import { complexQ } from "./helpers";

export const openExamPrepQuestions = [
  complexQ({
    id: "oep-001",
    module: "accounting",
    text: { en: "A consultant is configuring the chart of accounts for a new company. In Odoo 19, where are the accounts stored as a technical model?", fr: "Un consultant configure le plan comptable pour une nouvelle société. Dans Odoo 19, où les comptes sont-ils stockés en tant que modèle technique ?" },
    correct: { en: "account.account", fr: "account.account" },
    distractors: [
      { en: "account.chart", fr: "account.chart" },
      { en: "account.coa", fr: "account.coa" },
      { en: "res.account", fr: "res.account" },
    ],
    explanation: { en: "All accounts in Odoo's chart of accounts are records of the technical model account.account. Each account has a code, a name, an account type (e.g., Receivable, Payable, Income, Expense), and is scoped to a company in multi-company setups. The chart of accounts itself is just the collection of account.account records assigned to a company.\n\nWhy not \"account.chart\"? There is no account.chart model; the chart is the set of account.account records, not a separate object.\n\nWhy not \"account.coa\"? account.coa is not an Odoo model name; the correct technical name is account.account.\n\nWhy not \"res.account\"? res.* models are reserved for resources like users, partners, and companies — not accounts.", fr: "Tous les comptes du plan comptable sont des enregistrements du modèle technique account.account. Chaque compte possède un code, un nom, un type de compte (ex. : Créances, Dettes, Produits, Charges) et est rattaché à une société dans les configurations multi-sociétés. Le plan comptable est simplement la collection des enregistrements account.account attribués à une société." },
  }),
  complexQ({
    id: "oep-002",
    module: "accounting",
    text: { en: "In Odoo 19 Accounting, what is the correct sequence to record a customer payment that clears an outstanding invoice?", fr: "Dans Odoo 19 Comptabilité, quelle est la séquence correcte pour enregistrer un paiement client qui solde une facture en cours ?" },
    correct: { en: "Register Payment from the invoice", fr: "Enregistrer le paiement depuis la facture" },
    distractors: [
      { en: "Create a journal entry manually crediting the receivable account", fr: "Créer une écriture comptable manuellement en créditant le compte de créances" },
      { en: "Record the bank statement first, then create the invoice from the statement", fr: "Enregistrer d'abord le relevé bancaire, puis créer la facture à partir du relevé" },
      { en: "Validate the invoice, then mark it as Paid from the action menu", fr: "Valider la facture, puis la marquer comme Payée depuis le menu d'actions" },
    ],
    explanation: { en: "The standard flow is: post the invoice, click Register Payment (which creates a payment in an outstanding receipts account), then reconcile that payment with the bank statement line when the bank import arrives. This two-step approach correctly separates the moment cash is recorded from the moment it clears the bank, which matters for cash-basis reporting and bank reconciliation accuracy.\n\nWhy not \"Create a journal entry manually crediting the receivable account\"? Manual journal entries bypass the payment matching machinery and break the partner ledger and aged receivable reports.\n\nWhy not \"Record the bank statement first, then create the invoice from the statement\"? Creating an invoice from a statement line is possible but is the exception, not the rule, and does not reflect the standard order-to-cash flow.\n\nWhy not \"Validate the invoice, then mark it as Paid from the action menu\"? There is no 'Mark as Paid' action that bypasses the payment record; payments must be registered to update the GL.", fr: "Le flux standard est : valider la facture, cliquer sur Enregistrer le paiement (ce qui crée un paiement dans un compte d'encaissements en attente), puis lettrer ce paiement avec la ligne du relevé bancaire lorsque l'import bancaire arrive. Cette approche en deux étapes sépare correctement le moment où l'encaissement est enregistré de celui où il passe en banque." },
  }),
  complexQ({
    id: "oep-003",
    module: "accounting",
    text: { en: "Which Odoo 19 feature allows a company to apply different tax rates and accounts automatically based on the customer's country or state?", fr: "Quelle fonctionnalité d'Odoo 19 permet à une société d'appliquer automatiquement différents taux de taxe et comptes en fonction du pays ou de l'état du client ?" },
    correct: { en: "Fiscal positions", fr: "Les positions fiscales" },
    distractors: [
      { en: "Analytic accounting", fr: "La comptabilité analytique" },
      { en: "Tax groups", fr: "Les groupes de taxes" },
      { en: "Multi-currency", fr: "Le multi-devises" },
    ],
    explanation: { en: "Fiscal positions map default taxes and accounts to alternates based on rules such as the customer's country, state, or VAT status. For example, a fiscal position for EU B2B customers can replace domestic VAT with the reverse-charge tax and swap the income account to an intra-community sales account, automatically applied at quotation and invoice creation.\n\nWhy not \"Analytic accounting\"? Analytic accounting tracks cost centers and projects, not jurisdiction-based tax substitution.\n\nWhy not \"Tax groups\"? Tax groups aggregate taxes for reporting; they do not substitute taxes per customer.\n\nWhy not \"Multi-currency\"? Multi-currency handles currency conversion, not tax/account remapping by location.", fr: "Les positions fiscales associent les taxes et comptes par défaut à des alternatives en fonction de règles telles que le pays, l'état ou le statut TVA du client. Par exemple, une position fiscale pour les clients B2B de l'UE peut remplacer la TVA nationale par l'autoliquidation et changer le compte de produit en compte de ventes intracommunautaires." },
  }),
  complexQ({
    id: "oep-004",
    module: "accounting",
    text: { en: "A consultant must record monthly depreciation automatically for a fleet of vehicles. Which Odoo Enterprise application configures the depreciation schedule?", fr: "Un consultant doit enregistrer automatiquement l'amortissement mensuel d'une flotte de véhicules. Quelle application Odoo Enterprise configure le plan d'amortissement ?" },
    correct: { en: "Accounting > Assets", fr: "Comptabilité > Immobilisations" },
    distractors: [
      { en: "Inventory > Valuation Adjustments", fr: "Inventaire > Ajustements de valorisation" },
      { en: "Fleet > Depreciation", fr: "Parc automobile > Amortissement" },
      { en: "Manufacturing > Equipment", fr: "Fabrication > Équipements" },
    ],
    explanation: { en: "Odoo Enterprise Accounting provides an Asset Management feature under Accounting > Accounting > Management > Assets. You define an asset model with method (linear/degressive), duration, prorata, and journal, and Odoo posts the monthly depreciation entries automatically. Asset records can be created from vendor bills by linking the expense account to an asset model.\n\nWhy not \"Inventory > Valuation Adjustments\"? Inventory valuation adjustments handle stock value changes, not fixed asset depreciation.\n\nWhy not \"Fleet > Depreciation\"? Fleet tracks vehicles operationally (driver assignment, costs) but does not post depreciation entries.\n\nWhy not \"Manufacturing > Equipment\"? Manufacturing > Equipment relates to maintenance and OEE, not financial depreciation.", fr: "Odoo Enterprise Comptabilité fournit une fonctionnalité de gestion des immobilisations sous Comptabilité > Comptabilité > Gestion > Immobilisations. On définit un modèle d'immobilisation avec la méthode (linéaire/dégressive), la durée, le prorata et le journal, et Odoo comptabilise automatiquement les écritures d'amortissement mensuelles." },
  }),
  complexQ({
    id: "oep-005",
    module: "accounting",
    text: { en: "A consultant needs the Odoo 19 system to track expenses per project for profitability reporting. Which feature should be configured?", fr: "Un consultant a besoin que le système Odoo 19 suive les dépenses par projet pour le reporting de rentabilité. Quelle fonctionnalité doit être configurée ?" },
    correct: { en: "Analytic accounts and analytic distributions on journal items", fr: "Les comptes analytiques et les distributions analytiques sur les écritures comptables" },
    distractors: [
      { en: "Cost centers via product categories in Odoo 19", fr: "Les centres de coûts via les catégories de produits dans Odoo 19" },
      { en: "Multi-company consolidation", fr: "La consolidation multi-sociétés, qui est un paramètre distinct mais lié" },
      { en: "Tags on partners", fr: "Les étiquettes sur les contacts, qui ne sont pas la configuration pertinente ici" },
    ],
    explanation: { en: "Analytic accounting in Odoo lets you tag any journal item with one or more analytic accounts via an analytic distribution (percentages summing to 100%). The same expense can be split across departments, projects, or customers without affecting the GL. The Project app can auto-create an analytic account per project and post project costs and revenue to it for the profitability report.\n\nWhy not \"Cost centers via product categories in Odoo 19\"? Product categories drive stock valuation accounts, not flexible cost-center reporting.\n\nWhy not \"Multi-company consolidation\"? Multi-company consolidation aggregates several companies; it does not provide per-project tagging.\n\nWhy not \"Tags on partners\"? Partner tags help with marketing segmentation, not financial cost analysis.", fr: "La comptabilité analytique dans Odoo permet d'étiqueter toute écriture comptable avec un ou plusieurs comptes analytiques via une distribution analytique (pourcentages totalisant 100 %). La même charge peut être répartie entre départements, projets ou clients sans affecter le grand livre. L'application Projet peut créer automatiquement un compte analytique par projet." },
  }),
  complexQ({
    id: "oep-006",
    module: "accounting",
    text: { en: "In Odoo 19, what is the technical model name for journal entries (the document that contains debit and credit lines)?", fr: "Dans Odoo 19, quel est le nom technique du modèle pour les écritures comptables (le document qui contient les lignes de débit et crédit) ?" },
    correct: { en: "account.move", fr: "account.move" },
    distractors: [
      { en: "account.journal", fr: "account.journal" },
      { en: "account.entry", fr: "account.entry" },
      { en: "account.transaction", fr: "account.transaction" },
    ],
    explanation: { en: "account.move is the journal entry header in Odoo. Its lines are stored in account.move.line. Customer invoices, vendor bills, payments, and miscellaneous entries are all account.move records distinguished by the move_type field (out_invoice, in_invoice, out_refund, in_refund, entry).\n\nWhy not \"account.journal\"? account.journal is the journal definition (e.g., Sales, Purchase, Bank), not the entries.\n\nWhy not \"account.entry\"? account.entry is not a real Odoo model; the correct name is account.move.\n\nWhy not \"account.transaction\"? account.transaction is not the model used for journal entries.", fr: "account.move est l'en-tête de l'écriture comptable dans Odoo. Ses lignes sont stockées dans account.move.line. Les factures clients, factures fournisseur, paiements et écritures diverses sont tous des enregistrements account.move distingués par le champ move_type (out_invoice, in_invoice, out_refund, in_refund, entry)." },
  }),
  complexQ({
    id: "oep-007",
    module: "accounting",
    text: { en: "A multi-currency company in Odoo 19 sells in EUR but its main currency is USD. When an EUR invoice is posted, how does Odoo determine the USD amount on the GL?", fr: "Une société multi-devises dans Odoo 19 vend en EUR mais sa devise principale est l'USD. Lorsqu'une facture en EUR est validée, comment Odoo détermine-t-il le montant en USD dans le grand livre ?" },
    correct: { en: "Uses the exchange rate active on the invoice date from res.currency.rate", fr: "Utilise le taux de change actif à la date de la facture depuis res.currency.rate" },
    distractors: [
      { en: "Uses the rate from the company preference page only", fr: "Utilise le taux de la page de préférences de la société uniquement" },
      { en: "Always uses the rate at the moment of payment", fr: "Utilise toujours le taux au moment du paiement" },
      { en: "Forces the user to enter the rate manually", fr: "Oblige l'utilisateur à saisir le taux manuellement" },
    ],
    explanation: { en: "Odoo stores exchange rates as res.currency.rate records with effective dates. When a journal entry is posted, it looks up the most recent rate on or before the document date and converts foreign-currency amounts to the company currency for the GL columns (debit/credit). Rates can be updated manually or pulled from providers like ECB or Banxico via a scheduled action.\n\nWhy not \"Uses the rate from the company preference page only\"? There is no single rate on a 'company preference page'; rates are dated records on the currency.\n\nWhy not \"Always uses the rate at the moment of payment\"? Payment-date rates trigger an exchange-rate gain/loss entry separately; the invoice itself uses the invoice-date rate.\n\nWhy not \"Forces the user to enter the rate manually\"? The user is not forced to enter a rate manually if the rate table is populated.", fr: "Odoo stocke les taux de change sous forme d'enregistrements res.currency.rate avec des dates d'effet. Lorsqu'une écriture comptable est validée, il recherche le taux le plus récent à la date du document ou avant et convertit les montants en devise étrangère vers la devise de la société pour les colonnes du grand livre." },
  }),
  complexQ({
    id: "oep-008",
    module: "accounting",
    text: { en: "A consultant configures a Bank Journal in Odoo 19. What does the 'Outstanding Receipts Account' do?", fr: "Un consultant configure un journal bancaire dans Odoo 19. Que fait le « Compte d'encaissements en attente » ?" },
    correct: { en: "Holds customer payments before they are reconciled with a bank statement line", fr: "Conserve les paiements clients avant leur lettrage avec une ligne de relevé bancaire" },
    distractors: [
      { en: "Records bank fees automatically", fr: "Enregistre automatiquement les frais bancaires et appartient à une autre application Odoo" },
      { en: "Stores foreign exchange differences", fr: "Stocke les écarts de change" },
      { en: "Acts as the petty cash account", fr: "Agit comme le compte de petite caisse" },
    ],
    explanation: { en: "The Outstanding Receipts Account is an interim account used between Register Payment and bank reconciliation. When a customer payment is registered, it credits the receivable and debits Outstanding Receipts. When the bank statement line is reconciled with that payment, the entry transfers from Outstanding Receipts to the bank account. This separation is what enables the two-step payment flow.\n\nWhy not \"Records bank fees automatically\"? Bank fees are posted via a reconciliation model or manual line, not through Outstanding Receipts.\n\nWhy not \"Stores foreign exchange differences\"? FX differences are posted to dedicated unrealized/realized FX gain/loss accounts.\n\nWhy not \"Acts as the petty cash account\"? Petty cash uses a separate Cash journal, not Outstanding Receipts.", fr: "Le compte d'encaissements en attente est un compte transitoire utilisé entre l'enregistrement du paiement et le lettrage bancaire. Lorsqu'un paiement client est enregistré, il crédite le compte de créances et débite le compte d'encaissements en attente. Lors du lettrage de la ligne du relevé bancaire, l'écriture est transférée vers le compte bancaire." },
  }),
  complexQ({
    id: "oep-009",
    module: "accounting",
    text: { en: "Which Odoo 19 feature enables automatic reconciliation suggestions based on past matching patterns?", fr: "Quelle fonctionnalité d'Odoo 19 permet des suggestions de lettrage automatique basées sur les modèles de correspondance passés ?" },
    correct: { en: "Reconciliation models", fr: "Les modèles de lettrage" },
    distractors: [
      { en: "Automated payment terms", fr: "Les conditions de paiement automatisées" },
      { en: "Asset models", fr: "Les modèles d'immobilisations" },
      { en: "Tax adjustments", fr: "Les ajustements de taxes" },
    ],
    explanation: { en: "Reconciliation models in Accounting > Configuration > Banks > Reconciliation Models let you define rules that auto-match or auto-create entries on bank statement lines. Examples: 'If memo contains BANK FEE, post to account 6210', or 'If counterpart matches an open invoice, propose it as the match'. Odoo 19 leverages prior reconciliations to refine suggestions.\n\nWhy not \"Automated payment terms\"? Payment terms define due dates and installments, not bank matching rules.\n\nWhy not \"Asset models\"? Asset models drive depreciation, unrelated to bank reconciliation.\n\nWhy not \"Tax adjustments\"? Tax adjustments are manual corrections for tax reports, not reconciliation rules.", fr: "Les modèles de lettrage dans Comptabilité > Configuration > Banques > Modèles de lettrage permettent de définir des règles qui auto-lettrent ou auto-créent des écritures sur les lignes de relevé bancaire. Par exemple : « Si le mémo contient FRAIS BANCAIRE, imputer au compte 6210 »." },
  }),
  complexQ({
    id: "oep-010",
    module: "accounting",
    text: { en: "An accountant wants to lock all accounting entries before a specific date so they can no longer be modified. Where is this configured in Odoo 19?", fr: "Un comptable souhaite verrouiller toutes les écritures comptables avant une date spécifique pour qu'elles ne puissent plus être modifiées. Où cela se configure-t-il dans Odoo 19 ?" },
    correct: { en: "On the company under Accounting > Settings > Lock Date (Tax Lock + All Users Lock)", fr: "Sur la société dans Comptabilité > Paramètres > Date de verrouillage (Verrouillage fiscal + Verrouillage tous utilisateurs)" },
    distractors: [
      { en: "On each journal individually under Sequence Lock", fr: "Sur chaque journal individuellement sous Verrouillage de séquence" },
      { en: "By archiving the fiscal year on res.company", fr: "En archivant l'exercice fiscal sur res.company" },
      { en: "Only by removing user posting rights", fr: "Uniquement en retirant les droits de validation des utilisateurs" },
    ],
    explanation: { en: "Lock Dates are set on the company in Accounting > Settings. The 'Tax Return Lock Date' prevents changes to entries up to that date that would affect submitted tax returns; the 'Global Lock Date' (or 'All Users Lock') prevents any user — including advisors — from posting or modifying entries before that date. Both are essential for period closing integrity.\n\nWhy not \"On each journal individually under Sequence Lock\"? Lock dates are company-wide, not per journal.\n\nWhy not \"By archiving the fiscal year on res.company\"? Archiving a fiscal year is not how Odoo locks entries; the lock is a date on the company.\n\nWhy not \"Only by removing user posting rights\"? Removing posting rights is too broad and does not protect already-posted entries.", fr: "Les dates de verrouillage sont définies sur la société dans Comptabilité > Paramètres. La « Date de verrouillage de la déclaration de TVA » empêche les modifications d'écritures qui affecteraient les déclarations soumises ; la « Date de verrouillage globale » empêche tout utilisateur de modifier des écritures avant cette date." },
  }),
  complexQ({
    id: "oep-011",
    module: "accounting",
    text: { en: "What is the difference between a Customer Invoice (out_invoice) and a Vendor Bill (in_invoice) in Odoo 19?", fr: "Quelle est la différence entre une facture client (out_invoice) et une facture fournisseur (in_invoice) dans Odoo 19 ?" },
    correct: { en: "They are the same model with different move_type values", fr: "C'est le même modèle avec des valeurs move_type différentes" },
    distractors: [
      { en: "Invoices use account.move; bills use a different model called account.bill", fr: "Les factures utilisent account.move ; les factures fournisseur utilisent un modèle différent appelé account.bill" },
      { en: "Bills cannot have multiple lines", fr: "Les factures fournisseur ne peuvent pas avoir plusieurs lignes" },
      { en: "Customer invoices cannot reference taxes", fr: "Les factures clients ne peuvent pas référencer de taxes" },
    ],
    explanation: { en: "Both customer invoices and vendor bills are stored in account.move with different move_type values: out_invoice for customer invoices, in_invoice for vendor bills, out_refund/in_refund for credit notes. This unified model is why all invoice flows share the same posting, payment, and reconciliation logic.\n\nWhy not \"Invoices use account.move; bills use a different model called account.bill\"? There is no separate account.bill model; both are account.move records.\n\nWhy not \"Bills cannot have multiple lines\"? Bills can have many lines, just like invoices.\n\nWhy not \"Customer invoices cannot reference taxes\"? Customer invoices fully support taxes; that is one of their core uses.", fr: "Les factures clients et les factures fournisseur sont toutes stockées dans account.move avec des valeurs move_type différentes : out_invoice pour les factures clients, in_invoice pour les factures fournisseur, out_refund/in_refund pour les avoirs. Ce modèle unifié permet à tous les flux de facturation de partager la même logique de validation, paiement et lettrage." },
  }),
  complexQ({
    id: "oep-012",
    module: "accounting",
    text: { en: "A consultant needs to issue a credit note for a posted customer invoice in Odoo 19. Which option is the standard approach?", fr: "Un consultant doit émettre un avoir pour une facture client validée dans Odoo 19. Quelle option est l'approche standard ?" },
    correct: { en: "Delete the posted invoice and recreate it with corrected line amounts", fr: "Supprimer la facture validée et la recréer avec les montants de ligne corrigés" },
    distractors: [
      { en: "Credit Note action: partial, full refund, or full refund with new draft", fr: "Action Avoir : remboursement partiel, total ou total avec nouveau brouillon" },
      { en: "Post manual reversing journal entries without linking a credit note", fr: "Saisir des écritures de contrepassation manuelles sans lier d'avoir" },
      { en: "Reset posted invoice to draft and edit lines in place without reversal", fr: "Remettre la facture validée en brouillon et modifier les lignes en place sans contrepassation" },
    ],
    explanation: { en: "Posted invoices cannot be deleted. The Credit Note action presents three options: 1) Partial Refund creates an empty credit note for editing, 2) Full Refund posts a complete reversal automatically, 3) Full Refund and New Draft Invoice reverses the original and creates a new draft so you can correct and re-issue. Choice depends on whether you need a partial or full reversal.\n\nWhy not \"Credit Note action: partial, full refund, or full refund with new draft\"? Posted invoices cannot be deleted; this would also break the audit trail.\n\nWhy not \"Post manual reversing journal entries without linking a credit note\"? Manual reversal entries bypass the credit note linkage and break payment matching with the original.\n\nWhy not \"Reset posted invoice to draft and edit lines in place without reversal\"? Once posted with a sequence number, an invoice cannot be reset to draft without a Reset to Draft action that itself requires reversing it.", fr: "Les factures validées ne peuvent pas être supprimées. L'action Avoir présente trois options : 1) Remboursement partiel crée un avoir vide à modifier, 2) Remboursement total valide une contrepassation complète automatiquement, 3) Remboursement total et nouvelle facture brouillon contrepasse l'original et crée un nouveau brouillon pour correction." },
  }),
  complexQ({
    id: "oep-013",
    module: "accounting",
    text: { en: "Odoo 19 lets you import bank statements via OFX, QIF, CSV, or direct bank synchronization. Which feature enables real-time direct synchronization with banks?", fr: "Odoo 19 permet d'importer des relevés bancaires via OFX, QIF, CSV ou la synchronisation bancaire directe. Quelle fonctionnalité permet la synchronisation directe en temps réel avec les banques ?" },
    correct: { en: "Odoo Bank Sync (Plaid, Ponto, Yodlee, Salt Edge connectors)", fr: "Odoo Bank Sync (connecteurs Plaid, Ponto, Yodlee, Salt Edge)" },
    distractors: [
      { en: "FTP file watcher", fr: "Observateur de fichiers FTP, qui appartient à une autre application Odoo" },
      { en: "Odoo IAP webhook", fr: "Webhook Odoo IAP" },
      { en: "ICS feed", fr: "Flux ICS" },
    ],
    explanation: { en: "Odoo provides bank synchronization through partners like Plaid (US/CA), Ponto (EU), Yodlee, and Salt Edge. Once enabled in Accounting > Configuration > Online Synchronization, statements are pulled automatically on a schedule. Manual import via OFX/QIF/CSV remains available for banks not supported by these connectors.\n\nWhy not \"FTP file watcher\"? There is no built-in FTP watcher feature for bank statements in core Odoo.\n\nWhy not \"Odoo IAP webhook\"? IAP webhooks are not the bank sync mechanism; Bank Sync uses dedicated partner APIs.\n\nWhy not \"ICS feed\"? ICS is a calendar feed format, unrelated to banking.", fr: "Odoo fournit la synchronisation bancaire via des partenaires comme Plaid (US/CA), Ponto (UE), Yodlee et Salt Edge. Une fois activée dans Comptabilité > Configuration > Synchronisation en ligne, les relevés sont récupérés automatiquement selon un planning." },
  }),
  complexQ({
    id: "oep-014",
    module: "accounting",
    text: { en: "Which Odoo 19 report aggregates open customer balances by aging bucket (e.g., 0-30, 31-60, 61-90, 90+)?", fr: "Quel rapport Odoo 19 agrège les soldes clients ouverts par tranche d'ancienneté (ex. : 0-30, 31-60, 61-90, 90+) ?" },
    correct: { en: "Aged Receivable", fr: "Balance âgée clients" },
    distractors: [
      { en: "Partner Ledger", fr: "Livre des tiers" },
      { en: "Trial Balance", fr: "Balance des comptes" },
      { en: "General Ledger", fr: "Grand livre" },
    ],
    explanation: { en: "The Aged Receivable report under Accounting > Reporting groups outstanding customer balances into aging buckets so the AR team can prioritize collections. Aged Payable does the same for vendor balances. Both are standard Odoo Accounting reports with drill-down to source documents.\n\nWhy not \"Partner Ledger\"? Partner Ledger lists every entry per partner without bucketing by age.\n\nWhy not \"Trial Balance\"? Trial Balance lists account balances, not partner aging.\n\nWhy not \"General Ledger\"? General Ledger lists all journal items, not aged customer summaries.", fr: "Le rapport Balance âgée clients sous Comptabilité > Reporting regroupe les soldes clients impayés par tranches d'ancienneté afin que l'équipe de recouvrement puisse prioriser les relances. La Balance âgée fournisseurs fait de même pour les soldes fournisseurs." },
  }),
  complexQ({
    id: "oep-015",
    module: "accounting",
    text: { en: "A consultant configures a payment term '30% advance, 70% net 60'. How does Odoo 19 split this on a posted invoice?", fr: "Un consultant configure une condition de paiement « 30 % d'acompte, 70 % net 60 ». Comment Odoo 19 répartit-il cela sur une facture validée ?" },
    correct: { en: "Two account.move.line records on the receivable account, each with its own due date", fr: "Deux enregistrements account.move.line sur le compte de créances, chacun avec sa propre date d'échéance" },
    distractors: [
      { en: "Two separate invoices linked together", fr: "Deux factures séparées liées entre elles" },
      { en: "A single line with a custom due date formula", fr: "Une seule ligne avec une formule de date d'échéance personnalisée" },
      { en: "It is not possible without an addon", fr: "Ce n'est pas possible sans un module complémentaire" },
    ],
    explanation: { en: "Payment terms with multiple lines generate multiple receivable lines on the same account.move. Each line has its own date_maturity, so the Aged Receivable report shows each portion in the correct bucket. The total still equals the invoice total. This is native functionality, not requiring any addon.\n\nWhy not \"Two separate invoices linked together\"? It is one invoice with multiple receivable lines, not two invoices.\n\nWhy not \"A single line with a custom due date formula\"? A formula on a single line cannot capture two different due dates.\n\nWhy not \"It is not possible without an addon\"? Multi-line payment terms are core Accounting functionality.", fr: "Les conditions de paiement avec plusieurs lignes génèrent plusieurs lignes de créances sur le même account.move. Chaque ligne a sa propre date d'échéance (date_maturity), de sorte que le rapport de balance âgée affiche chaque portion dans la bonne tranche." },
  }),
  complexQ({
    id: "oep-016",
    module: "accounting",
    text: { en: "Odoo 19 supports e-invoicing standards such as Peppol BIS Billing 3.0, Factur-X, and country-specific EDI. Where is the e-invoicing format selected for a partner?", fr: "Odoo 19 prend en charge les normes de facturation électronique telles que Peppol BIS Billing 3.0, Factur-X et l'EDI spécifique par pays. Où le format de facturation électronique est-il sélectionné pour un partenaire ?" },
    correct: { en: "On the partner's Accounting tab as Electronic Invoicing format", fr: "Sur l'onglet Comptabilité du partenaire en tant que format de facturation électronique" },
    distractors: [
      { en: "On every invoice manually before posting", fr: "Sur chaque facture manuellement avant validation" },
      { en: "Globally for the entire database in General Settings only", fr: "Globalement pour toute la base de données dans les Paramètres généraux uniquement" },
      { en: "Only on the company record", fr: "Uniquement sur la fiche société" },
    ],
    explanation: { en: "Each partner has an Accounting tab where the appropriate Electronic Invoicing formats are selected (e.g., Peppol BIS Billing 3.0, Factur-X, French Chorus Pro, Italian FatturaPA). When an invoice is posted to that partner, Odoo attaches the correct XML and routes it via Peppol or the country EDI gateway. Country-specific localizations install the right formats automatically.\n\nWhy not \"On every invoice manually before posting\"? Setting per invoice would defeat automation; the format is configured per partner.\n\nWhy not \"Globally for the entire database in General Settings only\"? There are global toggles, but the per-partner format selection is what determines which XML is produced.\n\nWhy not \"Only on the company record\"? The company record holds sender configuration, not the recipient's format preference.", fr: "Chaque partenaire possède un onglet Comptabilité où les formats de facturation électronique appropriés sont sélectionnés (ex. : Peppol BIS Billing 3.0, Factur-X, Chorus Pro). Lorsqu'une facture est validée pour ce partenaire, Odoo joint le bon XML et l'achemine via Peppol ou la passerelle EDI du pays." },
  }),
  complexQ({
    id: "oep-017",
    module: "accounting",
    text: { en: "In Odoo 19, what does the 'Tax Grids' configuration control on a tax record?", fr: "Dans Odoo 19, que contrôle la configuration « Grilles de taxes » sur un enregistrement de taxe ?" },
    correct: { en: "Visual grid layout designer for customizing form view column widths", fr: "Le concepteur visuel de disposition en grille pour personnaliser les largeurs de colonnes de la vue formulaire" },
    distractors: [
      { en: "Tax grid boxes receiving base/tax amounts on statutory return forms", fr: "Les cases de la grille fiscale recevant les montants de base/taxe sur les formulaires de déclaration légale" },
      { en: "Country list controlling where a tax rate may appear on invoices", fr: "La liste des pays contrôlant où un taux de taxe peut apparaître sur les factures" },
      { en: "Customer PDF grouping of tax lines on printed sales documents", fr: "Le regroupement PDF client des lignes de taxe sur les documents de vente imprimés" },
    ],
    explanation: { en: "Tax Grids map a tax's base and tax amounts to specific boxes on the official tax return. For each tax, you assign grids for invoices and refunds (positive and negative side). When you run the Tax Report, Odoo aggregates entries by grid to populate the official return form. Localizations ship with country-specific grids matching the legal tax form.\n\nWhy not \"Tax grid boxes receiving base/tax amounts on statutory return forms\"? Tax Grids are an accounting concept, not a UI grid.\n\nWhy not \"Country list controlling where a tax rate may appear on invoices\"? Country applicability is set via fiscal positions, not tax grids.\n\nWhy not \"Customer PDF grouping of tax lines on printed sales documents\"? Document grouping uses Tax Groups, not Tax Grids.", fr: "Les grilles de taxes associent les montants de base et de taxe à des cases spécifiques de la déclaration fiscale officielle. Pour chaque taxe, on assigne des grilles pour les factures et les avoirs (côté positif et négatif). Lorsque vous exécutez le rapport de taxe, Odoo agrège les écritures par grille pour remplir le formulaire de déclaration officiel." },
  }),
  complexQ({
    id: "oep-018",
    module: "crm",
    text: { en: "A consultant must configure recurring monthly billing for a SaaS subscription. Which Odoo 19 application is purpose-built for this?", fr: "Un consultant doit configurer la facturation récurrente mensuelle pour un abonnement SaaS. Quelle application Odoo 19 est spécialement conçue pour cela ?" },
    correct: { en: "Subscriptions", fr: "Abonnements" },
    distractors: [
      { en: "Sales", fr: "Ventes" },
      { en: "Invoicing recurring template", fr: "Modèle récurrent de facturation" },
      { en: "Helpdesk", fr: "Helpdesk" },
    ],
    explanation: { en: "The Subscriptions app (Enterprise) manages the full subscription lifecycle: recurring plans, MRR/ARR tracking, churn analysis, prorations, upsells, and automated invoicing/payment retries. A subscription is a sale.order with a plan, and Odoo creates invoices on schedule. Sales orders in the base Sales app do not have recurring logic on their own.\n\nWhy not \"Sales\"? Sales handles one-off orders; recurring billing requires Subscriptions.\n\nWhy not \"Invoicing recurring template\"? There is no generic 'Invoicing recurring template' — the proper module is Subscriptions.\n\nWhy not \"Helpdesk\"? Helpdesk is for support tickets, not billing.", fr: "L'application Abonnements (Enterprise) gère le cycle de vie complet de l'abonnement : plans récurrents, suivi MRR/ARR, analyse du taux de désabonnement, prorata, ventes additionnelles et facturation/relance de paiement automatisées. Un abonnement est un sale.order avec un plan, et Odoo crée les factures selon le planning." },
  }),
  complexQ({
    id: "oep-019",
    module: "crm",
    text: { en: "In Odoo 19 CRM, what is the difference between a Lead and an Opportunity?", fr: "Dans Odoo 19 CRM, quelle est la différence entre une piste et une opportunité ?" },
    correct: { en: "A Lead is an unqualified contact request", fr: "Une piste est une demande de contact non qualifiée" },
    distractors: [
      { en: "A Lead has no monetary value; an Opportunity always has a closed deal", fr: "Une piste n'a pas de valeur monétaire ; une opportunité a toujours une affaire conclue" },
      { en: "Leads are stored on res.partner; Opportunities are stored on crm.opportunity", fr: "Les pistes sont stockées sur res.partner ; les opportunités sont stockées sur crm.opportunity" },
      { en: "Leads are restricted to website forms only", fr: "Les pistes sont limitées aux formulaires du site web uniquement" },
    ],
    explanation: { en: "Both are stored on the same crm.lead model with type='lead' or type='opportunity'. The Lead stage represents an early, unqualified inquiry that may or may not convert. Once qualified (interest confirmed, budget identified), it is converted to an Opportunity that progresses through pipeline stages toward a Won/Lost outcome. The Lead step can be disabled in CRM settings if the team starts directly at Opportunity.\n\nWhy not \"A Lead has no monetary value; an Opportunity always has a closed deal\"? Opportunities are not always closed deals — they can be Won or Lost; both have monetary values.\n\nWhy not \"Leads are stored on res.partner; Opportunities are stored on crm.opportunity\"? There is no separate crm.opportunity model; both share crm.lead.\n\nWhy not \"Leads are restricted to website forms only\"? Leads can come from any source: import, web form, email alias, or manual entry.", fr: "Les deux sont stockées sur le même modèle crm.lead avec type='lead' ou type='opportunity'. L'étape Piste représente une demande précoce et non qualifiée qui peut ou non se convertir. Une fois qualifiée (intérêt confirmé, budget identifié), elle est convertie en opportunité qui progresse dans les étapes du pipeline vers un résultat Gagné/Perdu." },
  }),
  complexQ({
    id: "oep-020",
    module: "crm",
    text: { en: "In Odoo 19 Sales, which feature allows different prices to apply automatically based on customer segment, quantity, or date?", fr: "Dans Odoo 19 Ventes, quelle fonctionnalité permet d'appliquer automatiquement différents prix en fonction du segment client, de la quantité ou de la date ?" },
    correct: { en: "Pricelists", fr: "Les listes de prix" },
    distractors: [
      { en: "Discount rules on partners", fr: "Les règles de remise sur les partenaires" },
      { en: "Promotions only", fr: "Les promotions uniquement" },
      { en: "Tax adjustments", fr: "Les ajustements de taxes" },
    ],
    explanation: { en: "Pricelists are the configurable engine for dynamic pricing. A pricelist contains rules that apply discounts or set fixed prices based on product category, specific products, quantity tiers, validity dates, and chained pricelists. Each customer can have a default pricelist; the order's pricelist drives quotation and SO unit prices.\n\nWhy not \"Discount rules on partners\"? There is no 'discount rule' feature on partners separate from pricelists.\n\nWhy not \"Promotions only\"? Promotions (eCommerce coupons) are different from B2B pricing logic and apply at checkout.\n\nWhy not \"Tax adjustments\"? Tax adjustments do not change prices; they change tax computation.", fr: "Les listes de prix sont le moteur configurable pour la tarification dynamique. Une liste de prix contient des règles qui appliquent des remises ou fixent des prix en fonction de la catégorie de produit, des produits spécifiques, des paliers de quantité, des dates de validité et des listes de prix chaînées." },
  }),
  complexQ({
    id: "oep-021",
    module: "crm",
    text: { en: "What happens in Odoo 19 when a salesperson sends a quotation by email to the customer using the 'Send by Email' button?", fr: "Que se passe-t-il dans Odoo 19 lorsqu'un commercial envoie un devis par e-mail au client en utilisant le bouton « Envoyer par e-mail » ?" },
    correct: { en: "Quotation locks permanently and blocks all further line edits", fr: "Le devis est verrouillé définitivement et bloque toute modification ultérieure des lignes" },
    distractors: [
      { en: "Email queued; quote moves to Quotation Sent with portal link included", fr: "L'e-mail est mis en file d'attente ; le devis passe à Devis envoyé avec un lien portail inclus" },
      { en: "Customer auto-provisioned as internal website user with full ACL rights", fr: "Le client est automatiquement provisionné comme utilisateur interne du site web avec tous les droits ACL" },
      { en: "Quotation auto-confirms to sales order without customer interaction", fr: "Le devis se confirme automatiquement en bon de commande sans interaction du client" },
    ],
    explanation: { en: "Send by Email queues an email containing a portal link where the customer can review the quote, sign it (if e-signature is enabled), pay a deposit (if online payment is configured), and confirm. The quotation state transitions to 'Quotation Sent'. It can still be edited, and the customer's actions update the same record.\n\nWhy not \"Email queued; quote moves to Quotation Sent with portal link included\"? Quotations remain editable in Sent state; they only lock on confirmation if 'Lock Confirmed Sales' is enabled.\n\nWhy not \"Customer auto-provisioned as internal website user with full ACL rights\"? The customer does not auto-become a website user; they receive a token-based portal link.\n\nWhy not \"Quotation auto-confirms to sales order without customer interaction\"? Conversion to a sales order happens only when the customer clicks Sign/Confirm or the salesperson clicks Confirm.", fr: "Envoyer par e-mail met en file d'attente un e-mail contenant un lien portail où le client peut consulter le devis, le signer (si la signature électronique est activée), payer un acompte (si le paiement en ligne est configuré) et confirmer. Le statut du devis passe à « Devis envoyé ». Il peut encore être modifié." },
  }),
  complexQ({
    id: "oep-022",
    module: "crm",
    text: { en: "A salesperson wants the customer to e-sign the quotation online before it is confirmed. What must be enabled in Odoo 19 Sales settings?", fr: "Un commercial veut que le client signe électroniquement le devis en ligne avant sa confirmation. Que doit être activé dans les paramètres Odoo 19 Ventes ?" },
    correct: { en: "Online Signature in Sales > Configuration > Settings > Quotations & Orders", fr: "Signature en ligne dans Ventes > Configuration > Paramètres > Devis et commandes" },
    distractors: [
      { en: "Online Payment only in Odoo 19", fr: "Paiement en ligne uniquement dans Odoo 19" },
      { en: "Sign module replacement", fr: "Remplacement du module Sign" },
      { en: "Fleet integration", fr: "Intégration Parc automobile" },
    ],
    explanation: { en: "In Sales > Configuration > Settings, enabling 'Online Signature' adds a Sign button on the customer portal page for quotations. The customer types or draws their signature and the quote auto-converts to a confirmed sales order with the signature stored for audit. Online Payment is a separate adjacent option for collecting a deposit at signing.\n\nWhy not \"Online Payment only in Odoo 19\"? Online Payment lets them pay; signing is its own toggle.\n\nWhy not \"Sign module replacement\"? The Sign app is for general document signing flows, not the quotation portal toggle.\n\nWhy not \"Fleet integration\"? Fleet is unrelated to quotations.", fr: "Dans Ventes > Configuration > Paramètres, l'activation de « Signature en ligne » ajoute un bouton Signer sur la page du portail client pour les devis. Le client tape ou dessine sa signature et le devis se convertit automatiquement en bon de commande confirmé avec la signature conservée pour l'audit." },
  }),
  complexQ({
    id: "oep-023",
    module: "crm",
    text: { en: "How does Odoo 19 model the difference between a product template and a product variant?", fr: "Comment Odoo 19 modélise-t-il la différence entre un modèle de produit et une variante de produit ?" },
    correct: { en: "product.template holds shared attributes", fr: "product.template contient les attributs partagés" },
    distractors: [
      { en: "Both are the same model; variants are just tags", fr: "Les deux sont le même modèle ; les variantes sont juste des étiquettes" },
      { en: "Variants are stored as separate templates", fr: "Les variantes sont stockées comme des modèles séparés" },
      { en: "Variants only exist in eCommerce", fr: "Les variantes n'existent que dans l'eCommerce" },
    ],
    explanation: { en: "product.template is the shared definition (name, category, taxes, type). When attributes such as Color and Size are added to the template with values, Odoo generates one product.product per combination. Internal references, barcodes, prices, and stock levels can differ per variant. This template/variant split is core to all Odoo apps that use products.\n\nWhy not \"Both are the same model; variants are just tags\"? Templates and variants are different models with a clear parent/child relationship.\n\nWhy not \"Variants are stored as separate templates\"? Variants are not separate templates; one template owns its variants.\n\nWhy not \"Variants only exist in eCommerce\"? Variants are used everywhere products are: Sales, Purchase, Inventory, MRP, POS, eCommerce.", fr: "product.template est la définition partagée (nom, catégorie, taxes, type). Lorsque des attributs comme Couleur et Taille sont ajoutés au modèle avec des valeurs, Odoo génère un product.product par combinaison. Les références internes, codes-barres, prix et niveaux de stock peuvent différer par variante." },
  }),
  complexQ({
    id: "oep-024",
    module: "crm",
    text: { en: "A sales manager wants automatic round-robin assignment of new leads to a team. Where is this configured in Odoo 19?", fr: "Un directeur commercial veut l'attribution automatique en tourniquet des nouvelles pistes à une équipe. Où cela se configure-t-il dans Odoo 19 ?" },
    correct: { en: "On the Sales Team (crm.team) with assignment rules and members", fr: "Sur l'équipe commerciale (crm.team) avec les règles d'attribution et les membres" },
    distractors: [
      { en: "On res.users in Odoo 19", fr: "Sur res.users dans Odoo 19" },
      { en: "Only via Studio automated actions", fr: "Uniquement via des actions automatisées Studio" },
      { en: "It must be done in code", fr: "Cela doit être fait en code" },
    ],
    explanation: { en: "Sales Teams (crm.team) define members, assignment rules (domain filter), and assignment frequency. Lead Assignment can be configured as Manual or Automated; with automated rules, leads matching the filter are distributed across team members based on their max-leads capacity. This is a standard CRM Enterprise feature, no code or Studio required.\n\nWhy not \"On res.users in Odoo 19\"? User records do not control team assignment rules.\n\nWhy not \"Only via Studio automated actions\"? Studio automations can assign records but are not the standard or required tool here.\n\nWhy not \"It must be done in code\"? No code is needed; Sales Team configuration handles it.", fr: "Les équipes commerciales (crm.team) définissent les membres, les règles d'attribution (filtre de domaine) et la fréquence d'attribution. L'attribution des pistes peut être configurée en Manuel ou Automatisé ; avec les règles automatisées, les pistes correspondant au filtre sont distribuées entre les membres selon leur capacité maximale de pistes." },
  }),
  complexQ({
    id: "oep-025",
    module: "crm",
    text: { en: "What is an Optional Product on a quotation in Odoo 19?", fr: "Qu'est-ce qu'un produit optionnel sur un devis dans Odoo 19 ?" },
    correct: { en: "A suggested add-on shown on the customer portal that they can add with one click", fr: "Un complément suggéré affiché sur le portail client que le client peut ajouter en un clic" },
    distractors: [
      { en: "A product that is automatically added to every quote", fr: "Un produit automatiquement ajouté à chaque devis" },
      { en: "A free sample required by law", fr: "Un échantillon gratuit exigé par la loi" },
      { en: "A product that cannot be invoiced", fr: "Un produit qui ne peut pas être facturé" },
    ],
    explanation: { en: "Optional Products are upsell suggestions attached to a quotation line. On the customer portal, the customer sees them with an Add button. This is a low-friction upsell tool — a customer reviewing a laptop quote can self-add a warranty or carrying case without contacting sales. The salesperson can also configure default optional products on the product itself.\n\nWhy not \"A product that is automatically added to every quote\"? They are not auto-added; the customer must opt in.\n\nWhy not \"A free sample required by law\"? There is no legal-sample concept in Odoo Sales.\n\nWhy not \"A product that cannot be invoiced\"? Optional products, once added, are normal lines that can be invoiced.", fr: "Les produits optionnels sont des suggestions de vente additionnelle attachées à une ligne de devis. Sur le portail client, le client les voit avec un bouton Ajouter. C'est un outil de vente additionnelle à faible friction — un client consultant un devis pour un ordinateur portable peut ajouter lui-même une garantie ou un étui de transport." },
  }),
  complexQ({
    id: "oep-026",
    module: "crm",
    text: { en: "Odoo 19 introduced enhanced AI-assisted features in CRM. Which AI capability helps salespeople write follow-up emails or summarize opportunities?", fr: "Odoo 19 a introduit des fonctionnalités améliorées d'IA dans le CRM. Quelle capacité IA aide les commerciaux à rédiger des e-mails de suivi ou à résumer des opportunités ?" },
    correct: { en: "AI assistant integration in CRM (notes/email composition)", fr: "Intégration d'un assistant IA dans le CRM (composition de notes/e-mails)" },
    distractors: [
      { en: "The Knowledge wiki in Odoo 19", fr: "Le wiki Knowledge dans Odoo 19" },
      { en: "The Discuss app channel", fr: "L'application Discuss, qui appartient à une autre application Odoo" },
      { en: "The Sign module", fr: "Le module Sign" },
    ],
    explanation: { en: "Odoo 19 integrates AI-assisted writing in the chatter and email composer in CRM and other apps, helping users draft replies, summarize long opportunity histories, and rewrite messages. This is part of Odoo's expansion of AI-assisted productivity features in the 19 release. Configuration of AI access is done in General Settings.\n\nWhy not \"The Knowledge wiki in Odoo 19\"? Knowledge stores wiki articles but is not a writing assistant in CRM.\n\nWhy not \"The Discuss app channel\"? Discuss is a chat tool, not an AI generator (though AI features can be added).\n\nWhy not \"The Sign module\"? Sign handles signatures, not AI text generation.", fr: "Odoo 19 intègre la rédaction assistée par IA dans le chatter et le compositeur d'e-mails du CRM et d'autres applications, aidant les utilisateurs à rédiger des réponses, résumer de longs historiques d'opportunités et reformuler des messages. La configuration de l'accès IA se fait dans les Paramètres généraux." },
  }),
  complexQ({
    id: "oep-027",
    module: "crm",
    text: { en: "In Odoo 19 Sales, what does it mean when a quotation is set to 'Lock Confirmed Sales' (Lock Sales Orders) in the company settings?", fr: "Dans Odoo 19 Ventes, que signifie le paramètre « Verrouiller les commandes confirmées » dans les paramètres de la société ?" },
    correct: { en: "Confirmed orders can no longer be edited and need a new revision to change", fr: "Les commandes confirmées ne peuvent plus être modifiées et nécessitent une nouvelle révision pour être changées" },
    distractors: [
      { en: "Customers cannot view confirmed orders", fr: "Les clients ne peuvent pas voir les commandes confirmées" },
      { en: "Orders cannot be cancelled", fr: "Les commandes ne peuvent pas être annulées" },
      { en: "Orders cannot be invoiced", fr: "Les commandes ne peuvent pas être facturées" },
    ],
    explanation: { en: "Lock Confirmed Sales prevents accidental edits to confirmed sales orders. To change quantities or pricing, the salesperson must explicitly unlock or create a new sales order. This is a control aimed at preserving the customer-confirmed state of an order, especially important when integrated with manufacturing or shipping.\n\nWhy not \"Customers cannot view confirmed orders\"? Customers can still see their confirmed orders in the portal.\n\nWhy not \"Orders cannot be cancelled\"? Cancellation is a separate workflow not affected by the lock.\n\nWhy not \"Orders cannot be invoiced\"? Locked orders are still invoiceable.", fr: "Le verrouillage des commandes confirmées empêche les modifications accidentelles des bons de commande confirmés. Pour modifier les quantités ou les prix, le commercial doit explicitement déverrouiller ou créer un nouveau bon de commande. Ce contrôle vise à préserver l'état confirmé par le client." },
  }),
  complexQ({
    id: "oep-028",
    module: "crm",
    text: { en: "A sales rep notices the same customer keeps creating duplicate leads via the website form. Which Odoo 19 CRM feature handles automatic duplicate detection?", fr: "Un commercial remarque que le même client crée des pistes en double via le formulaire du site web. Quelle fonctionnalité CRM d'Odoo 19 gère la détection automatique des doublons ?" },
    correct: { en: "Lead duplicate detection (merge suggestions in CRM)", fr: "Détection de pistes en double (suggestions de fusion dans le CRM)" },
    distractors: [
      { en: "Mass mailing", fr: "Le publipostage de masse, qui appartient à une autre application Odoo" },
      { en: "The Knowledge module", fr: "Le module Knowledge" },
      { en: "Sign module", fr: "Le module Sign" },
    ],
    explanation: { en: "Odoo CRM detects probable duplicates by matching email or phone and shows a 'Similar Leads' button on the lead form, allowing the salesperson to merge them. The merged lead consolidates messages, activities, and partner links. This is critical because duplicate leads inflate pipeline numbers and confuse outreach.\n\nWhy not \"Mass mailing\"? Mass mailing sends emails; it does not detect duplicates.\n\nWhy not \"The Knowledge module\"? Knowledge stores wiki articles, unrelated to leads.\n\nWhy not \"Sign module\"? Sign manages e-signatures on documents; it does not detect duplicate CRM leads by email or phone.", fr: "Le CRM Odoo détecte les doublons probables en comparant l'e-mail ou le téléphone et affiche un bouton « Pistes similaires » sur le formulaire de la piste, permettant au commercial de les fusionner. La piste fusionnée consolide les messages, activités et liens partenaires." },
  }),
  complexQ({
    id: "oep-029",
    module: "inventory",
    text: { en: "In Odoo 19 Inventory, what is the technical model for a transfer document like a delivery order, receipt, or internal transfer?", fr: "Dans Odoo 19 Inventaire, quel est le modèle technique pour un document de transfert comme un bon de livraison, une réception ou un transfert interne ?" },
    correct: { en: "stock.picking", fr: "stock.picking" },
    distractors: [
      { en: "stock.transfer", fr: "stock.transfer" },
      { en: "stock.move.delivery", fr: "stock.move.delivery" },
      { en: "stock.warehouse.move", fr: "stock.warehouse.move" },
    ],
    explanation: { en: "stock.picking is the parent document for any stock transfer. Each picking has a picking_type_id (Receipts, Delivery Orders, Internal, MO transfers, etc.) and lines stored in stock.move and stock.move.line. The state field tracks the picking through Draft → Waiting → Ready → Done.\n\nWhy not \"stock.transfer\"? stock.transfer is not the canonical model name.\n\nWhy not \"stock.move.delivery\"? stock.move.delivery is invented.\n\nWhy not \"stock.warehouse.move\"? stock.warehouse.move is not a real Odoo model.", fr: "stock.picking est le document parent pour tout transfert de stock. Chaque picking a un picking_type_id (Réceptions, Bons de livraison, Internes, transferts OF, etc.) et des lignes stockées dans stock.move et stock.move.line. Le champ state suit le picking à travers Brouillon → En attente → Prêt → Fait." },
  }),
  complexQ({
    id: "oep-030",
    module: "inventory",
    text: { en: "A consultant configures inventory valuation in Odoo 19. Which method recalculates unit cost as a weighted average after each incoming shipment?", fr: "Un consultant configure la valorisation des stocks dans Odoo 19. Quelle méthode recalcule le coût unitaire en moyenne pondérée après chaque réception ?" },
    correct: { en: "AVCO (Average Cost)", fr: "CMUP (Coût Moyen Unitaire Pondéré)" },
    distractors: [
      { en: "Standard Price", fr: "Prix standard" },
      { en: "FIFO (First In, First Out)", fr: "FIFO (Premier Entré, Premier Sorti)" },
      { en: "LIFO (Last In, First Out)", fr: "LIFO (Dernier Entré, Premier Sorti)" },
    ],
    explanation: { en: "AVCO (Average Cost) recalculates the average unit cost after each receipt: (current_qty × current_cost + new_qty × new_cost) ÷ (current_qty + new_qty). FIFO consumes oldest cost layers first. Standard Price keeps a manually maintained fixed cost. Odoo does not natively support LIFO because most accounting standards (IFRS) prohibit it.\n\nWhy not \"Standard Price\"? Standard Price uses a manually defined fixed cost, not a recalculated average.\n\nWhy not \"FIFO (First In, First Out)\"? FIFO consumes oldest layers first; the cost reflects whichever layer was purchased first.\n\nWhy not \"LIFO (Last In, First Out)\"? LIFO is not natively supported in standard Odoo.", fr: "Le CMUP (AVCO) recalcule le coût unitaire moyen après chaque réception : (qté_actuelle × coût_actuel + nouvelle_qté × nouveau_coût) ÷ (qté_actuelle + nouvelle_qté). Le FIFO consomme les couches les plus anciennes en premier. Le prix standard maintient un coût fixe défini manuellement. Odoo ne supporte pas nativement le LIFO car la plupart des normes comptables (IFRS) l'interdisent." },
  }),
  complexQ({
    id: "oep-031",
    module: "inventory",
    text: { en: "A warehouse uses lots to track expiration dates on pharmaceutical inventory. Which Inventory setting must be enabled?", fr: "Un entrepôt utilise des lots pour suivre les dates d'expiration des stocks pharmaceutiques. Quel paramètre d'Inventaire doit être activé ?" },
    correct: { en: "Enable multi-step routes only without any lot or serial traceability", fr: "Activer les routes multi-étapes uniquement sans aucune traçabilité par lot ou numéro de série" },
    distractors: [
      { en: "Enable Lots & Serial Numbers, then expiration dates on tracked products", fr: "Activer Lots et numéros de série, puis les dates d'expiration sur les produits suivis" },
      { en: "Configure putaway rules directing pallets to cold-storage sub-locations", fr: "Configurer les règles de rangement dirigeant les palettes vers des sous-emplacements de stockage froid" },
      { en: "Define storage categories restricting hazardous goods to specific bins", fr: "Définir des catégories de stockage restreignant les marchandises dangereuses à des casiers spécifiques" },
    ],
    explanation: { en: "Enable 'Lots & Serial Numbers' in Inventory > Settings > Traceability. Then on each tracked product, set Tracking to 'By Lots' and enable 'Expiration Date'. Each lot then carries best-before, expiration, removal, and alert dates. Odoo 19 will warn or block movements of expired lots based on settings, and FEFO removal can be configured to consume the closest-to-expire lot first.\n\nWhy not \"Enable Lots & Serial Numbers, then expiration dates on tracked products\"? Multi-step routes determine flow steps, not lot tracking.\n\nWhy not \"Configure putaway rules directing pallets to cold-storage sub-locations\"? Putaway rules direct stock to specific locations on receipt; they do not enable lot tracking.\n\nWhy not \"Define storage categories restricting hazardous goods to specific bins\"? Storage categories restrict what products can go in which sub-locations; not lot tracking.", fr: "Activer « Lots et numéros de série » dans Inventaire > Paramètres > Traçabilité. Puis sur chaque produit suivi, définir le suivi sur « Par lots » et activer « Date d'expiration ». Chaque lot porte alors des dates de péremption, d'expiration, de retrait et d'alerte. Odoo 19 avertira ou bloquera les mouvements de lots expirés." },
  }),
  complexQ({
    id: "oep-032",
    module: "inventory",
    text: { en: "What is the difference between Make-to-Stock (MTS) and Make-to-Order (MTO) routes in Odoo 19?", fr: "Quelle est la différence entre les routes Fabrication sur stock (MTS) et Fabrication à la commande (MTO) dans Odoo 19 ?" },
    correct: { en: "MTS holds stock and reserves from on-hand inventory", fr: "MTS conserve du stock et réserve à partir de l'inventaire disponible" },
    distractors: [
      { en: "MTS produces or buys goods on demand for each sale; MTO holds inventory and reserves from stock", fr: "MTS produit ou achète des biens à la demande pour chaque vente ; MTO conserve l'inventaire et réserve depuis le stock" },
      { en: "They are synonyms", fr: "Ce sont des synonymes" },
      { en: "MTO only applies to services", fr: "MTO ne s'applique qu'aux services" },
    ],
    explanation: { en: "MTS (default) reserves goods from existing stock and replenishes via reordering rules. MTO chains a procurement directly to the sales order: for each SO line, Odoo creates an RFQ or MO linked to that line. MTO is suited for high-cost or customizable items where you want zero generic inventory; MTS is for fast-moving goods where availability matters more than per-order linkage.\n\nWhy not \"MTS produces or buys goods on demand for each sale; MTO holds inventory and reserves from stock\"? The definitions are swapped in this option.\n\nWhy not \"They are synonyms\"? They are opposite strategies, not synonyms.\n\nWhy not \"MTO only applies to services\"? Services are not stocked; MTS/MTO apply to stockable products.", fr: "MTS (par défaut) réserve les marchandises depuis le stock existant et réapprovisionne via des règles de réapprovisionnement. MTO chaîne un approvisionnement directement à la commande client : pour chaque ligne de commande, Odoo crée une demande de prix ou un ordre de fabrication lié à cette ligne." },
  }),
  complexQ({
    id: "oep-033",
    module: "inventory",
    text: { en: "Reordering rules in Odoo 19 trigger procurement when stock falls below a minimum. What are the two key fields on a reordering rule?", fr: "Les règles de réapprovisionnement dans Odoo 19 déclenchent l'approvisionnement lorsque le stock tombe en dessous d'un minimum. Quels sont les deux champs clés d'une règle de réapprovisionnement ?" },
    correct: { en: "Min Quantity and Max Quantity", fr: "Quantité minimum et Quantité maximum" },
    distractors: [
      { en: "Cost and Price", fr: "Coût et prix" },
      { en: "Lead Time and Customer", fr: "Délai de livraison et client" },
      { en: "Lot Size and Tolerance", fr: "Taille de lot et tolérance" },
    ],
    explanation: { en: "A reordering rule has Min Quantity (the trigger threshold) and Max Quantity (the target stock level). When forecasted stock at the rule's location drops below Min, Odoo creates a procurement to bring stock back to Max. Multiple of (lot multiple) and lead time defaults from the supplier or BoM round up the procurement quantity.\n\nWhy not \"Cost and Price\"? Cost and Price live on the product, not the rule.\n\nWhy not \"Lead Time and Customer\"? Lead time can be displayed but is not the rule's defining pair; customer is unrelated.\n\nWhy not \"Lot Size and Tolerance\"? Lot Size and Tolerance are not the rule fields.", fr: "Une règle de réapprovisionnement a une quantité minimum (le seuil de déclenchement) et une quantité maximum (le niveau de stock cible). Lorsque le stock prévisionnel à l'emplacement de la règle descend en dessous du minimum, Odoo crée un approvisionnement pour ramener le stock au maximum." },
  }),
  complexQ({
    id: "oep-034",
    module: "inventory",
    text: { en: "An Odoo 19 warehouse is configured with 3-step receipts (Input → Quality → Stock). What is the primary purpose of this configuration?", fr: "Un entrepôt Odoo 19 est configuré avec des réceptions en 3 étapes (Entrée → Qualité → Stock). Quel est l'objectif principal de cette configuration ?" },
    correct: { en: "Insert a quality control step between vendor receipt and putaway to stock", fr: "Insérer une étape de contrôle qualité entre la réception fournisseur et le rangement en stock" },
    distractors: [
      { en: "Faster receipts in Odoo 19", fr: "Des réceptions plus rapides dans Odoo 19" },
      { en: "Multi-currency receipts", fr: "Des réceptions multi-devises" },
      { en: "Consolidate multiple POs", fr: "Consolider plusieurs bons de commande fournisseur" },
    ],
    explanation: { en: "3-step receipts separate physical reception (vendor delivers to Input), quality inspection (move from Input to QC location), and putaway (move from QC to Stock once approved). Each step is a stock.picking with its own quality checks if the Quality module is installed. This pattern is common in regulated industries (pharma, food, electronics).\n\nWhy not \"Faster receipts in Odoo 19\"? Multi-step processes are slower per item but more controlled, not faster.\n\nWhy not \"Multi-currency receipts\"? Multi-currency is a finance feature, not a warehouse step model.\n\nWhy not \"Consolidate multiple POs\"? PO consolidation is a procurement choice unrelated to step count.", fr: "Les réceptions en 3 étapes séparent la réception physique (le fournisseur livre à l'entrée), l'inspection qualité (transfert de l'entrée vers l'emplacement CQ) et le rangement (transfert du CQ vers le stock une fois approuvé). Chaque étape est un stock.picking avec ses propres contrôles qualité si le module Qualité est installé." },
  }),
  complexQ({
    id: "oep-035",
    module: "inventory",
    text: { en: "A consultant needs to handle drop-shipping where the vendor ships directly to the customer. Which Odoo 19 route is used?", fr: "Un consultant doit gérer le dropshipping où le fournisseur expédie directement au client. Quelle route Odoo 19 est utilisée ?" },
    correct: { en: "Dropship route on the product", fr: "Route de livraison directe sur le produit" },
    distractors: [
      { en: "Buy + Manufacture in Odoo 19", fr: "Achat + Fabrication dans Odoo 19" },
      { en: "Cross-Dock only", fr: "Cross-dock uniquement" },
      { en: "Internal Transfers", fr: "Transferts internes" },
    ],
    explanation: { en: "Activate Dropshipping in Purchase > Settings, which adds a 'Dropship' route selectable on the product. When an SO line uses a Dropship product, Odoo creates a PO with the customer's shipping address as delivery, bypassing the warehouse entirely. No stock movement is recorded internally beyond the dropship transit.\n\nWhy not \"Buy + Manufacture in Odoo 19\"? Buy + Manufacture combines production with purchasing but still involves your warehouse.\n\nWhy not \"Cross-Dock only\"? Cross-Dock receives goods and immediately ships them out from the warehouse — different from direct vendor-to-customer.\n\nWhy not \"Internal Transfers\"? Internal Transfers move stock between own locations, not vendor-to-customer.", fr: "Activer la livraison directe dans Achats > Paramètres, ce qui ajoute une route « Livraison directe » sélectionnable sur le produit. Lorsqu'une ligne de commande client utilise un produit en livraison directe, Odoo crée un bon de commande fournisseur avec l'adresse de livraison du client, contournant entièrement l'entrepôt." },
  }),
  complexQ({
    id: "oep-036",
    module: "inventory",
    text: { en: "What does enabling 'Storage Locations' in Inventory > Settings allow a warehouse to do in Odoo 19?", fr: "Qu'est-ce que l'activation des « Emplacements de stockage » dans Inventaire > Paramètres permet à un entrepôt de faire dans Odoo 19 ?" },
    correct: { en: "Use sub-locations within a warehouse (aisles, shelves, bins)", fr: "Utiliser des sous-emplacements au sein d'un entrepôt (allées, étagères, casiers)" },
    distractors: [
      { en: "Create multiple warehouses", fr: "Créer plusieurs entrepôts" },
      { en: "Track lots", fr: "Suivre les lots" },
      { en: "Track ownership of stock", fr: "Suivre la propriété du stock" },
    ],
    explanation: { en: "Storage Locations enables hierarchical sub-locations like WH/Stock/Aisle-A/Bin-12. Without it, a warehouse has only its top-level Stock location. Combined with putaway rules and storage categories, you can direct different products to different bins, support pick paths, and track stock at granular locations.\n\nWhy not \"Create multiple warehouses\"? Multiple warehouses are always supported; this toggle is for sub-locations within a warehouse.\n\nWhy not \"Track lots\"? Lot tracking is a separate setting under Traceability.\n\nWhy not \"Track ownership of stock\"? Stock ownership (consignment) is its own setting.", fr: "Les emplacements de stockage permettent des sous-emplacements hiérarchiques comme WH/Stock/Allée-A/Casier-12. Sans cette option, un entrepôt n'a que son emplacement Stock de niveau supérieur. Combiné avec les règles de rangement et les catégories de stockage, vous pouvez diriger différents produits vers différents casiers." },
  }),
  complexQ({
    id: "oep-037",
    module: "inventory",
    text: { en: "An Odoo 19 user runs a physical inventory count. Which document records the discovered differences and posts them to inventory adjustments?", fr: "Un utilisateur Odoo 19 effectue un inventaire physique. Quel document enregistre les écarts constatés et les comptabilise en ajustements d'inventaire ?" },
    correct: { en: "Inventory Adjustment (under Operations > Physical Inventory)", fr: "Ajustement d'inventaire (sous Opérations > Inventaire physique)" },
    distractors: [
      { en: "Stock Move in Odoo 19", fr: "Mouvement de stock dans Odoo 19" },
      { en: "Vendor Bill", fr: "Facture fournisseur" },
      { en: "Manufacturing Order", fr: "Ordre de fabrication" },
    ],
    explanation: { en: "Operations > Physical Inventory lets users enter Counted Quantities by location/product/lot. Validating creates inventory adjustment moves between the location and the Inventory Adjustment virtual location, accounting for shrinkage, miscounts, or breakage. Each adjustment generates standard stock.move records and, with continuous valuation, journal entries.\n\nWhy not \"Stock Move in Odoo 19\"? Stock Move is the underlying record; Inventory Adjustment is the user-facing document.\n\nWhy not \"Vendor Bill\"? Vendor Bills are for AP, not for inventory counts.\n\nWhy not \"Manufacturing Order\"? MOs produce goods from BoMs, unrelated to count corrections.", fr: "Opérations > Inventaire physique permet aux utilisateurs de saisir les quantités comptées par emplacement/produit/lot. La validation crée des mouvements d'ajustement d'inventaire entre l'emplacement et l'emplacement virtuel d'ajustement d'inventaire, comptabilisant les pertes, erreurs de comptage ou casses." },
  }),
  complexQ({
    id: "oep-038",
    module: "inventory",
    text: { en: "A consultant must configure a product so that one unit equals 12 pieces (a dozen) for purchase but is sold and stocked as a single piece. Which Odoo 19 feature handles this?", fr: "Un consultant doit configurer un produit pour qu'une unité équivaille à 12 pièces (une douzaine) à l'achat, mais soit vendu et stocké à la pièce. Quelle fonctionnalité Odoo 19 gère cela ?" },
    correct: { en: "Units of Measure (UoM)", fr: "Unités de mesure (UdM)" },
    distractors: [
      { en: "Variants in Odoo 19", fr: "Les variantes dans Odoo 19" },
      { en: "Pricelists with quantity tiers", fr: "Les listes de prix avec paliers de quantité" },
      { en: "Putaway rules", fr: "Les règles de rangement" },
    ],
    explanation: { en: "Activate Units of Measure in Inventory > Settings. Define the Piece UoM and Dozen UoM in the same UoM category with conversion factor 12. On the product, set Unit of Measure = Piece (base for stock and sales) and Purchase UoM = Dozen. When a PO of 1 Dozen is received, stock is updated by 12 Pieces.\n\nWhy not \"Variants in Odoo 19\"? Variants are size/color combinations, not different units of the same product.\n\nWhy not \"Pricelists with quantity tiers\"? Pricelists tier prices but do not convert quantities into different units.\n\nWhy not \"Putaway rules\"? Putaway rules direct stock to locations; not conversion.", fr: "Activer les unités de mesure dans Inventaire > Paramètres. Définir l'UdM Pièce et l'UdM Douzaine dans la même catégorie d'UdM avec un facteur de conversion de 12. Sur le produit, définir l'unité de mesure = Pièce (base pour le stock et les ventes) et l'UdM d'achat = Douzaine." },
  }),
  complexQ({
    id: "oep-039",
    module: "inventory",
    text: { en: "What is consignment stock in Odoo 19 Inventory and how is it modeled?", fr: "Qu'est-ce que le stock en consignation dans Odoo 19 Inventaire et comment est-il modélisé ?" },
    correct: { en: "Stock at the company location but owned by a third party (vendor)", fr: "Stock situé dans l'emplacement de la société mais appartenant à un tiers (fournisseur)" },
    distractors: [
      { en: "Stock owned by the company at a customer site, with a special transfer type", fr: "Stock appartenant à la société chez un client, avec un type de transfert spécial" },
      { en: "Stock that is awaiting destruction", fr: "Stock en attente de destruction" },
      { en: "Stock blocked from sale", fr: "Stock bloqué à la vente" },
    ],
    explanation: { en: "Consignment lets a vendor own physical stock that resides at your warehouse. Enable Consignment in Inventory > Settings, which exposes an Owner field on stock moves and on-hand records. You only purchase the consigned items when you actually consume or sell them, decoupling physical possession from inventory ownership for accounting.\n\nWhy not \"Stock owned by the company at a customer site, with a special transfer type\"? That direction is reverse consignment / VMI variants; the standard consignment in Odoo is vendor-owned at your site.\n\nWhy not \"Stock that is awaiting destruction\"? Destruction stock uses scrap moves, not consignment.\n\nWhy not \"Stock blocked from sale\"? Blocked stock is achieved via location/lot blocking, not consignment.", fr: "La consignation permet à un fournisseur de posséder du stock physiquement présent dans votre entrepôt. Activer la consignation dans Inventaire > Paramètres, ce qui expose un champ Propriétaire sur les mouvements de stock et les enregistrements en stock. Vous n'achetez les articles consignés que lorsque vous les consommez ou les vendez réellement." },
  }),
  complexQ({
    id: "oep-040",
    module: "inventory",
    text: { en: "A consultant enables Multi-Step Routes and configures pull rules. Pull rules in Odoo 19 are triggered when:", fr: "Un consultant active les routes multi-étapes et configure des règles de tirage. Les règles de tirage dans Odoo 19 sont déclenchées quand :" },
    correct: { en: "A demand at the destination location pulls stock from a source location", fr: "Une demande à l'emplacement de destination tire le stock depuis un emplacement source" },
    distractors: [
      { en: "A purchase is created in Odoo 19", fr: "Un achat est créé dans Odoo 19" },
      { en: "Stock is received in a warehouse", fr: "Du stock est reçu dans un entrepôt" },
      { en: "An MO is validated", fr: "Un OF est validé" },
    ],
    explanation: { en: "Pull rules (procurement rules) are triggered when there is unmet demand at a destination location. Odoo searches for a rule whose destination matches and creates moves from the configured source. They are how routes such as MTO, multi-step delivery, and dropship are wired. Push rules instead react when stock arrives at a source location and proactively move it forward.\n\nWhy not \"A purchase is created in Odoo 19\"? POs are an effect of pull rules in some routes, not the trigger of the rule itself.\n\nWhy not \"Stock is received in a warehouse\"? Receipt arrival is what triggers push rules, not pull rules.\n\nWhy not \"An MO is validated\"? MO validation produces stock; it is not what triggers pull rules.", fr: "Les règles de tirage (règles d'approvisionnement) sont déclenchées lorsqu'il y a une demande non satisfaite à un emplacement de destination. Odoo recherche une règle dont la destination correspond et crée des mouvements depuis la source configurée. C'est ainsi que les routes comme MTO, la livraison multi-étapes et la livraison directe sont câblées." },
  }),
  complexQ({
    id: "oep-041",
    module: "inventory",
    text: { en: "Which Odoo 19 module lets you scan barcodes on receipts, deliveries, and manufacturing operations using a phone or scanner?", fr: "Quel module Odoo 19 permet de scanner des codes-barres sur les réceptions, livraisons et opérations de fabrication à l'aide d'un téléphone ou d'un scanner ?" },
    correct: { en: "Barcode (stock_barcode)", fr: "Code-barres (stock_barcode)" },
    distractors: [
      { en: "Studio in Odoo 19", fr: "Studio dans Odoo 19" },
      { en: "POS", fr: "PDV" },
      { en: "Sign", fr: "Sign" },
    ],
    explanation: { en: "The Barcode app provides a tablet/phone-friendly UI for warehouse operators to scan items, locations, and lots during receipts, deliveries, internal transfers, and manufacturing operations. It supports common 1D and 2D barcodes and uses the device's camera or any USB/Bluetooth scanner.\n\nWhy not \"Studio in Odoo 19\"? Studio customizes apps; it is not a barcode UI.\n\nWhy not \"POS\"? POS uses barcodes for sales at retail, not warehouse operations.\n\nWhy not \"Sign\"? Sign handles signatures, not barcodes.", fr: "L'application Code-barres fournit une interface adaptée aux tablettes/téléphones pour les opérateurs d'entrepôt afin de scanner les articles, emplacements et lots lors des réceptions, livraisons, transferts internes et opérations de fabrication. Elle prend en charge les codes-barres 1D et 2D courants." },
  }),
  complexQ({
    id: "oep-042",
    module: "purchases",
    text: { en: "A consultant wants to receive a shipment that includes products not on the original PO. What is the standard Odoo 19 way to handle this?", fr: "Un consultant veut recevoir un envoi qui inclut des produits absents du bon de commande fournisseur d'origine. Quelle est la méthode standard d'Odoo 19 pour gérer cela ?" },
    correct: { en: "Edit the receipt to add the missing line, then validate", fr: "Modifier la réception pour ajouter la ligne manquante, puis valider" },
    distractors: [
      { en: "Discard the entire receipt and create a new PO", fr: "Annuler la réception entière et créer un nouveau bon de commande fournisseur" },
      { en: "Use a backorder for the missing line", fr: "Utiliser un reliquat pour la ligne manquante" },
      { en: "It is not possible", fr: "Ce n'est pas possible" },
    ],
    explanation: { en: "On a draft receipt, a user with appropriate rights can add a stock.move.line for the unexpected product, validate the receipt, and the corresponding PO can be amended afterward (or a vendor bill match drives the linkage). For governance, many configurations require strict 1:1 PO/receipt; in that case, you would refuse the items or create a new PO. Default behavior allows over-receipt with a confirmation dialog.\n\nWhy not \"Discard the entire receipt and create a new PO\"? Discarding is wasteful; Odoo supports adjustments on the receipt.\n\nWhy not \"Use a backorder for the missing line\"? Backorders handle missing quantities, not missing line items.\n\nWhy not \"It is not possible\"? It is supported with appropriate rights.", fr: "Sur une réception en brouillon, un utilisateur avec les droits appropriés peut ajouter un stock.move.line pour le produit inattendu, valider la réception, et le bon de commande fournisseur correspondant peut être modifié par la suite. Le comportement par défaut autorise les sur-réceptions avec un dialogue de confirmation." },
  }),
  complexQ({
    id: "oep-043",
    module: "purchases",
    text: { en: "A buyer needs to negotiate competitive quotes from three vendors before placing a PO. Which Odoo 19 Purchase feature streamlines this?", fr: "Un acheteur a besoin de négocier des devis compétitifs auprès de trois fournisseurs avant de passer un bon de commande. Quelle fonctionnalité Odoo 19 Achats facilite cela ?" },
    correct: { en: "Purchase Agreements (Calls for Tender)", fr: "Contrats d'achat (Appels d'offres)" },
    distractors: [
      { en: "Vendor Bill Matching", fr: "Le rapprochement de factures fournisseur, qui appartient à une autre application Odoo" },
      { en: "Subscription Templates", fr: "Les modèles d'abonnement" },
      { en: "Reordering Rules", fr: "Les règles de réapprovisionnement" },
    ],
    explanation: { en: "Purchase Agreements in Purchase > Orders include 'Call for Tenders' (also called Purchase Tenders or Blanket Order). For tenders, you select multiple vendors, send each an RFQ, compare the responses side-by-side, and confirm one winning RFQ into a PO. Blanket Orders set a recurring purchase contract with one vendor instead.\n\nWhy not \"Vendor Bill Matching\"? Bill Matching is for accounting reconciliation of vendor invoices.\n\nWhy not \"Subscription Templates\"? Subscriptions are sales-side recurring sales.\n\nWhy not \"Reordering Rules\"? Reordering rules trigger replenishment but do not handle competitive bidding.", fr: "Les contrats d'achat dans Achats > Commandes incluent les « Appels d'offres ». Pour les appels d'offres, vous sélectionnez plusieurs fournisseurs, envoyez à chacun une demande de prix, comparez les réponses côte à côte et confirmez la demande de prix gagnante en bon de commande." },
  }),
  complexQ({
    id: "oep-044",
    module: "purchases",
    text: { en: "What is 3-way matching in Odoo 19 Purchase/Accounting?", fr: "Qu'est-ce que le rapprochement à 3 voies dans Odoo 19 Achats/Comptabilité ?" },
    correct: { en: "Match vendor bill to PO and receipt before payment", fr: "Rapprocher la facture fournisseur avec le bon de commande et la réception avant paiement" },
    distractors: [
      { en: "Match three different journals", fr: "Rapprocher trois journaux différents" },
      { en: "Match purchase, sale, and inventory", fr: "Rapprocher achat, vente et inventaire" },
      { en: "Match vendor, PO, and customer", fr: "Rapprocher fournisseur, bon de commande et client" },
    ],
    explanation: { en: "3-way matching ensures the vendor bill agrees with the PO (what was ordered) and the receipt (what was actually received) before the bill is paid. Enabled in Accounting > Settings, Odoo flags bills that do not pass the check, preventing payment of items not received or quantities exceeding the PO. This is a core internal control in AP.\n\nWhy not \"Match three different journals\"? It is not about journals.\n\nWhy not \"Match purchase, sale, and inventory\"? It is not about cross-app entity matching.\n\nWhy not \"Match vendor, PO, and customer\"? Vendors and customers are unrelated entities; the three documents are PO, receipt, and bill.", fr: "Le rapprochement à 3 voies garantit que la facture fournisseur correspond au bon de commande (ce qui a été commandé) et à la réception (ce qui a été effectivement reçu) avant que la facture soit payée. Activé dans Comptabilité > Paramètres, Odoo signale les factures qui ne passent pas le contrôle." },
  }),
  complexQ({
    id: "oep-045",
    module: "purchases",
    text: { en: "A buyer wants to create a vendor bill from an incoming PDF emailed to bills@company.odoo.com. Which Odoo 19 feature processes this?", fr: "Un acheteur veut créer une facture fournisseur à partir d'un PDF entrant envoyé par e-mail à factures@company.odoo.com. Quelle fonctionnalité Odoo 19 traite cela ?" },
    correct: { en: "Email alias on the Purchase journal", fr: "Alias e-mail sur le journal d'achat" },
    distractors: [
      { en: "Studio automated action only", fr: "Action automatisée Studio uniquement" },
      { en: "Discuss channel webhook", fr: "Webhook de canal Discuss" },
      { en: "Manual data entry only", fr: "Saisie manuelle uniquement" },
    ],
    explanation: { en: "Each Vendor Bill journal supports an email alias and OCR-based digitization via Odoo IAP credits. Forward or have the vendor send a PDF to the alias; Odoo extracts vendor, total, due date, lines, and creates a draft vendor bill ready for review. Accuracy improves with prior bills from the same vendor.\n\nWhy not \"Studio automated action only\"? Studio automations cannot OCR PDFs without the digitization service.\n\nWhy not \"Discuss channel webhook\"? Discuss is for chat, not document processing.\n\nWhy not \"Manual data entry only\"? Manual entry works but is not the streamlined feature being asked about.", fr: "Chaque journal de factures fournisseur prend en charge un alias e-mail et la numérisation OCR via les crédits Odoo IAP. Le fournisseur envoie un PDF à l'alias ; Odoo extrait le fournisseur, le total, la date d'échéance, les lignes et crée un brouillon de facture fournisseur prêt à être vérifié." },
  }),
  complexQ({
    id: "oep-046",
    module: "purchases",
    text: { en: "On a purchase.order in Odoo 19, what is the difference between an RFQ and a PO?", fr: "Sur un purchase.order dans Odoo 19, quelle est la différence entre une demande de prix et un bon de commande fournisseur ?" },
    correct: { en: "RFQ is a draft state where the document is a Request for Quotation", fr: "La demande de prix est un état brouillon où le document est une demande de prix" },
    distractors: [
      { en: "RFQ is for services only", fr: "La demande de prix est réservée aux services uniquement" },
      { en: "PO is for blanket orders only", fr: "Le bon de commande est réservé aux ordres ouverts uniquement" },
      { en: "There is no difference", fr: "Il n'y a pas de différence" },
    ],
    explanation: { en: "Both share the purchase.order model. While in 'RFQ' state, the document is a request you send to the vendor for pricing. After confirmation, it becomes a Purchase Order with state='purchase' and Odoo creates the linked receipt(s). The label visible to users (RFQ vs PO) depends on the state, not on a different model.\n\nWhy not \"RFQ is for services only\"? Both products and services can be on RFQs and POs.\n\nWhy not \"PO is for blanket orders only\"? Blanket orders are a separate Purchase Agreement type.\n\nWhy not \"There is no difference\"? There is a clear lifecycle difference between the two states.", fr: "Les deux partagent le modèle purchase.order. À l'état « Demande de prix », le document est une demande envoyée au fournisseur pour obtenir un devis. Après confirmation, il devient un bon de commande fournisseur avec state='purchase' et Odoo crée les réceptions liées." },
  }),
  complexQ({
    id: "oep-047",
    module: "purchases",
    text: { en: "A consultant configures a vendor pricelist (vendor info) on a product. Which fields drive automatic procurement decisions in Odoo 19?", fr: "Un consultant configure une liste de prix fournisseur (infos fournisseur) sur un produit. Quels champs pilotent les décisions d'approvisionnement automatique dans Odoo 19 ?" },
    correct: { en: "Vendor, Min Qty, Price, Delivery Lead Time, Validity", fr: "Fournisseur, Qté minimum, Prix, Délai de livraison, Validité" },
    distractors: [
      { en: "Only the vendor name", fr: "Uniquement le nom du fournisseur" },
      { en: "Only the price", fr: "Uniquement le prix" },
      { en: "Only the lead time", fr: "Uniquement le délai de livraison" },
    ],
    explanation: { en: "The Vendor Pricelist line under product > Purchase tab includes Vendor, Min Quantity (price applies above this qty), Price, Delivery Lead Time (for procurement scheduling), and Validity dates. The first valid line drives RFQs created by reordering rules and MTO. Multiple vendors can be ranked by sequence so Odoo picks the preferred one.\n\nWhy not \"Only the vendor name\"? Just the vendor is insufficient; price/lead time are required to drive procurement.\n\nWhy not \"Only the price\"? Price alone is not enough; lead time and qty matter.\n\nWhy not \"Only the lead time\"? Lead time alone does not drive pricing or vendor choice.", fr: "La ligne de liste de prix fournisseur sous produit > onglet Achat inclut le fournisseur, la quantité minimum (le prix s'applique au-dessus de cette quantité), le prix, le délai de livraison (pour la planification d'approvisionnement) et les dates de validité. La première ligne valide pilote les demandes de prix créées par les règles de réapprovisionnement." },
  }),
  complexQ({
    id: "oep-048",
    module: "purchases",
    text: { en: "A buyer wants automated approval thresholds where POs over $10,000 require manager approval. How is this configured in Odoo 19?", fr: "Un acheteur veut des seuils d'approbation automatiques où les bons de commande supérieurs à 10 000 $ nécessitent l'approbation d'un responsable. Comment cela se configure-t-il dans Odoo 19 ?" },
    correct: { en: "Activate Purchase Order Approval in Purchase > Settings, set the threshold", fr: "Activer l'approbation des bons de commande dans Achats > Paramètres, définir le seuil" },
    distractors: [
      { en: "Use a Studio automation only", fr: "Utiliser uniquement une automatisation Studio" },
      { en: "Modify res.users", fr: "Modifier res.users" },
      { en: "Use an analytic distribution rule", fr: "Utiliser une règle de distribution analytique" },
    ],
    explanation: { en: "Purchase > Configuration > Settings has 'Purchase Order Approval' with a Minimum Amount field. POs above this amount require explicit manager approval before they can be confirmed. The required approver is a user with the Purchase Manager role (purchase.group_purchase_manager).\n\nWhy not \"Use a Studio automation only\"? A Studio automation could replicate this, but the standard built-in feature is the toggle in Purchase Settings.\n\nWhy not \"Modify res.users\"? User records define identity and access, not threshold rules.\n\nWhy not \"Use an analytic distribution rule\"? Analytic distributions tag costs, not approval thresholds.", fr: "Achats > Configuration > Paramètres dispose d'un paramètre « Approbation des bons de commande » avec un champ Montant minimum. Les bons de commande au-dessus de ce montant nécessitent l'approbation explicite d'un responsable avant de pouvoir être confirmés." },
  }),
  complexQ({
    id: "oep-049",
    module: "mrp",
    text: { en: "In Odoo 19 Manufacturing, what is the technical model for a Bill of Materials?", fr: "Dans Odoo 19 Fabrication, quel est le modèle technique pour une nomenclature ?" },
    correct: { en: "mrp.bom", fr: "mrp.bom" },
    distractors: [
      { en: "mrp.recipe", fr: "mrp.recipe" },
      { en: "mrp.formula", fr: "mrp.formula" },
      { en: "manufacturing.bom", fr: "manufacturing.bom" },
    ],
    explanation: { en: "The Bill of Materials is the mrp.bom model, with components in mrp.bom.line and operations (if any) in mrp.routing.workcenter. A BoM links a product (or template), an output quantity, and the required components and operations needed to produce it.\n\nWhy not \"mrp.recipe\"? mrp.recipe is not the model name.\n\nWhy not \"mrp.formula\"? mrp.formula is not the model name.\n\nWhy not \"manufacturing.bom\"? manufacturing.bom is not the namespace; Odoo uses mrp.*.", fr: "La nomenclature est le modèle mrp.bom, avec les composants dans mrp.bom.line et les opérations (le cas échéant) dans mrp.routing.workcenter. Une nomenclature lie un produit (ou modèle), une quantité de sortie et les composants et opérations nécessaires pour le produire." },
  }),
  complexQ({
    id: "oep-050",
    module: "mrp",
    text: { en: "What is the difference between a Kit BoM and a Manufacturing BoM in Odoo 19?", fr: "Quelle est la différence entre une nomenclature de type Kit et une nomenclature de fabrication dans Odoo 19 ?" },
    correct: { en: "Kit BoM explodes components on delivery; no stocked finished product", fr: "La nomenclature Kit éclate les composants à la livraison ; pas de produit fini en stock" },
    distractors: [
      { en: "Kit and Manufacture BoMs behave identically on every sales workflow", fr: "Les nomenclatures Kit et Fabrication se comportent de manière identique dans tous les flux de vente" },
      { en: "Kit BoM requires a work center and shop-floor work order sequence", fr: "La nomenclature Kit nécessite un poste de charge et une séquence d'ordres de travail" },
      { en: "Kit BoM products cannot be sold on quotations or sales orders", fr: "Les produits avec nomenclature Kit ne peuvent pas être vendus sur les devis ou bons de commande" },
    ],
    explanation: { en: "BoM Type 'Kit' means the parent product itself is not stocked or manufactured; instead, when sold or delivered, Odoo replaces the kit line with its component lines on the picking. BoM Type 'Manufacture this product' creates an MO that consumes components and produces the stocked finished product. Phantom (kit) BoMs are common for bundled SKUs sold as one but shipped as parts.\n\nWhy not \"Kit and Manufacture BoMs behave identically on every sales workflow\"? They are different BoM types with very different behavior.\n\nWhy not \"Kit BoM requires a work center and shop-floor work order sequence\"? Kits do not use work centers; manufacturing BoMs may.\n\nWhy not \"Kit BoM products cannot be sold on quotations or sales orders\"? Kits are sold all the time — that is their main use.", fr: "Le type de nomenclature « Kit » signifie que le produit parent lui-même n'est pas stocké ni fabriqué ; au lieu de cela, lors de la vente ou de la livraison, Odoo remplace la ligne du kit par ses lignes de composants sur le bon de livraison. Le type « Fabriquer ce produit » crée un OF qui consomme les composants et produit le produit fini stocké." },
  }),
  complexQ({
    id: "oep-051",
    module: "mrp",
    text: { en: "An MO in Odoo 19 has 4 work orders across 3 work centers. What is the effect of confirming the MO?", fr: "Un OF dans Odoo 19 a 4 ordres de travail répartis sur 3 postes de charge. Quel est l'effet de la confirmation de l'OF ?" },
    correct: { en: "The work orders are scheduled on the work center calendars based on capacity and lead time", fr: "Les ordres de travail sont planifiés sur les calendriers des postes de charge en fonction de la capacité et du délai" },
    distractors: [
      { en: "All work orders start immediately regardless of capacity", fr: "Tous les ordres de travail démarrent immédiatement indépendamment de la capacité" },
      { en: "Components are shipped to the customer", fr: "Les composants sont expédiés au client" },
      { en: "An invoice is created", fr: "Une facture est créée" },
    ],
    explanation: { en: "On MO confirmation, Odoo creates the work orders and uses each work center's working hours and capacity to schedule start/finish times. Operators see the queue in the Manufacturing Shop Floor view, and they record start, pause, and finish to update real time and OEE statistics on the work center.\n\nWhy not \"All work orders start immediately regardless of capacity\"? Capacity and dependency constraints respect the schedule; not everything starts at once.\n\nWhy not \"Components are shipped to the customer\"? Customer shipping is unrelated to MO confirmation.\n\nWhy not \"An invoice is created\"? Invoices are created from sales/purchase, not MOs directly.", fr: "Lors de la confirmation de l'OF, Odoo crée les ordres de travail et utilise les heures de travail et la capacité de chaque poste de charge pour planifier les heures de début/fin. Les opérateurs voient la file d'attente dans la vue Atelier de fabrication." },
  }),
  complexQ({
    id: "oep-052",
    module: "mrp",
    text: { en: "A consultant wants to outsource an operation (e.g., heat treatment) to a partner. Which Odoo 19 feature handles this?", fr: "Un consultant veut sous-traiter une opération (ex. : traitement thermique) à un partenaire. Quelle fonctionnalité Odoo 19 gère cela ?" },
    correct: { en: "Subcontracting on the BoM with a vendor and components", fr: "Sous-traitance sur la nomenclature avec un fournisseur et des composants" },
    distractors: [
      { en: "Drop-shipping", fr: "La livraison directe, qui appartient à une autre application Odoo" },
      { en: "Cross-docking", fr: "Le cross-dock" },
      { en: "Internal Transfer route", fr: "La route de transfert interne" },
    ],
    explanation: { en: "Subcontracting in Manufacturing lets you specify on a BoM that the product is produced by a Subcontractor (vendor). Odoo creates a PO for the subcontract product when needed, ships components to the vendor, receives the finished product, and tracks costs. Two flows are supported: Subcontracting and Subcontracting with Resupplied components.\n\nWhy not \"Drop-shipping\"? Dropshipping ships from vendor to customer without manufacturing.\n\nWhy not \"Cross-docking\"? Cross-docking moves received goods straight to outbound, no manufacturing.\n\nWhy not \"Internal Transfer route\"? Internal Transfer is location-to-location, not vendor manufacturing.", fr: "La sous-traitance en Fabrication permet de spécifier sur une nomenclature que le produit est fabriqué par un sous-traitant (fournisseur). Odoo crée un bon de commande fournisseur pour le produit sous-traité quand nécessaire, expédie les composants au fournisseur, reçoit le produit fini et suit les coûts." },
  }),
  complexQ({
    id: "oep-053",
    module: "mrp",
    text: { en: "What is the role of the Manufacturing Shop Floor module in Odoo 19?", fr: "Quel est le rôle du module Atelier de fabrication dans Odoo 19 ?" },
    correct: { en: "Tablet UI for operators to start/stop work orders and log quantities", fr: "Interface tablette pour les opérateurs pour démarrer/arrêter les ordres de travail et enregistrer les quantités" },
    distractors: [
      { en: "Payroll module computing employee wages from attendance clock events", fr: "Module de paie calculant les salaires des employés à partir des événements de pointage" },
      { en: "Purchase RFQ comparison grid for competitive vendor quote evaluation", fr: "Grille de comparaison de demandes de prix fournisseur pour l'évaluation compétitive" },
      { en: "Inventory module replacement with no manufacturing shop-floor interface", fr: "Remplacement du module Inventaire sans interface d'atelier de fabrication" },
    ],
    explanation: { en: "Shop Floor is a dedicated tablet/touch interface where operators see their queued work orders per work center, log start/pause/finish times, register produced and scrap quantities, and perform inline quality checks. Time logged updates the work center's OEE and the MO's actual cost.\n\nWhy not \"Payroll module computing employee wages from attendance clock events\"? Payroll is the HR Payroll module's job.\n\nWhy not \"Purchase RFQ comparison grid for competitive vendor quote evaluation\"? Purchase handles RFQs and vendor orders; Shop Floor is the manufacturing operator interface.\n\nWhy not \"Inventory module replacement with no manufacturing shop-floor interface\"? Inventory is a separate app and is not replaced.", fr: "L'Atelier est une interface dédiée tablette/tactile où les opérateurs voient leurs ordres de travail en file par poste de charge, enregistrent les heures de début/pause/fin, les quantités produites et les rebuts, et effectuent des contrôles qualité en ligne." },
  }),
  complexQ({
    id: "oep-054",
    module: "mrp",
    text: { en: "A consultant configures a quality check that triggers automatically on every receipt of a specific product. Which Odoo 19 module is required?", fr: "Un consultant configure un contrôle qualité qui se déclenche automatiquement à chaque réception d'un produit spécifique. Quel module Odoo 19 est nécessaire ?" },
    correct: { en: "Quality (quality_control)", fr: "Qualité (quality_control)" },
    distractors: [
      { en: "Studio only in Odoo 19", fr: "Studio uniquement dans Odoo 19" },
      { en: "Field Service", fr: "Field Service" },
      { en: "Knowledge", fr: "Knowledge" },
    ],
    explanation: { en: "The Quality module provides Quality Control Points (QCPs) bound to operations (receipts, transfers, MOs, work orders) and products. Each QCP defines test type (Pass/Fail, Measure, Take a Picture, Print Label) and trigger (every transfer, % of transfers, periodic). Failed checks generate Quality Alerts for follow-up.\n\nWhy not \"Studio only in Odoo 19\"? Studio cannot replicate the QCP and Quality Alert workflow on its own.\n\nWhy not \"Field Service\"? Field Service is for on-site service tasks, not warehouse QC.\n\nWhy not \"Knowledge\"? Knowledge stores documentation.", fr: "Le module Qualité fournit des points de contrôle qualité (PCQ) liés aux opérations (réceptions, transferts, OF, ordres de travail) et aux produits. Chaque PCQ définit un type de test (Réussi/Échoué, Mesure, Prendre une photo, Imprimer une étiquette) et un déclencheur." },
  }),
  complexQ({
    id: "oep-055",
    module: "mrp",
    text: { en: "In Odoo 19 Manufacturing, what is the purpose of a 'work center' (mrp.workcenter)?", fr: "Dans Odoo 19 Fabrication, quel est le rôle d'un « poste de charge » (mrp.workcenter) ?" },
    correct: { en: "Production resource with calendar", fr: "Ressource de production avec calendrier" },
    distractors: [
      { en: "Employee HR profile storing payroll contract and leave allocations", fr: "Profil RH de l'employé stockant le contrat de paie et les allocations de congés" },
      { en: "BoM header storing component lines and manufacturing operations", fr: "En-tête de nomenclature stockant les lignes de composants et les opérations de fabrication" },
      { en: "Stock location bin replacing warehouse rack and aisle hierarchy", fr: "Casier d'emplacement de stock remplaçant la hiérarchie de racks et allées de l'entrepôt" },
    ],
    explanation: { en: "A work center represents a production resource: a machine, an assembly station, or a manual workstation. It has a working calendar, an hourly cost (used in MO costing), a capacity (parallel productions allowed), efficiency, and OEE statistics. Operations on a BoM are dispatched to work centers, which in turn create work orders.\n\nWhy not \"Employee HR profile storing payroll contract and leave allocations\"? Employees are tracked in HR; work centers are resources, though they can have an employee link.\n\nWhy not \"BoM header storing component lines and manufacturing operations\"? BoMs are stored in mrp.bom, not work centers.\n\nWhy not \"Stock location bin replacing warehouse rack and aisle hierarchy\"? Stock locations are stock.location, not work centers.", fr: "Un poste de charge représente une ressource de production : une machine, un poste d'assemblage ou un poste de travail manuel. Il a un calendrier de travail, un coût horaire (utilisé dans le calcul du coût de l'OF), une capacité (productions parallèles autorisées), une efficacité et des statistiques TRS." },
  }),
  complexQ({
    id: "oep-056",
    module: "mrp",
    text: { en: "In Odoo 19 Manufacturing, the 'Manufacturing Readiness' setting on a BoM controls when an MO is marked Ready. Which two options does it offer?", fr: "Dans Odoo 19 Fabrication, le paramètre « Disponibilité pour fabrication » sur une nomenclature contrôle quand un OF est marqué Prêt. Quelles deux options propose-t-il ?" },
    correct: { en: "'When all components are available' versus 'When components for the 1st operation are available'", fr: "« Quand tous les composants sont disponibles » vs « Quand les composants de la 1ère opération sont disponibles »" },
    distractors: [
      { en: "'Flexible' versus 'Strict'", fr: "« Flexible » vs « Strict »" },
      { en: "'Make to Stock' versus 'Make to Order'", fr: "« Fabrication sur stock » vs « Fabrication à la commande »" },
      { en: "'Push' versus 'Pull'", fr: "« Push » vs « Pull »" },
    ],
    explanation: { en: "Manufacturing Readiness on the BoM determines when an MO becomes Ready: 'When all components are available' requires every component to be in stock first, while 'When components for the 1st operation are available' lets the MO start as soon as the parts needed for the first operation are on hand. This is distinct from 'Flexible Consumption' (Blocked / Allowed / Allowed with Warning), which governs whether consumed quantities may deviate from the BoM.\n\nWhy not \"'Flexible' versus 'Strict'\"? 'Flexible'/'Strict' is not the Manufacturing Readiness wording in Odoo 19; the related Flexible Consumption setting uses Blocked / Allowed / Allowed with Warning.\n\nWhy not \"'Make to Stock' versus 'Make to Order'\"? MTS vs MTO are replenishment routes, not the MO readiness rule.\n\nWhy not \"'Push' versus 'Pull'\"? Push vs Pull describes route rule directions, not BoM readiness.", fr: "La disponibilité pour fabrication sur la nomenclature détermine quand un OF devient Prêt : « Quand tous les composants sont disponibles » exige que chaque composant soit en stock, tandis que « Quand les composants de la 1ère opération sont disponibles » permet à l'OF de démarrer dès que les pièces nécessaires à la première opération sont disponibles." },
  }),
  complexQ({
    id: "oep-057",
    module: "mrp",
    text: { en: "Odoo 19 introduced enhancements to the MRP scheduler. What is the role of the MRP Scheduler (Run Scheduler)?", fr: "Odoo 19 a introduit des améliorations au planificateur MRP. Quel est le rôle du planificateur MRP (Exécuter le planificateur) ?" },
    correct: { en: "Periodically processes reordering rules and MTO procurements to create needed RFQs and MOs", fr: "Traite périodiquement les règles de réapprovisionnement et les approvisionnements MTO pour créer les demandes de prix et OF nécessaires" },
    distractors: [
      { en: "Sends emails to vendors", fr: "Envoie des e-mails aux fournisseurs" },
      { en: "Posts journal entries", fr: "Comptabilise des écritures comptables" },
      { en: "Generates customer invoices", fr: "Génère des factures clients" },
    ],
    explanation: { en: "The Run Scheduler action (or scheduled cron) walks through reordering rules and unmet procurement demands and creates the corresponding RFQs, MOs, or transfers needed to keep stock at the configured level. It is essential to keep the supply chain in sync without manual intervention. In Odoo 19, scheduling logic continues to be refined for performance with larger catalogs.\n\nWhy not \"Sends emails to vendors\"? Email is handled by mail/queue, not the MRP scheduler.\n\nWhy not \"Posts journal entries\"? Accounting entries are posted by accounting flows, not the scheduler.\n\nWhy not \"Generates customer invoices\"? Invoices are generated from sales/manufacturing/inventory linkages, not directly by the scheduler.", fr: "L'action Exécuter le planificateur (ou cron planifié) parcourt les règles de réapprovisionnement et les demandes d'approvisionnement non satisfaites et crée les demandes de prix, OF ou transferts correspondants nécessaires pour maintenir le stock au niveau configuré." },
  }),
  complexQ({
    id: "oep-058",
    module: "mrp",
    text: { en: "A consultant configures by-products on a BoM (e.g., scrap metal generated when producing a chair). How does Odoo 19 record by-products?", fr: "Un consultant configure des sous-produits sur une nomenclature (ex. : ferraille métallique générée lors de la production d'une chaise). Comment Odoo 19 enregistre-t-il les sous-produits ?" },
    correct: { en: "BoM By-products tab posts extra output quantities to stock on MO close", fr: "L'onglet Sous-produits de la nomenclature comptabilise les quantités de sortie supplémentaires en stock à la clôture de l'OF" },
    distractors: [
      { en: "By-products are scrapped automatically and removed from inventory", fr: "Les sous-produits sont automatiquement mis au rebut et retirés de l'inventaire" },
      { en: "Odoo cannot record secondary outputs from a manufacturing process", fr: "Odoo ne peut pas enregistrer de sorties secondaires d'un processus de fabrication" },
      { en: "By-products post only to analytic accounts without stock quant changes", fr: "Les sous-produits ne sont comptabilisés que sur les comptes analytiques sans changements de quants en stock" },
    ],
    explanation: { en: "BoMs have a By-products tab. When the MO is completed, by-product quantities are received into the stock location, valued at their cost (configurable), and available for sale or further use. This is distinct from scrap, which is a destruction. Common examples: sawdust from cutting, scrap metal, secondary outputs in chemical processes.\n\nWhy not \"By-products are scrapped automatically and removed from inventory\"? Scrap is its own concept (consumed and removed); by-products are produced outputs.\n\nWhy not \"Odoo cannot record secondary outputs from a manufacturing process\"? By-products are fully supported.\n\nWhy not \"By-products post only to analytic accounts without stock quant changes\"? Analytic accounting is for cost tracking, not for stocking by-products.", fr: "Les nomenclatures ont un onglet Sous-produits. Lorsque l'OF est terminé, les quantités de sous-produits sont reçues dans l'emplacement de stock, valorisées à leur coût (configurable) et disponibles pour la vente ou une utilisation ultérieure." },
  }),
  complexQ({
    id: "oep-059",
    module: "mrp",
    text: { en: "A consultant must track maintenance for shop equipment in Odoo 19. Which module integrates with Manufacturing for preventive and corrective maintenance?", fr: "Un consultant doit suivre la maintenance des équipements d'atelier dans Odoo 19. Quel module s'intègre à la Fabrication pour la maintenance préventive et corrective ?" },
    correct: { en: "Maintenance (maintenance app)", fr: "Maintenance (application maintenance)" },
    distractors: [
      { en: "Helpdesk", fr: "Helpdesk, qui appartient à une autre application Odoo" },
      { en: "Subscriptions", fr: "Abonnements" },
      { en: "Field Service", fr: "Field Service" },
    ],
    explanation: { en: "The Maintenance app links to mrp.workcenter via the equipment record. Preventive maintenance is scheduled by frequency or meter reading; corrective maintenance is triggered when equipment breaks down or a quality alert is created. The MTBF/MTTR statistics inform reliability dashboards, and downtime can be reflected in OEE.\n\nWhy not \"Helpdesk\"? Helpdesk is for customer support tickets.\n\nWhy not \"Subscriptions\"? Subscriptions handle recurring sales billing.\n\nWhy not \"Field Service\"? Field Service is for on-site customer service tasks, not internal equipment maintenance.", fr: "L'application Maintenance se lie à mrp.workcenter via l'enregistrement d'équipement. La maintenance préventive est planifiée par fréquence ou lecture de compteur ; la maintenance corrective est déclenchée lorsque l'équipement tombe en panne. Les statistiques MTBF/MTTR alimentent les tableaux de bord de fiabilité." },
  }),
  complexQ({
    id: "oep-060",
    module: "mrp",
    text: { en: "What is the relationship between a Manufacturing Order and the underlying stock movements in Odoo 19?", fr: "Quelle est la relation entre un ordre de fabrication et les mouvements de stock sous-jacents dans Odoo 19 ?" },
    correct: { en: "MO pickings consume components and receive finished goods via stock moves", fr: "Les transferts de l'OF consomment les composants et reçoivent les produits finis via des mouvements de stock" },
    distractors: [
      { en: "The MO is accounting-only and never creates inventory transactions", fr: "L'OF est purement comptable et ne crée jamais de transactions d'inventaire" },
      { en: "The MO ships finished goods directly to the customer delivery address", fr: "L'OF expédie les produits finis directement à l'adresse de livraison du client" },
      { en: "The MO reuses the same picking document as the linked sales order", fr: "L'OF réutilise le même document de transfert que la commande client liée" },
    ],
    explanation: { en: "An MO drives two virtual transfers: one consuming components from a source location to the production location, and one producing the finished product from the production location to a stock location. These are stock.picking records distinguished by picking type. The valuation impact follows the company's costing method.\n\nWhy not \"The MO is accounting-only and never creates inventory transactions\"? MOs absolutely move stock — they consume components and produce finished goods.\n\nWhy not \"The MO ships finished goods directly to the customer delivery address\"? MOs do not ship to customers; that is the delivery order's job.\n\nWhy not \"The MO reuses the same picking document as the linked sales order\"? Sales-order pickings are separate from MO pickings.", fr: "Un OF pilote deux transferts virtuels : un consommant les composants d'un emplacement source vers l'emplacement de production, et un produisant le produit fini de l'emplacement de production vers un emplacement de stock. Ce sont des enregistrements stock.picking distingués par le type de transfert." },
  }),
  complexQ({
    id: "oep-061",
    module: "hr",
    text: { en: "In Odoo 19 HR, what is an Employee Contract used for?", fr: "Dans Odoo 19 RH, à quoi sert un contrat employé ?" },
    correct: { en: "hr.contract stores wage, schedule, dates, and payroll structure terms", fr: "hr.contract stocke le salaire, le planning, les dates et les termes de la structure de paie" },
    distractors: [
      { en: "Purchase Agreement storing negotiated vendor pricing and lead times", fr: "Contrat d'achat stockant les prix négociés fournisseur et les délais de livraison" },
      { en: "mrp.workcenter defining machine capacity and hourly production cost", fr: "mrp.workcenter définissant la capacité machine et le coût de production horaire" },
      { en: "sale.order template with default quotation sections and legal terms", fr: "Modèle de sale.order avec sections de devis par défaut et conditions légales" },
    ],
    explanation: { en: "An hr.contract record holds the employment terms: wage, working schedule (resource.calendar), structure (for payroll), start/end dates, trial period, and notes. Multiple contracts can exist over an employee's tenure. Payroll uses the active contract to compute payslips. Alerts notify HR before expiry to renew contracts.\n\nWhy not \"Purchase Agreement storing negotiated vendor pricing and lead times\"? Vendor contracts are in Purchase Agreements, not HR.\n\nWhy not \"mrp.workcenter defining machine capacity and hourly production cost\"? Work centers belong to Manufacturing.\n\nWhy not \"sale.order template with default quotation sections and legal terms\"? Sales orders are in Sales.", fr: "Un enregistrement hr.contract contient les termes d'emploi : salaire, planning de travail (resource.calendar), structure (pour la paie), dates de début/fin, période d'essai et notes. Plusieurs contrats peuvent exister au cours de la carrière d'un employé. La paie utilise le contrat actif pour calculer les bulletins de paie." },
  }),
  complexQ({
    id: "oep-062",
    module: "hr",
    text: { en: "A consultant configures Time Off in Odoo 19. What is the difference between an Allocation and a Leave (Time Off Request)?", fr: "Un consultant configure les congés dans Odoo 19. Quelle est la différence entre une allocation et un congé (demande de congé) ?" },
    correct: { en: "Allocation grants a balance (e.g., 20 vacation days/year)", fr: "L'allocation accorde un solde (ex. : 20 jours de vacances/an)" },
    distractors: [
      { en: "They are the same record", fr: "Ce sont le même enregistrement" },
      { en: "Allocation is for managers only", fr: "L'allocation est réservée aux responsables uniquement" },
      { en: "Leave requests run payroll automatically", fr: "Les demandes de congé exécutent automatiquement la paie" },
    ],
    explanation: { en: "Allocations (hr.leave.allocation) grant employees a balance of a specific time-off type (Paid Time Off, Sick Leave, Comp Time). Leaves (hr.leave) are the requests employees submit, which consume from the allocation. Some leave types can be set to auto-allocate (e.g., per pay period accrual) or unlimited (e.g., unpaid leave).\n\nWhy not \"They are the same record\"? They are clearly different records with different lifecycles.\n\nWhy not \"Allocation is for managers only\"? Both are visible to employees according to access rights.\n\nWhy not \"Leave requests run payroll automatically\"? Leave approvals do not directly trigger payroll runs; they affect attendance and worked-day computation.", fr: "Les allocations (hr.leave.allocation) accordent aux employés un solde d'un type de congé spécifique (congés payés, congé maladie, récupération). Les congés (hr.leave) sont les demandes soumises par les employés, qui consomment l'allocation. Certains types de congé peuvent être configurés pour s'allouer automatiquement." },
  }),
  complexQ({
    id: "oep-063",
    module: "hr",
    text: { en: "Where do employees in Odoo 19 submit their expense reports?", fr: "Où les employés dans Odoo 19 soumettent-ils leurs notes de frais ?" },
    correct: { en: "Expenses module (hr_expense)", fr: "Module Notes de frais (hr_expense)" },
    distractors: [
      { en: "Sales > New Quotation in Odoo 19", fr: "Ventes > Nouveau devis dans Odoo 19" },
      { en: "Accounting > Bank Statement", fr: "Comptabilité > Relevé bancaire" },
      { en: "Inventory > Receipt", fr: "Inventaire > Réception" },
    ],
    explanation: { en: "The Expenses app lets employees record expenses (with receipt photos), submit a report grouping them, route to manager approval, then to accounting where the report is posted as a vendor bill payable to the employee. Reimbursement is paid out of an Outstanding Payments / payable account. Per-diem and mileage are supported.\n\nWhy not \"Sales > New Quotation in Odoo 19\"? Sales is for customer quotations.\n\nWhy not \"Accounting > Bank Statement\"? Bank statements record transactions, not employee expense submissions.\n\nWhy not \"Inventory > Receipt\"? Inventory receipts are for goods, not expense reports.", fr: "L'application Notes de frais permet aux employés d'enregistrer des dépenses (avec photos de reçus), de soumettre un rapport les regroupant, de l'acheminer vers l'approbation du responsable, puis vers la comptabilité où le rapport est comptabilisé comme une facture fournisseur payable à l'employé." },
  }),
  complexQ({
    id: "oep-064",
    module: "hr",
    text: { en: "A consultant sets up Recruitment in Odoo 19. What is the purpose of the Kanban stages on the Recruitment pipeline?", fr: "Un consultant met en place le Recrutement dans Odoo 19. Quel est le rôle des étapes Kanban dans le pipeline de Recrutement ?" },
    correct: { en: "Kanban stages moving applicants from screening through offer and hire", fr: "Étapes Kanban déplaçant les candidats de la sélection à l'offre et l'embauche" },
    distractors: [
      { en: "Payroll structure types defining employee salary rules and deductions", fr: "Types de structure de paie définissant les règles salariales et déductions des employés" },
      { en: "Vendor payment batch processing outgoing AP transfers to suppliers", fr: "Traitement par lots des paiements fournisseurs pour les transferts AP sortants" },
      { en: "Time-off allocation granting annual PTO balances to existing staff", fr: "Allocation de congés accordant les soldes de congés annuels au personnel existant" },
    ],
    explanation: { en: "Recruitment uses a Kanban pipeline per Job Position. Default stages move applicants from Initial Qualification through Interview rounds to Offer and Contract Proposal, ending at Hired. Each stage can require certain actions, send templated emails, and trigger handover to HR onboarding flows.\n\nWhy not \"Payroll structure types defining employee salary rules and deductions\"? Payroll is its own module, not recruitment stages.\n\nWhy not \"Vendor payment batch processing outgoing AP transfers to suppliers\"? Vendor payment is in Accounting.\n\nWhy not \"Time-off allocation granting annual PTO balances to existing staff\"? Time off is in the Time Off module.", fr: "Le Recrutement utilise un pipeline Kanban par poste. Les étapes par défaut déplacent les candidats de la qualification initiale aux entretiens jusqu'à l'offre et la proposition de contrat, aboutissant à l'embauche." },
  }),
  complexQ({
    id: "oep-065",
    module: "hr",
    text: { en: "An employee uses the Odoo 19 Attendances app with kiosk mode. How does kiosk mode work?", fr: "Un employé utilise l'application Pointage d'Odoo 19 avec le mode kiosque. Comment fonctionne le mode kiosque ?" },
    correct: { en: "Shared tablet clock-in via PIN, badge, or RFID without personal login", fr: "Pointage sur tablette partagée via code PIN, badge ou RFID sans connexion personnelle" },
    distractors: [
      { en: "Locks the tablet for IT administrators during server maintenance windows", fr: "Verrouille la tablette pour les administrateurs IT pendant les fenêtres de maintenance serveur" },
      { en: "Registers visitor badges at the front desk reception module only", fr: "Enregistre les badges visiteurs à la réception uniquement" },
      { en: "Records continuous workplace surveillance video on the kiosk device", fr: "Enregistre une vidéosurveillance continue du lieu de travail sur le kiosque" },
    ],
    explanation: { en: "Kiosk mode in Attendances is designed for shared devices in factories or offices. The tablet shows a clock-in screen where employees swipe a badge, scan a barcode, type a PIN, or use facial recognition (where configured) to clock in or out. Each scan creates an hr.attendance record without requiring a personal Odoo login.\n\nWhy not \"Locks the tablet for IT administrators during server maintenance windows\"? Kiosk mode is an end-user feature, not IT lock.\n\nWhy not \"Registers visitor badges at the front desk reception module only\"? Visitors have their own Frontdesk module.\n\nWhy not \"Records continuous workplace surveillance video on the kiosk device\"? Kiosk mode records check-in/out times, not video.", fr: "Le mode kiosque dans Pointage est conçu pour les appareils partagés dans les usines ou bureaux. La tablette affiche un écran de pointage où les employés scannent un badge, un code-barres, saisissent un code PIN ou utilisent la reconnaissance faciale pour pointer à l'entrée ou à la sortie." },
  }),
  complexQ({
    id: "oep-066",
    module: "hr",
    text: { en: "What is the difference between an Employee record (hr.employee) and a User record (res.users) in Odoo 19?", fr: "Quelle est la différence entre un enregistrement employé (hr.employee) et un enregistrement utilisateur (res.users) dans Odoo 19 ?" },
    correct: { en: "An Employee is an HR record (can exist without login)", fr: "Un employé est un enregistrement RH (peut exister sans connexion)" },
    distractors: [
      { en: "They are the same", fr: "Ce sont la même chose" },
      { en: "Only users can submit time off", fr: "Seuls les utilisateurs peuvent soumettre des congés" },
      { en: "Employees are for vendors only", fr: "Les employés sont uniquement pour les fournisseurs" },
    ],
    explanation: { en: "hr.employee is an HR profile and can exist for staff who never log in to Odoo (e.g., shop floor workers using only Attendances kiosk). res.users is a login account, typically linked one-to-one with an Employee for self-service (timesheets, expenses, time off). User access defines what data they can see and edit.\n\nWhy not \"They are the same\"? They are clearly different concepts.\n\nWhy not \"Only users can submit time off\"? Time off can be submitted on behalf of any employee by a manager; the employee themselves needs a user only for self-service.\n\nWhy not \"Employees are for vendors only\"? Employees are HR concepts, not vendor records.", fr: "hr.employee est un profil RH et peut exister pour du personnel qui ne se connecte jamais à Odoo (ex. : opérateurs d'atelier utilisant uniquement le kiosque de Pointage). res.users est un compte de connexion, généralement lié un-pour-un avec un employé pour le libre-service." },
  }),
  complexQ({
    id: "oep-067",
    module: "project",
    text: { en: "In Odoo 19 Project, what is the difference between a Task and a Milestone?", fr: "Dans Odoo 19 Projet, quelle est la différence entre une tâche et un jalon ?" },
    correct: { en: "Tasks are individual work items with assignees and deadlines", fr: "Les tâches sont des éléments de travail individuels avec des responsables et des échéances" },
    distractors: [
      { en: "They are the same", fr: "Ce sont la même chose" },
      { en: "Milestones cannot have a date", fr: "Les jalons ne peuvent pas avoir de date" },
      { en: "Tasks cannot be billed", fr: "Les tâches ne peuvent pas être facturées" },
    ],
    explanation: { en: "Tasks (project.task) are the executable work items with stages, assignees, and timesheets. Milestones (project.milestone) are project-level checkpoints (e.g., 'Design Approved', 'UAT Complete') that can be linked to multiple tasks. Milestones can be billed separately if the project's billing type is Milestone-based.\n\nWhy not \"They are the same\"? They are different objects with different roles.\n\nWhy not \"Milestones cannot have a date\"? Milestones can have target and actual dates.\n\nWhy not \"Tasks cannot be billed\"? Tasks can be billed (via timesheets or task-based billing) when the project is configured for it.", fr: "Les tâches (project.task) sont les éléments de travail exécutables avec des étapes, des responsables et des feuilles de temps. Les jalons (project.milestone) sont des points de contrôle au niveau du projet (ex. : « Design approuvé », « Recette terminée ») qui peuvent être liés à plusieurs tâches." },
  }),
  complexQ({
    id: "oep-068",
    module: "project",
    text: { en: "A consultant configures a project with billing type 'Based on Timesheets'. What does this mean in Odoo 19?", fr: "Un consultant configure un projet avec le type de facturation « Basé sur les feuilles de temps ». Que signifie cela dans Odoo 19 ?" },
    correct: { en: "Timesheet hours on project tasks become billable SO lines at the set rate", fr: "Les heures de feuille de temps sur les tâches du projet deviennent des lignes de commande facturables au tarif défini" },
    distractors: [
      { en: "The project is non-billable and excludes all timesheet-based invoicing", fr: "Le projet est non facturable et exclut toute facturation basée sur les feuilles de temps" },
      { en: "Only fixed-price contracts apply; timesheets are hidden from billing", fr: "Seuls les contrats à prix fixe s'appliquent ; les feuilles de temps sont masquées de la facturation" },
      { en: "Timesheets are disabled entirely for service projects in Enterprise", fr: "Les feuilles de temps sont entièrement désactivées pour les projets de services dans Enterprise" },
    ],
    explanation: { en: "With Timesheets billing, the linked sales order's product is service with 'invoice based on timesheets'. Hours logged on tasks of that project flow to the SO as deliverable quantities. When invoiced, those hours become invoice lines at the SO's unit price. Billable vs non-billable timesheet entries can be filtered to control what is invoiced.\n\nWhy not \"The project is non-billable and excludes all timesheet-based invoicing\"? It is billable — that is the definition.\n\nWhy not \"Only fixed-price contracts apply; timesheets are hidden from billing\"? Fixed price is a different billing type (Fixed Price / Milestones).\n\nWhy not \"Timesheets are disabled entirely for service projects in Enterprise\"? Timesheets are visible and central to this model.", fr: "Avec la facturation sur feuilles de temps, le produit du bon de commande lié est un service avec « facturer sur la base des feuilles de temps ». Les heures enregistrées sur les tâches de ce projet alimentent la commande en quantités livrables. Lors de la facturation, ces heures deviennent des lignes de facture au prix unitaire de la commande." },
  }),
  complexQ({
    id: "oep-069",
    module: "project",
    text: { en: "How does Odoo 19 measure project profitability?", fr: "Comment Odoo 19 mesure-t-il la rentabilité d'un projet ?" },
    correct: { en: "Analytic revenue minus timesheet cost, expenses, and consumed materials", fr: "Revenus analytiques moins coûts de feuilles de temps, notes de frais et matériaux consommés" },
    distractors: [
      { en: "Only the static budget field on the project form with no actual postings", fr: "Uniquement le champ budget statique sur le formulaire du projet sans aucune écriture réelle" },
      { en: "Only external SQL reports; Odoo has no built-in profitability analysis", fr: "Uniquement des rapports SQL externes ; Odoo n'a pas d'analyse de rentabilité intégrée" },
      { en: "Profitability is not measured; projects track tasks without financial KPIs", fr: "La rentabilité n'est pas mesurée ; les projets suivent les tâches sans KPI financiers" },
    ],
    explanation: { en: "Each project gets an analytic account. Revenue lines (invoices, planned SO amounts) and cost lines (timesheets at employee hourly cost, employee expenses, vendor bills, sold/consumed materials) post analytic items to that account. The Project Profitability report aggregates them into Margin = Revenue - Cost. This is standard in Odoo Enterprise.\n\nWhy not \"Only the static budget field on the project form with no actual postings\"? Profitability vs budget is a different metric.\n\nWhy not \"Only external SQL reports; Odoo has no built-in profitability analysis\"? Standard reports cover this; custom reports are not required.\n\nWhy not \"Profitability is not measured; projects track tasks without financial KPIs\"? It is a core feature of Project.", fr: "Chaque projet obtient un compte analytique. Les lignes de revenus (factures, montants de commandes planifiés) et les lignes de coûts (feuilles de temps au coût horaire de l'employé, notes de frais, factures fournisseur, matériaux vendus/consommés) comptabilisent des écritures analytiques sur ce compte. Le rapport de rentabilité du projet les agrège en Marge = Revenus - Coûts." },
  }),
  complexQ({
    id: "oep-070",
    module: "project",
    text: { en: "An Odoo 19 consultant sets up Sub-tasks under a parent task. What is the main benefit of using sub-tasks?", fr: "Un consultant Odoo 19 configure des sous-tâches sous une tâche parente. Quel est le principal avantage d'utiliser les sous-tâches ?" },
    correct: { en: "Decompose work under a parent while preserving grouped reporting", fr: "Décomposer le travail sous un parent tout en préservant le reporting groupé" },
    distractors: [
      { en: "Sub-tasks always bill at half the parent task hourly rate automatically", fr: "Les sous-tâches sont toujours facturées à la moitié du tarif horaire de la tâche parente automatiquement" },
      { en: "Sub-tasks ignore deadlines and never appear on Gantt or Kanban views", fr: "Les sous-tâches ignorent les échéances et n'apparaissent jamais dans les vues Gantt ou Kanban" },
      { en: "Every project must define at least one sub-task before going live", fr: "Chaque projet doit définir au moins une sous-tâche avant la mise en production" },
    ],
    explanation: { en: "Sub-tasks let you decompose work without losing the relationship to the parent. They appear under the parent task, contribute to its overall hour roll-up, and can be assigned to different team members. This pattern fits Agile-style story-to-subtask breakdowns or large deliverables divided into checkpoints.\n\nWhy not \"Sub-tasks always bill at half the parent task hourly rate automatically\"? Rates depend on the SO/employee, not parent/sub-task hierarchy.\n\nWhy not \"Sub-tasks ignore deadlines and never appear on Gantt or Kanban views\"? Sub-tasks have their own deadlines, just like tasks.\n\nWhy not \"Every project must define at least one sub-task before going live\"? Sub-tasks are optional; the benefit is structured decomposition under a parent task for reporting.", fr: "Les sous-tâches permettent de décomposer le travail sans perdre la relation avec le parent. Elles apparaissent sous la tâche parente, contribuent au cumul global des heures et peuvent être assignées à différents membres de l'équipe." },
  }),
  complexQ({
    id: "oep-071",
    module: "project",
    text: { en: "What is the purpose of the Planning module in Odoo 19, and how does it relate to Project?", fr: "Quel est le rôle du module Planification dans Odoo 19, et comment se rapporte-t-il au Projet ?" },
    correct: { en: "Planning lets managers schedule resources (employees", fr: "Planification permet aux responsables de planifier les ressources (employés" },
    distractors: [
      { en: "Planning replaces the Calendar app", fr: "Planification remplace l'application Calendrier" },
      { en: "Planning is for HR payroll only", fr: "Planification est uniquement pour la paie RH" },
      { en: "Planning is identical to Project", fr: "Planification est identique au Projet" },
    ],
    explanation: { en: "Planning manages shift-based resource scheduling (who works when, on what role/role template). Shifts can be linked to projects/tasks to show planned hours alongside availability. Conflicts (overlaps with time off, double-booking) are flagged. Used heavily in agencies and services to plan billable utilization in advance.\n\nWhy not \"Planning replaces the Calendar app\"? Calendar is a personal calendar; Planning is resource scheduling.\n\nWhy not \"Planning is for HR payroll only\"? Planning schedules shifts and roles; payroll computation belongs to the Payroll application.\n\nWhy not \"Planning is identical to Project\"? It complements Project; it does not replace it.", fr: "Planification gère la planification des ressources basée sur les créneaux (qui travaille quand, sur quel rôle). Les créneaux peuvent être liés aux projets/tâches pour afficher les heures planifiées aux côtés de la disponibilité. Les conflits (chevauchements avec les congés, double réservation) sont signalés." },
  }),
  complexQ({
    id: "oep-072",
    module: "website",
    text: { en: "A consultant publishes a website built with Odoo 19. Which technology powers the page builder?", fr: "Un consultant publie un site web construit avec Odoo 19. Quelle technologie alimente le constructeur de pages ?" },
    correct: { en: "A drag-and-drop block editor with snippets stored in QWeb templates", fr: "Un éditeur de blocs glisser-déposer avec des snippets stockés dans des templates QWeb" },
    distractors: [
      { en: "Pure plain HTML edited in code", fr: "Du HTML pur édité en code" },
      { en: "WordPress under the hood", fr: "WordPress sous le capot" },
      { en: "Static site generator only", fr: "Uniquement un générateur de site statique" },
    ],
    explanation: { en: "Odoo Website uses QWeb templates and a Snippet-based block editor. Editors drag/drop snippets (hero, features, gallery, testimonials), customize text, images, animations, and visibility per device. Templates are versioned and can be reverted. The same QWeb engine serves products, blog posts, and custom pages.\n\nWhy not \"Pure plain HTML edited in code\"? Plain HTML editing is possible but is not how the standard page builder works.\n\nWhy not \"WordPress under the hood\"? Odoo's Website is its own framework, not WordPress.\n\nWhy not \"Static site generator only\"? Pages are dynamic, not statically generated.", fr: "Le Site Web Odoo utilise des templates QWeb et un éditeur basé sur des blocs (snippets). Les éditeurs glissent/déposent des snippets (héros, fonctionnalités, galerie, témoignages), personnalisent le texte, les images, les animations et la visibilité par appareil." },
  }),
  complexQ({
    id: "oep-073",
    module: "website",
    text: { en: "What is the difference between a Product (in Sales) and an eCommerce Product in Odoo 19?", fr: "Quelle est la différence entre un produit (dans Ventes) et un produit eCommerce dans Odoo 19 ?" },
    correct: { en: "Same product.template published to eCommerce with website fields and SEO", fr: "Le même product.template publié sur l'eCommerce avec des champs site web et SEO" },
    distractors: [
      { en: "Separate website.product model unrelated to Sales catalog records", fr: "Un modèle website.product séparé sans lien avec les produits du catalogue Ventes" },
      { en: "Sales catalog products cannot appear on the public website storefront", fr: "Les produits du catalogue Ventes ne peuvent pas apparaître sur la vitrine publique du site web" },
      { en: "eCommerce supports downloadable services only, not physical goods", fr: "L'eCommerce ne prend en charge que les services téléchargeables, pas les biens physiques" },
    ],
    explanation: { en: "Odoo uses one product.template across Sales, Purchase, Inventory, and Website. Toggling 'Is Published' / 'Available on eCommerce' on a product exposes it to the website with its eCommerce-specific fields (description for the page, image, SEO meta, ribbon, alternative products). One source of truth avoids data duplication.\n\nWhy not \"Separate website.product model unrelated to Sales catalog records\"? There is no website.product model.\n\nWhy not \"Sales catalog products cannot appear on the public website storefront\"? Sales products absolutely can be sold online.\n\nWhy not \"eCommerce supports downloadable services only, not physical goods\"? eCommerce supports goods and services.", fr: "Odoo utilise un seul product.template dans Ventes, Achats, Inventaire et Site Web. Activer « Est publié » sur un produit l'expose au site web avec ses champs spécifiques eCommerce (description de la page, image, méta SEO, ruban, produits alternatifs). Une seule source de vérité évite la duplication des données." },
  }),
  complexQ({
    id: "oep-074",
    module: "website",
    text: { en: "A consultant configures Stripe as a payment provider in Odoo 19 eCommerce. Where is this set up?", fr: "Un consultant configure Stripe comme fournisseur de paiement dans l'eCommerce Odoo 19. Où cela se configure-t-il ?" },
    correct: { en: "Accounting or Website > Payment Providers", fr: "Comptabilité ou Site Web > Fournisseurs de paiement" },
    distractors: [
      { en: "Inventory settings for stock accounts without any payment gateway setup", fr: "Paramètres d'inventaire pour les comptes de stock sans configuration de passerelle de paiement" },
      { en: "HR payroll configuration for employee reimbursement workflows", fr: "Configuration de la paie RH pour les flux de remboursement des employés" },
      { en: "Studio custom fields only, with no payment.provider records", fr: "Champs personnalisés Studio uniquement, sans enregistrements payment.provider" },
    ],
    explanation: { en: "Payment Providers (payment.provider) include Stripe, PayPal, Adyen, Authorize.Net, Mercado Pago, Razorpay, and many more. You enter API keys, choose Test or Production mode, configure the linked journal where successful payments post, and select which payment methods (cards, wallets) to enable. Once set to Enabled, the provider appears on website checkout.\n\nWhy not \"Inventory settings for stock accounts without any payment gateway setup\"? Inventory does not handle payment providers.\n\nWhy not \"HR payroll configuration for employee reimbursement workflows\"? HR does not handle payment providers.\n\nWhy not \"Studio custom fields only, with no payment.provider records\"? Studio cannot configure provider credentials by itself.", fr: "Les fournisseurs de paiement (payment.provider) incluent Stripe, PayPal, Adyen, Authorize.Net, Mercado Pago, Razorpay et bien d'autres. Vous saisissez les clés API, choisissez le mode Test ou Production, configurez le journal lié où les paiements réussis sont comptabilisés, et sélectionnez les méthodes de paiement à activer." },
  }),
  complexQ({
    id: "oep-075",
    module: "website",
    text: { en: "A consultant must enable B2B mode on the Odoo 19 website so prices display tax-excluded and login is required to see prices. Which combination of settings achieves this?", fr: "Un consultant doit activer le mode B2B sur le site Odoo 19 pour que les prix s'affichent hors taxes et qu'une connexion soit requise pour voir les prix. Quelle combinaison de paramètres permet cela ?" },
    correct: { en: "Tax-excluded pricelists, mandatory login, and B2B customer account rules", fr: "Listes de prix hors taxes, connexion obligatoire et règles de compte client B2B" },
    distractors: [
      { en: "Disable Sales entirely and record revenue only via manual journal entries", fr: "Désactiver entièrement les Ventes et enregistrer les revenus uniquement via des écritures comptables manuelles" },
      { en: "Configure POS exclusively with no website or eCommerce storefront", fr: "Configurer uniquement le PDV sans site web ni vitrine eCommerce" },
      { en: "Enable multi-currency without changing tax display or login requirements", fr: "Activer le multi-devises sans changer l'affichage des taxes ni les exigences de connexion" },
    ],
    explanation: { en: "B2B mode is a combination of: pricelists with 'Tax Excluded' display, customer account settings requiring login before checkout (or before pricing), private categories or login-protected products, and possibly assigning a default pricelist by partner. Each customer can have a specific pricelist negotiated by sales. This is configurable via Website Settings without code.\n\nWhy not \"Disable Sales entirely and record revenue only via manual journal entries\"? Sales is required, not disabled.\n\nWhy not \"Configure POS exclusively with no website or eCommerce storefront\"? POS is unrelated to website B2B configuration.\n\nWhy not \"Enable multi-currency without changing tax display or login requirements\"? Multi-currency does not control tax display or login gating.", fr: "Le mode B2B est une combinaison de : listes de prix avec affichage « Hors taxes », paramètres de compte client exigeant la connexion avant la commande (ou avant de voir les prix), catégories privées ou produits protégés par connexion, et possiblement l'attribution d'une liste de prix par défaut par partenaire." },
  }),
  complexQ({
    id: "oep-076",
    module: "website",
    text: { en: "How are shipping methods integrated with carriers in Odoo 19?", fr: "Comment les méthodes de livraison sont-elles intégrées aux transporteurs dans Odoo 19 ?" },
    correct: { en: "Delivery > Shipping Methods with carrier API", fr: "Livraison > Méthodes de livraison avec API transporteur" },
    distractors: [
      { en: "Hardcoded shipping rates embedded only in custom Python modules", fr: "Tarifs de livraison codés en dur uniquement dans des modules Python personnalisés" },
      { en: "Studio form designer without any delivery.carrier integration", fr: "Concepteur de formulaire Studio sans intégration delivery.carrier" },
      { en: "Inventory module alone with no shipping method configuration menu", fr: "Module Inventaire seul sans menu de configuration des méthodes de livraison" },
    ],
    explanation: { en: "Shipping methods (delivery.carrier) wrap a provider integration. Manual provider lets you set fixed or rule-based rates. Real-time carrier integrations (FedEx, UPS, DHL, USPS, EasyPost, Sendcloud, Bpost) call the carrier's API at quotation/delivery time to fetch rates and generate shipping labels. Packaging dimensions and weight on products feed the rate calculation.\n\nWhy not \"Hardcoded shipping rates embedded only in custom Python modules\"? Carrier integrations are configurable, not hardcoded.\n\nWhy not \"Studio form designer without any delivery.carrier integration\"? Studio cannot configure carrier credentials by itself.\n\nWhy not \"Inventory module alone with no shipping method configuration menu\"? Inventory hosts the picking; carrier setup is in Inventory > Configuration > Shipping Methods or directly under Delivery.", fr: "Les méthodes de livraison (delivery.carrier) encapsulent une intégration de fournisseur. Le fournisseur manuel permet de définir des tarifs fixes ou basés sur des règles. Les intégrations de transporteurs en temps réel (FedEx, UPS, DHL, USPS, EasyPost, Sendcloud, Bpost) appellent l'API du transporteur au moment du devis/de la livraison pour obtenir les tarifs et générer les étiquettes." },
  }),
  complexQ({
    id: "oep-077",
    module: "website",
    text: { en: "A customer abandons their cart on the Odoo 19 eCommerce site. What feature can automatically follow up?", fr: "Un client abandonne son panier sur le site eCommerce Odoo 19. Quelle fonctionnalité peut automatiquement assurer le suivi ?" },
    correct: { en: "Automated abandoned-cart email after delay with cart recovery deep link", fr: "E-mail automatisé de panier abandonné après un délai avec un lien de récupération du panier" },
    distractors: [
      { en: "Manual phone follow-up only; Odoo provides no cart recovery tooling", fr: "Suivi téléphonique manuel uniquement ; Odoo ne fournit aucun outil de récupération de panier" },
      { en: "Abandoned carts deleted nightly with no retention or email option", fr: "Les paniers abandonnés sont supprimés chaque nuit sans rétention ni option d'e-mail" },
      { en: "Requires Marketing Automation exclusively; eCommerce has no built-in mail", fr: "Nécessite exclusivement l'Automatisation Marketing ; l'eCommerce n'a pas d'e-mail intégré" },
    ],
    explanation: { en: "eCommerce settings include automated emails for abandoned carts: after X hours of inactivity, the customer receives a templated email with a deep link back to their cart. Combined with discounts or coupons, this is a high-leverage recovery channel. Marketing Automation can extend the sequence with multi-touch campaigns.\n\nWhy not \"Manual phone follow-up only; Odoo provides no cart recovery tooling\"? A manual call is one option but not the standard automation answer.\n\nWhy not \"Abandoned carts deleted nightly with no retention or email option\"? Carts are not deleted automatically; they persist for the configured time.\n\nWhy not \"Requires Marketing Automation exclusively; eCommerce has no built-in mail\"? Marketing Automation can extend it but the basic email is built into eCommerce.", fr: "Les paramètres eCommerce incluent des e-mails automatisés pour les paniers abandonnés : après X heures d'inactivité, le client reçoit un e-mail modèle avec un lien direct vers son panier. Combiné avec des remises ou coupons, c'est un canal de récupération à fort levier." },
  }),
  complexQ({
    id: "oep-078",
    module: "website",
    text: { en: "A consultant configures eCommerce Tax Display in Odoo 19. Which company-level setting controls whether prices on the website show tax-included or tax-excluded?", fr: "Un consultant configure l'affichage des taxes eCommerce dans Odoo 19. Quel paramètre au niveau de la société contrôle si les prix sur le site affichent TTC ou HT ?" },
    correct: { en: "The pricelist's 'Display Type' field combined", fr: "Le champ « Type d'affichage » de la liste de prix combiné" },
    distractors: [
      { en: "The journal default", fr: "Le journal par défaut" },
      { en: "The currency", fr: "La devise" },
      { en: "The fiscal position alone", fr: "La position fiscale seule" },
    ],
    explanation: { en: "Tax display is determined by the Pricelist's display type (tax-included vs tax-excluded) and the website's default pricelist. Often B2C sites show tax-included prices and B2B sites show tax-excluded with VAT applied at checkout based on the customer's fiscal position. Country localizations may set different defaults.\n\nWhy not \"The journal default\"? Journals control accounting, not display.\n\nWhy not \"The currency\"? Currency controls money formatting, not tax display.\n\nWhy not \"The fiscal position alone\"? Fiscal positions remap taxes/accounts but do not control include/exclude display directly.", fr: "L'affichage des taxes est déterminé par le type d'affichage de la liste de prix (TTC vs HT) et la liste de prix par défaut du site web. Souvent, les sites B2C affichent les prix TTC et les sites B2B affichent les prix HT avec la TVA appliquée au paiement selon la position fiscale du client." },
  }),
  complexQ({
    id: "oep-079",
    module: "website",
    text: { en: "What is the role of Odoo Forum/Live Chat/Knowledge in supporting an eCommerce site?", fr: "Quel est le rôle d'Odoo Forum/Chat en direct/Knowledge pour soutenir un site eCommerce ?" },
    correct: { en: "Forum Q&A, Live Chat widgets, and Knowledge self-service articles", fr: "Forum Q&R, widgets de chat en direct et articles Knowledge en libre-service" },
    distractors: [
      { en: "They replace the Website Builder and remove all product catalog pages", fr: "Ils remplacent le constructeur de site web et suppriment toutes les pages du catalogue produits" },
      { en: "They operate only on POS terminals during active cashier sessions", fr: "Ils fonctionnent uniquement sur les terminaux PDV pendant les sessions de caisse actives" },
      { en: "They are HR modules for payroll, contracts, and employee onboarding", fr: "Ce sont des modules RH pour la paie, les contrats et l'intégration des employés" },
    ],
    explanation: { en: "Live Chat (im_livechat) enables real-time support widgets on the website with channels and operator routing. Forum lets a community discuss topics with reputation/karma. Knowledge (Enterprise) is a wiki for internal docs and customer-facing articles. Together they support pre-sale and post-sale interactions on the eCommerce site.\n\nWhy not \"They replace the Website Builder and remove all product catalog pages\"? They complement, not replace, the website.\n\nWhy not \"They operate only on POS terminals during active cashier sessions\"? They are website/CRM/Helpdesk-related, not POS.\n\nWhy not \"They are HR modules for payroll, contracts, and employee onboarding\"? Forum, Live Chat, and Knowledge support website engagement, not HR employee records.", fr: "Le Chat en direct (im_livechat) permet des widgets de support en temps réel sur le site web avec des canaux et le routage d'opérateurs. Le Forum permet à une communauté de discuter de sujets avec réputation/karma. Knowledge (Enterprise) est un wiki pour les documents internes et les articles destinés aux clients." },
  }),
  complexQ({
    id: "oep-080",
    module: "pos",
    text: { en: "A consultant configures Odoo 19 POS for a retail store. Which configuration object groups payment methods, the linked journal, and an outstanding account?", fr: "Un consultant configure le PDV Odoo 19 pour un magasin de détail. Quel objet de configuration regroupe les méthodes de paiement, le journal lié et un compte d'attente ?" },
    correct: { en: "pos.payment.method", fr: "pos.payment.method" },
    distractors: [
      { en: "pos.config", fr: "pos.config" },
      { en: "pos.session", fr: "pos.session" },
      { en: "account.payment", fr: "account.payment" },
    ],
    explanation: { en: "pos.payment.method defines a payment method (Cash, Bank, Custom) used at the POS. Each method links to a journal, an outstanding receipts account, and a label. Multiple methods can be enabled in a POS Config (pos.config). The session (pos.session) is opened/closed per shift and reconciles cash drawer to expected balance.\n\nWhy not \"pos.config\"? pos.config is the overall POS configuration; payment methods are linked to it but live in pos.payment.method.\n\nWhy not \"pos.session\"? pos.session is per-shift, not a method definition.\n\nWhy not \"account.payment\"? account.payment is in Accounting, not POS.", fr: "pos.payment.method définit une méthode de paiement (Espèces, Banque, Personnalisée) utilisée au PDV. Chaque méthode est liée à un journal, un compte d'encaissements en attente et un libellé. Plusieurs méthodes peuvent être activées dans une configuration PDV (pos.config)." },
  }),
  complexQ({
    id: "oep-081",
    module: "pos",
    text: { en: "Odoo 19 POS has a Restaurant feature. What does this enable?", fr: "Le PDV Odoo 19 a une fonctionnalité Restaurant. Qu'est-ce que cela active ?" },
    correct: { en: "Table maps, bill splitting, course sequencing, and kitchen print/KDS", fr: "Plans de table, partage de l'addition, séquencement des plats et impression cuisine/KDS" },
    distractors: [
      { en: "Wholesale B2B catalog ordering without table or course management", fr: "Commande catalogue B2B grossiste sans gestion de table ni de plats" },
      { en: "Simple street-market cash sales with no restaurant floor plan features", fr: "Ventes simples au comptant en marché sans fonctionnalités de plan de salle" },
      { en: "Online eLearning course pages published through the Website app", fr: "Pages de cours eLearning en ligne publiées via l'application Site Web" },
    ],
    explanation: { en: "Restaurant mode in POS adds floor plans (tables on a canvas), table service (assign waiter, hold/transfer tables), bill splitting (by item, by share, by customer), course management (entrée → main → dessert sequencing), and integrated kitchen printing or KDS (Kitchen Display System). It is widely used for cafes, bars, and full-service restaurants.\n\nWhy not \"Wholesale B2B catalog ordering without table or course management\"? Wholesale is a different B2B pattern.\n\nWhy not \"Simple street-market cash sales with no restaurant floor plan features\"? Street market POS is just standard POS.\n\nWhy not \"Online eLearning course pages published through the Website app\"? Online courses live in eLearning.", fr: "Le mode Restaurant dans le PDV ajoute des plans de salle (tables sur un canvas), le service en salle (assigner un serveur, mettre en attente/transférer les tables), le partage de l'addition (par article, par part, par client), la gestion des plats (entrée → plat → dessert) et l'impression cuisine intégrée ou KDS." },
  }),
  complexQ({
    id: "oep-082",
    module: "pos",
    text: { en: "What is the purpose of the Kitchen Display System (KDS) connected to Odoo 19 POS?", fr: "Quel est le rôle du système d'affichage cuisine (KDS) connecté au PDV Odoo 19 ?" },
    correct: { en: "Screen shows kitchen orders; cooks mark items done for waiter updates", fr: "L'écran affiche les commandes cuisine ; les cuisiniers marquent les articles terminés pour informer les serveurs" },
    distractors: [
      { en: "Tracks employee attendance hours from a kitchen tablet interface", fr: "Suit les heures de présence des employés depuis une interface tablette cuisine" },
      { en: "Replaces Accounting for posting restaurant revenue journal entries", fr: "Remplace la Comptabilité pour comptabiliser les écritures de revenus du restaurant" },
      { en: "Disables tipping and removes all payment methods from the POS config", fr: "Désactive les pourboires et supprime toutes les méthodes de paiement de la configuration PDV" },
    ],
    explanation: { en: "The Kitchen Display System (KDS) is a screen in the kitchen showing live orders broken into preparation lanes. Cooks acknowledge items as they begin and finish, which signals the front-of-house. This reduces lost paper tickets, helps track preparation times, and integrates seamlessly with course management for proper meal pacing.\n\nWhy not \"Tracks employee attendance hours from a kitchen tablet interface\"? Employee tracking is in HR/Attendances.\n\nWhy not \"Replaces Accounting for posting restaurant revenue journal entries\"? Accounting records revenue and payments; KDS only displays kitchen preparation queues.\n\nWhy not \"Disables tipping and removes all payment methods from the POS config\"? Tipping is configured separately at POS, unaffected by KDS.", fr: "Le système d'affichage cuisine (KDS) est un écran en cuisine affichant les commandes en direct réparties en lignes de préparation. Les cuisiniers accusent réception des articles au début et à la fin, ce qui signale la salle. Cela réduit les tickets papier perdus et aide à suivre les temps de préparation." },
  }),
  complexQ({
    id: "oep-083",
    module: "pos",
    text: { en: "A POS session is closed at the end of the day in Odoo 19. What happens with the cash count?", fr: "Une session PDV est clôturée en fin de journée dans Odoo 19. Que se passe-t-il avec le comptage de caisse ?" },
    correct: { en: "The cashier enters counted cash", fr: "Le caissier saisit le montant compté en caisse" },
    distractors: [
      { en: "Cash is automatically deposited", fr: "L'argent est automatiquement déposé" },
      { en: "The session cannot be closed without a sale", fr: "La session ne peut pas être clôturée sans vente" },
      { en: "Cash is ignored", fr: "L'argent liquide est ignoré" },
    ],
    explanation: { en: "Closing a POS session shows expected balance per payment method (cash, card, etc.) vs counted balance. The cashier records the count; any difference posts to a configured Difference account (e.g., Cash Over/Short). Odoo creates the corresponding accounting entries to move cash from the POS journal to the bank, ensuring cashier cash is reconciled with the GL daily.\n\nWhy not \"Cash is automatically deposited\"? There is no automatic deposit; it is a manual count and post.\n\nWhy not \"The session cannot be closed without a sale\"? Sessions can be closed even with zero sales, e.g., a closed day.\n\nWhy not \"Cash is ignored\"? Cash differences are tracked, not ignored.", fr: "La clôture d'une session PDV affiche le solde attendu par méthode de paiement (espèces, carte, etc.) vs le solde compté. Le caissier enregistre le comptage ; tout écart est comptabilisé sur un compte d'écart configuré (ex. : Surplus/Déficit de caisse). Odoo crée les écritures comptables correspondantes." },
  }),
  complexQ({
    id: "oep-084",
    module: "pos",
    text: { en: "A consultant wants the POS to integrate with Inventory so each sale reduces stock in real time in Odoo 19. What ensures this?", fr: "Un consultant veut que le PDV s'intègre à l'Inventaire pour que chaque vente réduise le stock en temps réel dans Odoo 19. Qu'est-ce qui garantit cela ?" },
    correct: { en: "POS source location on stock; moves post on session close or per order", fr: "Emplacement source PDV sur le stock ; les mouvements sont comptabilisés à la clôture de session ou par commande" },
    distractors: [
      { en: "POS sales never touch inventory; stock is adjusted manually each week", fr: "Les ventes PDV ne touchent jamais l'inventaire ; le stock est ajusté manuellement chaque semaine" },
      { en: "Only Studio automations can decrement inventory after POS checkout", fr: "Seules les automatisations Studio peuvent décrémenter l'inventaire après un passage en caisse PDV" },
      { en: "Cashiers must validate a delivery order after every POS transaction", fr: "Les caissiers doivent valider un bon de livraison après chaque transaction PDV" },
    ],
    explanation: { en: "POS sales generate stock moves that reduce inventory at the configured POS source location. Depending on the configuration, moves are posted per order or aggregated when the session closes. The Anglo-Saxon vs Continental valuation method affects whether COGS lines are posted to the GL. Cross-checks against Inventory keep on-hand data accurate.\n\nWhy not \"POS sales never touch inventory; stock is adjusted manually each week\"? POS does affect stock by default.\n\nWhy not \"Only Studio automations can decrement inventory after POS checkout\"? Studio is not required for stock integration.\n\nWhy not \"Cashiers must validate a delivery order after every POS transaction\"? It happens automatically, not manually.", fr: "Les ventes PDV génèrent des mouvements de stock qui réduisent l'inventaire à l'emplacement source PDV configuré. Selon la configuration, les mouvements sont comptabilisés par commande ou agrégés à la clôture de session." },
  }),
  complexQ({
    id: "oep-085",
    module: "studio",
    text: { en: "A consultant wants to add a custom field 'Customer Loyalty Tier' on the partner form without writing code. Which Odoo 19 Enterprise tool is used?", fr: "Un consultant veut ajouter un champ personnalisé « Niveau de fidélité client » sur le formulaire de contact sans écrire de code. Quel outil Odoo 19 Enterprise est utilisé ?" },
    correct: { en: "Studio", fr: "Studio" },
    distractors: [
      { en: "Discuss", fr: "Discuss" },
      { en: "Sign", fr: "Sign" },
      { en: "Knowledge", fr: "Knowledge" },
    ],
    explanation: { en: "Studio (Enterprise) is the no-code customization tool. With Studio, you can add fields to any form, change layouts, build new menus and reports, customize automated actions, and modify access. Studio writes the changes as XML data into the database without altering source code, making them upgrade-friendly.\n\nWhy not \"Discuss\"? Discuss provides team messaging channels, not no-code form customization through Studio.\n\nWhy not \"Sign\"? Sign handles document signatures, not adding custom fields on partner forms.\n\nWhy not \"Knowledge\"? Knowledge is for wiki articles.", fr: "Studio (Enterprise) est l'outil de personnalisation sans code. Avec Studio, vous pouvez ajouter des champs à n'importe quel formulaire, modifier les dispositions, créer de nouveaux menus et rapports, personnaliser les actions automatisées et modifier les droits d'accès." },
  }),
  complexQ({
    id: "oep-086",
    module: "studio",
    text: { en: "Studio in Odoo 19 lets you create Automated Actions. What is the difference between a Server Action and an Automated Action?", fr: "Studio dans Odoo 19 permet de créer des actions automatisées. Quelle est la différence entre une action serveur et une action automatisée ?" },
    correct: { en: "Server Actions run on demand; Automated Actions add creation/time triggers", fr: "Les actions serveur s'exécutent à la demande ; les actions automatisées ajoutent des déclencheurs de création/temps" },
    distractors: [
      { en: "They are the same object with no difference in trigger or execution model", fr: "C'est le même objet sans différence de déclencheur ni de modèle d'exécution" },
      { en: "Automated Actions cannot run Python code under any security configuration", fr: "Les actions automatisées ne peuvent pas exécuter de code Python quelle que soit la configuration de sécurité" },
      { en: "Server Actions were removed in Odoo 19 and replaced entirely by Studio", fr: "Les actions serveur ont été supprimées dans Odoo 19 et entièrement remplacées par Studio" },
    ],
    explanation: { en: "ir.actions.server is the Server Action — it can be called explicitly from a button, menu, or automated action. base.automation (Automated Actions) wraps a server action with a trigger (record created/written/deleted, time-based, on tag added/removed, on state change). Both can run Python code if user has the right permissions.\n\nWhy not \"They are the same object with no difference in trigger or execution model\"? They serve different roles in the architecture.\n\nWhy not \"Automated Actions cannot run Python code under any security configuration\"? Both can run Python code (with appropriate access).\n\nWhy not \"Server Actions were removed in Odoo 19 and replaced entirely by Studio\"? Server Actions are core and not deprecated.", fr: "ir.actions.server est l'action serveur — elle peut être appelée explicitement depuis un bouton, un menu ou une action automatisée. base.automation (Actions automatisées) encapsule une action serveur avec un déclencheur (enregistrement créé/modifié/supprimé, basé sur le temps, sur l'ajout/suppression d'étiquette, sur le changement d'état)." },
  }),
  complexQ({
    id: "oep-087",
    module: "studio",
    text: { en: "A consultant uses Studio to add a new menu under Sales with a custom kanban view of opportunities. What does Studio create technically?", fr: "Un consultant utilise Studio pour ajouter un nouveau menu sous Ventes avec une vue kanban personnalisée des opportunités. Que crée Studio techniquement ?" },
    correct: { en: "XML records (ir.ui.menu", fr: "Des enregistrements XML (ir.ui.menu" },
    distractors: [
      { en: "A new Python module installed dynamically", fr: "Un nouveau module Python installé dynamiquement" },
      { en: "A separate server", fr: "Un serveur séparé" },
      { en: "Nothing — only display tweaks", fr: "Rien — uniquement des ajustements d'affichage" },
    ],
    explanation: { en: "Studio writes its customizations as XML records in the database: menus, actions, and views. These are versioned and can be exported to a custom module for migration to other databases. Studio does not require server restart or module installation; everything happens in the running database.\n\nWhy not \"A new Python module installed dynamically\"? No new Python module is installed; XML records are written.\n\nWhy not \"A separate server\"? Studio works on the same server.\n\nWhy not \"Nothing — only display tweaks\"? Studio creates real records that drive functionality, not just visual tweaks.", fr: "Studio écrit ses personnalisations sous forme d'enregistrements XML dans la base de données : menus, actions et vues. Ceux-ci sont versionnés et peuvent être exportés vers un module personnalisé pour migration vers d'autres bases de données. Studio ne nécessite pas de redémarrage du serveur." },
  }),
  complexQ({
    id: "oep-088",
    module: "studio",
    text: { en: "Studio Reports in Odoo 19 let users design a printable PDF. What underlying engine renders the PDF?", fr: "Les rapports Studio dans Odoo 19 permettent de concevoir un PDF imprimable. Quel moteur sous-jacent rend le PDF ?" },
    correct: { en: "QWeb templates rendered to HTML", fr: "Templates QWeb rendus en HTML" },
    distractors: [
      { en: "LaTeX", fr: "LaTeX" },
      { en: "Microsoft Word integration only", fr: "Intégration Microsoft Word uniquement" },
      { en: "JasperReports", fr: "JasperReports" },
    ],
    explanation: { en: "Odoo's reporting engine uses QWeb templates to produce HTML, which is then converted to PDF by wkhtmltopdf (or an alternative renderer). Studio Report Designer offers a drag-and-drop UI on top of QWeb so users can place fields, headers, footers, and conditional sections without writing XML.\n\nWhy not \"LaTeX\"? Odoo renders PDFs from QWeb HTML; LaTeX is not part of the reporting engine.\n\nWhy not \"Microsoft Word integration only\"? Word is not the rendering engine.\n\nWhy not \"JasperReports\"? JasperReports is not Odoo's engine.", fr: "Le moteur de rapports d'Odoo utilise des templates QWeb pour produire du HTML, qui est ensuite converti en PDF par wkhtmltopdf (ou un moteur alternatif). Le concepteur de rapports Studio offre une interface glisser-déposer par-dessus QWeb." },
  }),
  complexQ({
    id: "oep-089",
    module: "studio",
    text: { en: "A consultant wants to extend a model in Studio to add a Many2one field linking customers to a custom 'Industry Vertical' lookup. Which Odoo 19 step is correct?", fr: "Un consultant veut étendre un modèle dans Studio pour ajouter un champ Many2one liant les clients à un référentiel personnalisé « Secteur d'activité ». Quelle étape Odoo 19 est correcte ?" },
    correct: { en: "Studio on res.partner: add Many2one to x_industry_vertical model and save", fr: "Studio sur res.partner : ajouter un Many2one vers le modèle x_industry_vertical et sauvegarder" },
    distractors: [
      { en: "Edit PostgreSQL tables directly with ALTER TABLE in production SQL", fr: "Modifier les tables PostgreSQL directement avec ALTER TABLE en SQL de production" },
      { en: "Translate labels only in base.po without creating any new field", fr: "Traduire les libellés uniquement dans base.po sans créer de nouveau champ" },
      { en: "Override the Python res.partner class in Odoo core source code", fr: "Surcharger la classe Python res.partner dans le code source Odoo" },
    ],
    explanation: { en: "In Studio, you add a Many2one field by selecting the field type, choosing/creating the target model (Studio prefixes custom models with x_), labeling it, and saving. Studio creates the column and metadata automatically. Direct SQL is unsafe and bypasses ORM rules; modifying core code is unnecessary for this simple extension.\n\nWhy not \"Edit PostgreSQL tables directly with ALTER TABLE in production SQL\"? SQL bypasses ORM, breaking constraints, audit, and migration.\n\nWhy not \"Translate labels only in base.po without creating any new field\"? base.po is for translations.\n\nWhy not \"Override the Python res.partner class in Odoo core source code\"? Studio handles this without core overrides.", fr: "Dans Studio, vous ajoutez un champ Many2one en sélectionnant le type de champ, en choisissant/créant le modèle cible (Studio préfixe les modèles personnalisés avec x_), en le nommant et en sauvegardant. Studio crée automatiquement la colonne et les métadonnées." },
  }),
  complexQ({
    id: "oep-090",
    module: "studio",
    text: { en: "A consultant wants to require a manager's approval before a Purchase Order can be confirmed in Odoo 19. Which no-code feature handles this?", fr: "Un consultant veut exiger l'approbation d'un responsable avant qu'un bon de commande fournisseur puisse être confirmé dans Odoo 19. Quelle fonctionnalité sans code gère cela ?" },
    correct: { en: "Studio Approval rules with amount conditions and approver user groups", fr: "Règles d'approbation Studio avec conditions de montant et groupes d'approbateurs" },
    distractors: [
      { en: "A custom Python module overriding purchase.order confirm in core", fr: "Un module Python personnalisé surchargeant le confirm de purchase.order dans le code source" },
      { en: "An external webhook with no in-Odoo approval dialog or notification", fr: "Un webhook externe sans dialogue ni notification d'approbation dans Odoo" },
      { en: "Studio cannot gate confirmations; only Purchase Settings thresholds apply", fr: "Studio ne peut pas bloquer les confirmations ; seuls les seuils des Paramètres d'achat s'appliquent" },
    ],
    explanation: { en: "Studio Approvals (Enterprise) lets you define approval rules tied to a model and operation. For example, on purchase.order confirm, require approval from the Purchase Manager group when the amount exceeds $10K. The user clicking confirm sees an approval dialog; the approver receives a notification. All without writing code.\n\nWhy not \"A custom Python module overriding purchase.order confirm in core\"? Custom Python is not required for standard approvals.\n\nWhy not \"An external webhook with no in-Odoo approval dialog or notification\"? Webhooks are unrelated to approval gates.\n\nWhy not \"Studio cannot gate confirmations; only Purchase Settings thresholds apply\"? Studio supports approvals natively.", fr: "Les approbations Studio (Enterprise) permettent de définir des règles d'approbation liées à un modèle et une opération. Par exemple, sur purchase.order confirm, exiger l'approbation du groupe Responsable des achats lorsque le montant dépasse 10K $. L'utilisateur cliquant sur confirmer voit un dialogue d'approbation." },
  }),
  complexQ({
    id: "oep-091",
    module: "studio",
    text: { en: "What is the function of access groups in Odoo 19 (e.g., Sales / User: All Documents vs Sales / User: Own Documents only)?", fr: "Quelle est la fonction des groupes d'accès dans Odoo 19 (ex. : Ventes / Utilisateur : Tous les documents vs Ventes / Utilisateur : Documents personnels uniquement) ?" },
    correct: { en: "Groups bind sets of permissions and record rules to users", fr: "Les groupes lient des ensembles de permissions et des règles d'enregistrement aux utilisateurs" },
    distractors: [
      { en: "Groups are only labels", fr: "Les groupes sont uniquement des étiquettes" },
      { en: "Groups cannot restrict records", fr: "Les groupes ne peuvent pas restreindre les enregistrements" },
      { en: "Groups apply only to inventory", fr: "Les groupes s'appliquent uniquement à l'inventaire" },
    ],
    explanation: { en: "res.groups is the security group model. Groups are linked to model access rights (CRUD per model) and to record rules (filters that constrain which records a user can read/write). The 'Own Documents Only' vs 'All Documents' pattern in Sales is a record rule that restricts a user to their own opportunities/quotations unless they are in the all-documents group.\n\nWhy not \"Groups are only labels\"? Groups are functional, not just labels.\n\nWhy not \"Groups cannot restrict records\"? Record rules attached to groups absolutely restrict records.\n\nWhy not \"Groups apply only to inventory\"? Groups apply to every model, not just inventory.", fr: "res.groups est le modèle de groupe de sécurité. Les groupes sont liés aux droits d'accès par modèle (CRUD par modèle) et aux règles d'enregistrement (filtres qui restreignent quels enregistrements un utilisateur peut lire/écrire). Le modèle « Documents personnels uniquement » vs « Tous les documents » dans Ventes est une règle d'enregistrement." },
  }),
  complexQ({
    id: "oep-092",
    module: "studio",
    text: { en: "Multi-company in Odoo 19 lets one database serve multiple legal entities. How is data isolated between companies?", fr: "Le multi-sociétés dans Odoo 19 permet à une seule base de données de servir plusieurs entités juridiques. Comment les données sont-elles isolées entre les sociétés ?" },
    correct: { en: "Many models include a company_id field", fr: "De nombreux modèles incluent un champ company_id" },
    distractors: [
      { en: "By creating multiple databases", fr: "En créant plusieurs bases de données" },
      { en: "Only via separate servers", fr: "Uniquement via des serveurs séparés" },
      { en: "It is not supported", fr: "Ce n'est pas supporté" },
    ],
    explanation: { en: "Multi-company uses a company_id field on records (most models include it) and security rules that limit each user to their assigned companies. Users select an active company via the company switcher in the navbar. Shared resources (catalog, partners) can be company-scoped or global. Inter-company rules can automate transactions like inter-company sales/purchases.\n\nWhy not \"By creating multiple databases\"? Multiple databases is multi-database, not multi-company.\n\nWhy not \"Only via separate servers\"? One Odoo server can host many companies.\n\nWhy not \"It is not supported\"? It is fully supported and widely used.", fr: "Le multi-sociétés utilise un champ company_id sur les enregistrements (la plupart des modèles l'incluent) et des règles de sécurité qui limitent chaque utilisateur à ses sociétés assignées. Les utilisateurs sélectionnent une société active via le sélecteur de société dans la barre de navigation." },
  }),
  complexQ({
    id: "oep-093",
    module: "studio",
    text: { en: "A consultant must make Odoo 19 available in French and Spanish for users in the same company. Which step is required?", fr: "Un consultant doit rendre Odoo 19 disponible en français et en espagnol pour les utilisateurs d'une même société. Quelle étape est nécessaire ?" },
    correct: { en: "Settings > Translations > Load a Translation; set user preferred language", fr: "Paramètres > Traductions > Charger une traduction ; définir la langue préférée de l'utilisateur" },
    distractors: [
      { en: "Modify core Python translation files and redeploy the Odoo server code", fr: "Modifier les fichiers de traduction Python de base et redéployer le code du serveur Odoo" },
      { en: "Provision a separate Odoo database for each language your company uses", fr: "Provisionner une base de données Odoo séparée pour chaque langue utilisée par la société" },
      { en: "Odoo user interface supports English only with no translation packs", fr: "L'interface utilisateur Odoo ne supporte que l'anglais sans packs de traduction" },
    ],
    explanation: { en: "Languages are installed via Settings > Translations > Load a Translation (or General Settings > Languages section). Once installed, each user can pick their preferred language in their preferences; the UI and many emails switch instantly. Translatable fields (product names, descriptions) can carry per-language values. Country localizations may install their primary language automatically.\n\nWhy not \"Modify core Python translation files and redeploy the Odoo server code\"? No source-code change is needed.\n\nWhy not \"Provision a separate Odoo database for each language your company uses\"? One database supports many languages.\n\nWhy not \"Odoo user interface supports English only with no translation packs\"? Odoo supports dozens of languages.", fr: "Les langues sont installées via Paramètres > Traductions > Charger une traduction (ou la section Langues des Paramètres généraux). Une fois installée, chaque utilisateur peut choisir sa langue préférée dans ses préférences ; l'interface et de nombreux e-mails changent instantanément." },
  }),
  complexQ({
    id: "oep-094",
    module: "studio",
    text: { en: "A consultant wants to send templated emails (e.g., quotation sent, invoice due reminder) in Odoo 19. Which mechanism is used?", fr: "Un consultant veut envoyer des e-mails modèles (ex. : devis envoyé, rappel de facture due) dans Odoo 19. Quel mécanisme est utilisé ?" },
    correct: { en: "mail.template records with QWeb body and dynamic field placeholders", fr: "Enregistrements mail.template avec corps QWeb et champs dynamiques de fusion" },
    distractors: [
      { en: "Studio PDF report layouts without any mail.template email definitions", fr: "Mises en page de rapports PDF Studio sans aucune définition d'e-mail mail.template" },
      { en: "Sign documents for legally binding signatures on outbound messages", fr: "Documents Sign pour des signatures juridiquement contraignantes sur les messages sortants" },
      { en: "Discuss channels for ad-hoc chat without reusable email templates", fr: "Canaux Discuss pour du chat ad-hoc sans modèles d'e-mails réutilisables" },
    ],
    explanation: { en: "Email templates (mail.template) define a subject line, body (QWeb / HTML), recipients, and attachments. Placeholders use Jinja-like / QWeb syntax to inject record data. Templates are bound to a model (e.g., sale.order) and can be triggered manually (Send by Email button) or by automated actions (e.g., reminder X days before due date).\n\nWhy not \"Studio PDF report layouts without any mail.template email definitions\"? Studio reports produce PDFs, not email content directly.\n\nWhy not \"Sign documents for legally binding signatures on outbound messages\"? Sign is for e-signature workflows, not defining reusable outbound email templates.\n\nWhy not \"Discuss channels for ad-hoc chat without reusable email templates\"? Discuss handles internal chat, not templated emails.", fr: "Les modèles d'e-mails (mail.template) définissent un objet, un corps (QWeb / HTML), des destinataires et des pièces jointes. Les champs dynamiques utilisent la syntaxe Jinja/QWeb pour injecter les données de l'enregistrement. Les modèles sont liés à un modèle (ex. : sale.order)." },
  }),
  complexQ({
    id: "oep-095",
    module: "studio",
    text: { en: "What is a Scheduled Action (ir.cron) in Odoo 19?", fr: "Qu'est-ce qu'une action planifiée (ir.cron) dans Odoo 19 ?" },
    correct: { en: "ir.cron scheduled job executing a server action on a recurring interval", fr: "Tâche planifiée ir.cron exécutant une action serveur à intervalle récurrent" },
    distractors: [
      { en: "A one-time manual action with no database scheduler backing it", fr: "Une action manuelle ponctuelle sans planificateur de base de données" },
      { en: "A personal calendar reminder visible only in the user agenda view", fr: "Un rappel de calendrier personnel visible uniquement dans la vue agenda de l'utilisateur" },
      { en: "A Discuss meeting invite sent to channel participants", fr: "Une invitation de réunion Discuss envoyée aux participants du canal" },
    ],
    explanation: { en: "Scheduled Actions (ir.cron) execute Python code or method calls on a configured frequency. Many built-in features rely on them: MRP/procurement scheduler, expired pricelist refresh, queue retries, recurring invoices, automated follow-ups. Admins can pause, force-run, or change frequency. Developers can add new cron jobs via XML data files.\n\nWhy not \"A one-time manual action with no database scheduler backing it\"? They are recurring by definition.\n\nWhy not \"A personal calendar reminder visible only in the user agenda view\"? Calendar reminders are calendar.event-related.\n\nWhy not \"A Discuss meeting invite sent to channel participants\"? Meeting invites are different objects.", fr: "Les actions planifiées (ir.cron) exécutent du code Python ou des appels de méthode selon une fréquence configurée. De nombreuses fonctionnalités intégrées en dépendent : planificateur MRP/approvisionnement, rafraîchissement des listes de prix expirées, relances de file d'attente, factures récurrentes, relances automatisées." },
  }),
  complexQ({
    id: "oep-096",
    module: "studio",
    text: { en: "Odoo 19 was released by Odoo S.A. as a new major version. Approximately when was Odoo 19 released?", fr: "Odoo 19 a été publié par Odoo S.A. comme nouvelle version majeure. Quand environ Odoo 19 a-t-il été publié ?" },
    correct: { en: "September 2025 at Odoo Experience", fr: "Septembre 2025 lors de l'Odoo Experience" },
    distractors: [
      { en: "January 2024", fr: "Janvier 2024" },
      { en: "Late 2023", fr: "Fin 2023" },
      { en: "It is not released yet", fr: "Il n'est pas encore sorti" },
    ],
    explanation: { en: "Odoo 19 was announced and released around Odoo Experience in September 2025, the company's annual conference where new versions are traditionally launched. Each major release brings updated apps, performance improvements, and new features such as enhanced AI integrations and refreshed UI elements compared to Odoo 18.\n\nWhy not \"January 2024\"? January 2024 was the era of v17.\n\nWhy not \"Late 2023\"? Late 2023 corresponds to the Odoo 17 release window, not the Odoo 19 major version.\n\nWhy not \"It is not released yet\"? Odoo 19 is the current LTS as of 2026.", fr: "Odoo 19 a été annoncé et publié autour de l'Odoo Experience en septembre 2025, la conférence annuelle de l'entreprise où les nouvelles versions sont traditionnellement lancées." },
  }),
  complexQ({
    id: "oep-097",
    module: "studio",
    text: { en: "A new consultant must understand the difference between Odoo Community and Enterprise. Which capability is Enterprise-only?", fr: "Un nouveau consultant doit comprendre la différence entre Odoo Community et Enterprise. Quelle capacité est exclusivement Enterprise ?" },
    correct: { en: "Studio, Documents, Helpdesk, and advanced Accounting (Enterprise add-ons)", fr: "Studio, Documents, Helpdesk et la Comptabilité avancée (modules complémentaires Enterprise)" },
    distractors: [
      { en: "Sales quotations and orders (available in Community and Enterprise)", fr: "Devis et commandes de ventes (disponibles dans Community et Enterprise)" },
      { en: "CRM pipelines and lead tracking (available in Community and Enterprise)", fr: "Pipelines CRM et suivi des pistes (disponibles dans Community et Enterprise)" },
      { en: "Inventory routes and stock valuation (available in Community and Enterprise)", fr: "Routes d'inventaire et valorisation des stocks (disponibles dans Community et Enterprise)" },
    ],
    explanation: { en: "Community (open source) covers Sales, CRM, Inventory, Purchase, Manufacturing (basic), Project, Website, eCommerce. Enterprise adds Studio, Documents, Helpdesk, advanced Accounting (with full reporting and bank sync), Marketing Automation, Field Service, Subscriptions, Planning, Quality, native iOS/Android apps, IoT integrations, and more. Many implementations need Enterprise for accounting localizations and customization.\n\nWhy not \"Sales quotations and orders (available in Community and Enterprise)\"? Sales is in both editions.\n\nWhy not \"CRM pipelines and lead tracking (available in Community and Enterprise)\"? CRM is included in both Community and Enterprise; it is not Enterprise-only.\n\nWhy not \"Inventory routes and stock valuation (available in Community and Enterprise)\"? Inventory is in both editions.", fr: "Community (open source) couvre Ventes, CRM, Inventaire, Achats, Fabrication (basique), Projet, Site Web, eCommerce. Enterprise ajoute Studio, Documents, Helpdesk, Comptabilité avancée (avec reporting complet et synchronisation bancaire), Automatisation Marketing, Field Service, Abonnements, Planification, Qualité, et plus encore." },
  }),
  complexQ({
    id: "oep-098",
    module: "studio",
    text: { en: "A consultant configures a sequence on a custom model in Odoo 19 so each new record auto-numbers as INV/2026/00001. Which model holds sequence definitions?", fr: "Un consultant configure une séquence sur un modèle personnalisé dans Odoo 19 pour que chaque nouvel enregistrement soit auto-numéroté comme INV/2026/00001. Quel modèle stocke les définitions de séquence ?" },
    correct: { en: "ir.sequence", fr: "ir.sequence" },
    distractors: [
      { en: "res.sequence", fr: "res.sequence" },
      { en: "model.sequence", fr: "model.sequence" },
      { en: "auto.number", fr: "auto.number" },
    ],
    explanation: { en: "ir.sequence stores sequence definitions: code (used to fetch the next value), prefix (with date variables like %(year)s), padding, and increment. Models like sale.order, account.move, and stock.picking call ir.sequence.next_by_code() to get the next value. Sequences can reset yearly/monthly with date_range entries.\n\nWhy not \"res.sequence\"? res.sequence is not the model.\n\nWhy not \"model.sequence\"? model.sequence is not real.\n\nWhy not \"auto.number\"? auto.number is not a real Odoo model; sequence definitions live in ir.sequence.", fr: "ir.sequence stocke les définitions de séquence : code (utilisé pour récupérer la prochaine valeur), préfixe (avec des variables de date comme %(year)s), complément de zéros et incrément. Les modèles comme sale.order, account.move et stock.picking appellent ir.sequence.next_by_code() pour obtenir la prochaine valeur." },
  }),
  complexQ({
    id: "oep-099",
    module: "studio",
    text: { en: "A consultant wants to take advantage of Odoo 19's improved UI. Compared to Odoo 18, Odoo 19 generally:", fr: "Un consultant veut tirer parti de l'interface utilisateur améliorée d'Odoo 19. Par rapport à Odoo 18, Odoo 19 offre généralement :" },
    correct: { en: "Refined UI tokens, faster list/kanban views, broader AI-assisted features", fr: "Des tokens d'interface affinés, des vues liste/kanban plus rapides, des fonctionnalités IA plus étendues" },
    distractors: [
      { en: "Kanban view removed entirely from all Odoo 19 applications", fr: "La vue kanban entièrement supprimée de toutes les applications Odoo 19" },
      { en: "Studio module discontinued and replaced by external customization SaaS", fr: "Le module Studio abandonné et remplacé par un SaaS de personnalisation externe" },
      { en: "Multi-company support removed from the Odoo 19 platform architecture", fr: "Le support multi-sociétés supprimé de l'architecture de la plateforme Odoo 19" },
    ],
    explanation: { en: "Odoo 19's release notes emphasize a refined visual language, performance improvements (especially on large list/kanban renders), enhanced AI-assisted writing and suggestions across apps, deeper Spreadsheet capabilities, and continued localization improvements. Major architectural pillars (multi-company, Studio, kanban, Enterprise apps) remain — they are typically extended, not removed.\n\nWhy not \"Kanban view removed entirely from all Odoo 19 applications\"? Kanban views remain a core layout.\n\nWhy not \"Studio module discontinued and replaced by external customization SaaS\"? Studio is a flagship Enterprise module and is retained.\n\nWhy not \"Multi-company support removed from the Odoo 19 platform architecture\"? Multi-company is foundational and supported.", fr: "Les notes de version d'Odoo 19 mettent l'accent sur un langage visuel affiné, des améliorations de performance (surtout sur les rendus de grandes listes/kanban), la rédaction et les suggestions assistées par IA dans toutes les applications, des capacités de tableur étendues et des améliorations continues de localisation." },
  }),
  complexQ({
    id: "oep-100",
    module: "studio",
    text: { en: "An Odoo 19 functional consultant prepares a go-live. Which sequence is the recommended approach when migrating data into a fresh Odoo database?", fr: "Un consultant fonctionnel Odoo 19 prépare une mise en production. Quelle séquence est l'approche recommandée pour migrer des données dans une nouvelle base Odoo ?" },
    correct: { en: "Configure COA/taxes, import masters, open balances, opening entry, go-live", fr: "Configurer le plan comptable/taxes, importer les données maîtres, soldes d'ouverture, écriture d'ouverture, mise en production" },
    distractors: [
      { en: "Import partners, products, and transactions in one unordered CSV batch", fr: "Importer les partenaires, produits et transactions dans un seul lot CSV non ordonné" },
      { en: "Build Studio customizations before defining chart of accounts or taxes", fr: "Construire les personnalisations Studio avant de définir le plan comptable ou les taxes" },
      { en: "Skip master configuration and begin daily transactions on a blank database", fr: "Ignorer la configuration maître et commencer les transactions quotidiennes sur une base vierge" },
    ],
    explanation: { en: "A standard Odoo go-live follows: configuration first (so taxes/accounts exist for transaction imports), then master data, then open transactional balances at cutover, then opening trial balance, then user training. Imports use Odoo's Import tool (CSV/XLSX) with external IDs to maintain relationships. Skipping order leads to broken references and re-imports.\n\nWhy not \"Import partners, products, and transactions in one unordered CSV batch\"? Order matters — imports without configuration fail or import partial data.\n\nWhy not \"Build Studio customizations before defining chart of accounts or taxes\"? Customizations should layer on top of standard processes, not before configuration.\n\nWhy not \"Skip master configuration and begin daily transactions on a blank database\"? Skipping configuration leads to non-functional accounting and broken workflows.", fr: "Une mise en production Odoo standard suit : configuration d'abord (pour que les taxes/comptes existent pour les imports de transactions), puis les données maîtres, puis les soldes transactionnels ouverts au basculement, puis la balance de vérification d'ouverture, puis la formation des utilisateurs." },
  }),
  complexQ({
    id: "oep-101",
    module: "marketing",
    text: { en: "A marketing manager wants to test two email subject lines on a campaign in Odoo 19. Which Email Marketing feature supports this?", fr: "Un responsable marketing veut tester deux objets d'e-mail sur une campagne dans Odoo 19. Quelle fonctionnalité d'Email Marketing supporte cela ?" },
    correct: { en: "A/B testing with a sample percentage and winner selection metric", fr: "Tests A/B avec un pourcentage d'échantillon et une métrique de sélection du gagnant" },
    distractors: [
      { en: "Survey scoring with pass/fail thresholds on responses", fr: "Scoring d'enquête avec seuils de réussite/échec sur les réponses" },
      { en: "POS loyalty point accrual rules on checkout", fr: "Règles d'accumulation de points de fidélité PDV au passage en caisse" },
      { en: "Studio approval gates before an email is sent", fr: "Portes d'approbation Studio avant l'envoi d'un e-mail" },
    ],
    explanation: { en: "Email Marketing supports A/B tests on subject lines (and sometimes content). You send variants to a sample, wait for opens/clicks, then mail the winning version to the remainder. This is native to the Marketing app, not Studio or POS.\n\nWhy not \"Survey scoring with pass/fail thresholds on responses\"? Survey scoring evaluates quiz answers, not email subject-line performance.\n\nWhy not \"POS loyalty point accrual rules on checkout\"? POS loyalty rules apply at retail checkout, not to mass email campaigns.\n\nWhy not \"Studio approval gates before an email is sent\"? Studio approvals gate business documents; they are not the Email Marketing A/B test tool.", fr: "Email Marketing prend en charge les tests A/B sur les objets d'e-mail (et parfois le contenu). Vous envoyez les variantes à un échantillon, attendez les ouvertures/clics, puis envoyez la version gagnante au reste." },
  }),
  complexQ({
    id: "oep-102",
    module: "marketing",
    text: { en: "In Odoo 19 Marketing Automation, what starts a workflow when a contact downloads a specific whitepaper from the website?", fr: "Dans l'Automatisation Marketing Odoo 19, qu'est-ce qui démarre un workflow lorsqu'un contact télécharge un livre blanc spécifique depuis le site web ?" },
    correct: { en: "A trigger such as \"Page visited\" or a tracked link/UTM tied to the campaign", fr: "Un déclencheur tel que « Page visitée » ou un lien suivi/UTM lié à la campagne" },
    distractors: [
      { en: "A manufacturing reordering rule on the product template", fr: "Une règle de réapprovisionnement de fabrication sur le modèle de produit" },
      { en: "A bank reconciliation model matching statement lines", fr: "Un modèle de lettrage bancaire correspondant aux lignes de relevé" },
      { en: "A POS session opening cash count", fr: "Un comptage de caisse d'ouverture de session PDV" },
    ],
    explanation: { en: "Marketing Automation workflows begin on triggers like page visits, link clicks, form submissions, or time delays. A whitepaper download is typically tracked via a campaign link or website page rule that enrolls the contact in the workflow.\n\nWhy not \"A manufacturing reordering rule on the product template\"? Reordering rules replenish stock; they do not enroll marketing contacts.\n\nWhy not \"A bank reconciliation model matching statement lines\"? Reconciliation models match bank transactions, not website downloads.\n\nWhy not \"A POS session opening cash count\"? POS session opening records cashier cash, unrelated to marketing enrollment.", fr: "Les workflows d'automatisation marketing démarrent sur des déclencheurs comme les visites de page, les clics sur liens, les soumissions de formulaire ou les délais. Un téléchargement de livre blanc est généralement suivi via un lien de campagne ou une règle de page web qui inscrit le contact dans le workflow." },
  }),
  complexQ({
    id: "oep-103",
    module: "marketing",
    text: { en: "Which Odoo 19 app sends bulk promotional text messages to opted-in contacts?", fr: "Quelle application Odoo 19 envoie des SMS promotionnels en masse aux contacts ayant donné leur consentement ?" },
    correct: { en: "SMS Marketing with recipient lists and compliance opt-out handling", fr: "SMS Marketing avec listes de destinataires et gestion de la conformité de désinscription" },
    distractors: [
      { en: "Knowledge articles shared as SMS from the wiki editor", fr: "Articles Knowledge partagés par SMS depuis l'éditeur wiki" },
      { en: "Inventory barcode transfers pushed as text alerts", fr: "Transferts de code-barres d'inventaire envoyés comme alertes texte" },
      { en: "Discuss channels broadcasting internal chat only", fr: "Canaux Discuss diffusant uniquement du chat interne" },
    ],
    explanation: { en: "SMS Marketing sends campaigns to mailing lists with provider credits (IAP). Opt-out links and blacklist rules keep compliance. It is separate from Discuss internal chat and from Knowledge documentation.\n\nWhy not \"Knowledge articles shared as SMS from the wiki editor\"? Knowledge publishes articles; it is not a bulk SMS campaign tool.\n\nWhy not \"Inventory barcode transfers pushed as text alerts\"? Barcode operations update stock moves, not customer SMS campaigns.\n\nWhy not \"Discuss channels broadcasting internal chat only\"? Discuss handles team chat, not promotional SMS to external contacts.", fr: "SMS Marketing envoie des campagnes à des listes de diffusion avec des crédits fournisseur (IAP). Les liens de désinscription et les règles de liste noire assurent la conformité." },
  }),
  complexQ({
    id: "oep-104",
    module: "marketing",
    text: { en: "A trainer builds a certification quiz in Odoo 19 Surveys. How can a passing score be enforced?", fr: "Un formateur construit un quiz de certification dans Odoo 19 Enquêtes. Comment un score de passage peut-il être imposé ?" },
    correct: { en: "Set scoring on questions and define a minimum % to pass on the survey", fr: "Définir le scoring sur les questions et définir un pourcentage minimum pour réussir l'enquête" },
    distractors: [
      { en: "Require a POS payment before the survey opens", fr: "Exiger un paiement PDV avant l'ouverture de l'enquête" },
      { en: "Use a fiscal position to map taxes on answers", fr: "Utiliser une position fiscale pour mapper les taxes sur les réponses" },
      { en: "Lock the survey until a manufacturing order completes", fr: "Verrouiller l'enquête jusqu'à ce qu'un ordre de fabrication soit terminé" },
    ],
    explanation: { en: "Surveys support scored questions (single/multiple choice with points). You configure a passing score percentage; respondents see pass/fail and can be limited on retries depending on settings.\n\nWhy not \"Require a POS payment before the survey opens\"? POS payments are unrelated to survey scoring logic.\n\nWhy not \"Use a fiscal position to map taxes on answers\"? Fiscal positions remap taxes on transactions, not survey grades.\n\nWhy not \"Lock the survey until a manufacturing order completes\"? Manufacturing orders produce goods; they do not gate survey access.", fr: "Les enquêtes supportent des questions avec score (choix simple/multiple avec points). Vous configurez un pourcentage de passage ; les répondants voient réussi/échoué et peuvent être limités en tentatives selon les paramètres." },
  }),
  complexQ({
    id: "oep-105",
    module: "marketing",
    text: { en: "Which Surveys question type collects a matrix of ratings (rows vs columns) in Odoo 19?", fr: "Quel type de question d'Enquête collecte une matrice de notations (lignes vs colonnes) dans Odoo 19 ?" },
    correct: { en: "Matrix question type with row labels and column scale values", fr: "Type de question Matrice avec libellés de lignes et valeurs d'échelle en colonnes" },
    distractors: [
      { en: "Simple Textbox for one-line free text only", fr: "Zone de texte simple pour du texte libre sur une seule ligne uniquement" },
      { en: "Numerical Value with a single integer input", fr: "Valeur numérique avec une saisie d'entier unique" },
      { en: "File Upload for attaching a PDF response", fr: "Téléchargement de fichier pour joindre une réponse PDF" },
    ],
    explanation: { en: "The Matrix question type lets you define rows (statements) and columns (rating scale). Respondents pick one column per row, ideal for satisfaction grids or skills assessments.\n\nWhy not \"Simple Textbox for one-line free text only\"? Textbox captures a single text answer, not a row/column grid.\n\nWhy not \"Numerical Value with a single integer input\"? Numerical Value is one number, not a multi-row rating matrix.\n\nWhy not \"File Upload for attaching a PDF response\"? File Upload stores attachments; it does not render rating grids.", fr: "Le type de question Matrice permet de définir des lignes (affirmations) et des colonnes (échelle de notation). Les répondants choisissent une colonne par ligne, idéal pour les grilles de satisfaction ou les évaluations de compétences." },
  }),
  complexQ({
    id: "oep-106",
    module: "spreadsheet",
    text: { en: "A CFO wants a live inventory valuation pivot inside Odoo 19 without exporting to Excel. Which tool is designed for this?", fr: "Un directeur financier veut un tableau croisé dynamique de valorisation des stocks en direct dans Odoo 19 sans exporter vers Excel. Quel outil est conçu pour cela ?" },
    correct: { en: "Odoo Spreadsheet inserting a pivot/list from Inventory reporting data", fr: "Tableur Odoo insérant un tableau croisé/une liste depuis les données de reporting d'Inventaire" },
    distractors: [
      { en: "Sign module for PDF signature capture on stock counts", fr: "Module Sign pour la capture de signature PDF sur les comptages de stock" },
      { en: "POS closing journal for end-of-day cash differences", fr: "Journal de clôture PDV pour les écarts de caisse en fin de journée" },
      { en: "Discuss channel pinned messages for warehouse notes", fr: "Messages épinglés de canal Discuss pour les notes d'entrepôt" },
    ],
    explanation: { en: "Odoo Spreadsheet connects to live Odoo data. You insert pivots or lists from reports (e.g., stock valuation) and refresh values in place, optionally on dashboards.\n\nWhy not \"Sign module for PDF signature capture on stock counts\"? Sign handles signatures, not live analytical pivots.\n\nWhy not \"POS closing journal for end-of-day cash differences\"? POS session closing reconciles cash, not inventory valuation pivots.\n\nWhy not \"Discuss channel pinned messages for warehouse notes\"? Discuss stores chat messages, not spreadsheet analytics.", fr: "Le tableur Odoo se connecte aux données Odoo en direct. Vous insérez des tableaux croisés dynamiques ou des listes depuis les rapports (ex. : valorisation des stocks) et rafraîchissez les valeurs en place, éventuellement sur des tableaux de bord." },
  }),
  complexQ({
    id: "oep-107",
    module: "spreadsheet",
    text: { en: "In Odoo 19 Spreadsheet, what happens when you click \"Insert\" > \"List\" from a filtered sales report?", fr: "Dans le Tableur Odoo 19, que se passe-t-il lorsque vous cliquez sur « Insérer » > « Liste » depuis un rapport de ventes filtré ?" },
    correct: { en: "A linked list of records appears in the sheet and can refresh from live data", fr: "Une liste liée d'enregistrements apparaît dans la feuille et peut être rafraîchie depuis les données en direct" },
    distractors: [
      { en: "A static PNG screenshot is pasted with no data connection", fr: "Une capture d'écran PNG statique est collée sans connexion aux données" },
      { en: "A new sales order is created for each visible row", fr: "Un nouveau bon de commande est créé pour chaque ligne visible" },
      { en: "The underlying report filter is deleted permanently", fr: "Le filtre du rapport sous-jacent est supprimé définitivement" },
    ],
    explanation: { en: "Insert List pulls the current report dataset into the spreadsheet as a linked data region. Refresh updates figures when underlying transactions change, preserving filters defined at insert time.\n\nWhy not \"A static PNG screenshot is pasted with no data connection\"? Spreadsheet lists are data-linked, not static image captures.\n\nWhy not \"A new sales order is created for each visible row\"? Insert List does not create sales orders; it imports data for analysis.\n\nWhy not \"The underlying report filter is deleted permanently\"? Inserting a list does not delete the source report or its filters.", fr: "Insérer une Liste extrait le jeu de données du rapport actuel dans le tableur en tant que zone de données liée. Le rafraîchissement met à jour les chiffres lorsque les transactions sous-jacentes changent, en préservant les filtres définis à l'insertion." },
  }),
  complexQ({
    id: "oep-108",
    module: "spreadsheet",
    text: { en: "A manager pins a Spreadsheet dashboard to the Accounting app home screen in Odoo 19. What does this provide?", fr: "Un responsable épingle un tableau de bord Tableur sur l'écran d'accueil de l'application Comptabilité dans Odoo 19. Qu'est-ce que cela fournit ?" },
    correct: { en: "A shared live dashboard tile users open without rebuilding the sheet", fr: "Une tuile de tableau de bord en direct partagée que les utilisateurs ouvrent sans reconstruire la feuille" },
    distractors: [
      { en: "A one-time PDF export that never updates after publishing", fr: "Un export PDF ponctuel qui ne se met jamais à jour après publication" },
      { en: "A Studio custom model replacing account.move entirely", fr: "Un modèle personnalisé Studio remplaçant entièrement account.move" },
      { en: "A POS config for retail cash control only", fr: "Une configuration PDV pour le contrôle de caisse de détail uniquement" },
    ],
    explanation: { en: "Spreadsheet dashboards can be shared and pinned to app menus. Authorized users open the live dashboard with refreshed figures from connected Odoo data sources.\n\nWhy not \"A one-time PDF export that never updates after publishing\"? Dashboards remain linked to live data, unlike a static PDF snapshot.\n\nWhy not \"A Studio custom model replacing account.move entirely\"? Studio extends models; it does not replace account.move with a dashboard tile.\n\nWhy not \"A POS config for retail cash control only\"? POS config manages registers and payment methods, not spreadsheet dashboards.", fr: "Les tableaux de bord de tableur peuvent être partagés et épinglés aux menus d'applications. Les utilisateurs autorisés ouvrent le tableau de bord en direct avec des chiffres rafraîchis depuis les sources de données Odoo connectées." },
  }),
  complexQ({
    id: "oep-109",
    module: "spreadsheet",
    text: { en: "Which Odoo 19 app hosts collaborative internal playbooks with nested articles and @mentions?", fr: "Quelle application Odoo 19 héberge des guides collaboratifs internes avec des articles imbriqués et des @mentions ?" },
    correct: { en: "Knowledge with workspaces, articles, and permission levels", fr: "Knowledge avec espaces de travail, articles et niveaux de permission" },
    distractors: [
      { en: "Inventory > Operations > Transfers for stock pickings", fr: "Inventaire > Opérations > Transferts pour les bons de transfert de stock" },
      { en: "Purchase > RFQ list for vendor quotations", fr: "Achats > Liste des demandes de prix pour les devis fournisseurs" },
      { en: "Maintenance equipment records for work centers", fr: "Enregistrements d'équipement de maintenance pour les postes de charge" },
    ],
    explanation: { en: "Knowledge (Enterprise) provides workspaces, hierarchical articles, templates, and collaboration features like mentions and favorites. It is the wiki/playbook app referenced on the certification syllabus.\n\nWhy not \"Inventory > Operations > Transfers for stock pickings\"? Transfers move stock; they do not store collaborative documentation articles.\n\nWhy not \"Purchase > RFQ list for vendor quotations\"? RFQs negotiate vendor pricing, not internal knowledge bases.\n\nWhy not \"Maintenance equipment records for work centers\"? Maintenance tracks equipment reliability, not wiki-style playbooks.", fr: "Knowledge (Enterprise) fournit des espaces de travail, des articles hiérarchiques, des modèles et des fonctionnalités de collaboration comme les mentions et les favoris. C'est l'application wiki/guide référencée dans le programme de certification." },
  }),
  complexQ({
    id: "oep-110",
    module: "spreadsheet",
    text: { en: "A support lead links a Knowledge article to a Helpdesk ticket in Odoo 19. What is the typical purpose?", fr: "Un responsable support lie un article Knowledge à un ticket Helpdesk dans Odoo 19. Quel est le but typique ?" },
    correct: { en: "Give agents a vetted troubleshooting procedure without leaving the ticket", fr: "Donner aux agents une procédure de dépannage validée sans quitter le ticket" },
    distractors: [
      { en: "Post the ticket total to the general ledger as revenue", fr: "Comptabiliser le total du ticket dans le grand livre comme revenu" },
      { en: "Create a manufacturing order from the article BOM", fr: "Créer un ordre de fabrication à partir de la nomenclature de l'article" },
      { en: "Replace the customer portal quotation signature flow", fr: "Remplacer le flux de signature de devis du portail client" },
    ],
    explanation: { en: "Linking Knowledge articles to Helpdesk tickets surfaces standard operating procedures, policies, or FAQs inside the ticket form so agents follow consistent resolution steps.\n\nWhy not \"Post the ticket total to the general ledger as revenue\"? Helpdesk tickets are not posted as revenue journal entries by linking articles.\n\nWhy not \"Create a manufacturing order from the article BOM\"? Manufacturing orders come from BoMs, not Knowledge article links.\n\nWhy not \"Replace the customer portal quotation signature flow\"? Portal quotation signing is a Sales workflow unrelated to Helpdesk article links.", fr: "Lier des articles Knowledge aux tickets Helpdesk fait apparaître les procédures opérationnelles standard, politiques ou FAQ dans le formulaire du ticket afin que les agents suivent des étapes de résolution cohérentes." },
  }),
  complexQ({
    id: "oep-111",
    module: "crm",
    text: { en: "A sales order requires a 30% down payment before production starts in Odoo 19. Which invoicing policy supports this?", fr: "Un bon de commande nécessite un acompte de 30 % avant le début de la production dans Odoo 19. Quelle politique de facturation supporte cela ?" },
    correct: { en: "Down payment invoice from the sales order (percentage or fixed amount)", fr: "Facture d'acompte depuis le bon de commande (pourcentage ou montant fixe)" },
    distractors: [
      { en: "Invoice on delivery only with no deposit capability", fr: "Facturer à la livraison uniquement sans possibilité d'acompte" },
      { en: "Vendor bill three-way matching on the sales quotation", fr: "Rapprochement à 3 voies de la facture fournisseur sur le devis" },
      { en: "POS session cash difference posting at day end", fr: "Comptabilisation de l'écart de caisse de la session PDV en fin de journée" },
    ],
    explanation: { en: "Sales orders support down payment invoices (percentage or fixed). Odoo creates a deposit invoice, tracks the down payment on the SO, and deducts it from the final invoice.\n\nWhy not \"Invoice on delivery only with no deposit capability\"? Delivered-quantity invoicing bills after shipment, not an upfront deposit.\n\nWhy not \"Vendor bill three-way matching on the sales quotation\"? Three-way matching applies to vendor bills, not customer down payments.\n\nWhy not \"POS session cash difference posting at day end\"? POS cash differences reconcile registers; they are not sales deposits.", fr: "Les bons de commande supportent les factures d'acompte (pourcentage ou montant fixe). Odoo crée une facture d'acompte, suit l'acompte sur la commande et le déduit de la facture finale." },
  }),
  complexQ({
    id: "oep-112",
    module: "crm",
    text: { en: "A storable product should invoice when quantities are delivered, not when the order is confirmed. Where is this set in Odoo 19?", fr: "Un produit stockable doit être facturé lorsque les quantités sont livrées, pas lorsque la commande est confirmée. Où cela se paramètre-t-il dans Odoo 19 ?" },
    correct: { en: "Product invoicing policy: Ordered quantities vs Delivered quantities", fr: "Politique de facturation du produit : Quantités commandées vs Quantités livrées" },
    distractors: [
      { en: "Warehouse route Make-to-Order on the vendor pricelist", fr: "Route d'entrepôt Fabrication à la commande sur la liste de prix fournisseur" },
      { en: "Fiscal position mapping on the payment provider", fr: "Mapping de position fiscale sur le fournisseur de paiement" },
      { en: "POS config outstanding receipts account", fr: "Compte d'encaissements en attente de la configuration PDV" },
    ],
    explanation: { en: "On the product (or service), Invoicing Policy controls whether invoice lines follow ordered or delivered quantities. Delivered is standard for storable goods where revenue aligns with shipment.\n\nWhy not \"Warehouse route Make-to-Order on the vendor pricelist\"? MTO routes drive procurement linkage, not customer invoice timing.\n\nWhy not \"Fiscal position mapping on the payment provider\"? Fiscal positions remap taxes/accounts, not invoice-on-delivery policy.\n\nWhy not \"POS config outstanding receipts account\"? POS outstanding accounts handle register payments, not SO invoice policy.", fr: "Sur le produit (ou service), la politique de facturation contrôle si les lignes de facture suivent les quantités commandées ou livrées. « Livrées » est standard pour les biens stockables où le revenu s'aligne avec l'expédition." },
  }),
  complexQ({
    id: "oep-113",
    module: "crm",
    text: { en: "A sales team reuses a standard quotation layout with default sections and terms in Odoo 19. Which object stores this?", fr: "Une équipe commerciale réutilise une mise en page de devis standard avec des sections par défaut et des conditions dans Odoo 19. Quel objet stocke cela ?" },
    correct: { en: "Quotation Template (sale.order.template) applied on new quotations", fr: "Modèle de devis (sale.order.template) appliqué sur les nouveaux devis" },
    distractors: [
      { en: "Purchase Agreement blanket order for vendor tenders", fr: "Contrat d'achat (ordre ouvert) pour les appels d'offres fournisseurs" },
      { en: "mrp.bom kit explosion on delivery orders", fr: "Éclatement de nomenclature Kit mrp.bom sur les bons de livraison" },
      { en: "ir.cron scheduled action for mail queue", fr: "Action planifiée ir.cron pour la file d'attente des e-mails" },
    ],
    explanation: { en: "Quotation Templates define default lines, sections, terms, and optional products. Salespeople start from a template to speed quoting while keeping consistent structure and legal text.\n\nWhy not \"Purchase Agreement blanket order for vendor tenders\"? Blanket orders are purchase-side contracts with vendors, not sales quote layouts.\n\nWhy not \"mrp.bom kit explosion on delivery orders\"? Kit BoMs explode components on pickings, not quotation document structure.\n\nWhy not \"ir.cron scheduled action for mail queue\"? Scheduled actions run background jobs; they do not store quote layouts.", fr: "Les modèles de devis définissent les lignes par défaut, les sections, les conditions et les produits optionnels. Les commerciaux démarrent depuis un modèle pour accélérer l'établissement des devis tout en gardant une structure et un texte juridique cohérents." },
  }),
  complexQ({
    id: "oep-114",
    module: "crm",
    text: { en: "A consultant sells consulting hours in Days but stocks materials in Units. Which Odoo 19 feature manages both on one product catalog?", fr: "Un consultant vend des heures de conseil en Jours mais stocke des matériaux en Unités. Quelle fonctionnalité Odoo 19 gère les deux sur un même catalogue de produits ?" },
    correct: { en: "Units of Measure categories with conversion between related UoMs", fr: "Catégories d'unités de mesure avec conversion entre UdM apparentées" },
    distractors: [
      { en: "Separate databases per unit type with no shared products", fr: "Des bases de données séparées par type d'unité sans produits partagés" },
      { en: "POS-only UoM definitions unavailable to Sales orders", fr: "Des définitions d'UdM réservées au PDV non disponibles pour les bons de commande" },
      { en: "Analytic tags replacing all UoM configuration", fr: "Des étiquettes analytiques remplaçant toute la configuration d'UdM" },
    ],
    explanation: { en: "UoM categories group compatible units (Unit, Dozen, kg, Day, Hour). Products reference a base UoM; alternate UoMs convert within the category for sales, purchase, and inventory.\n\nWhy not \"Separate databases per unit type with no shared products\"? One Odoo database supports multiple UoM categories on a shared product catalog.\n\nWhy not \"POS-only UoM definitions unavailable to Sales orders\"? POS uses the same product UoM definitions as Sales and Inventory.\n\nWhy not \"Analytic tags replacing all UoM configuration\"? Analytic tags track dimensions; they do not replace unit-of-measure setup.", fr: "Les catégories d'UdM regroupent les unités compatibles (Unité, Douzaine, kg, Jour, Heure). Les produits référencent une UdM de base ; les UdM alternatives convertissent au sein de la catégorie pour les ventes, achats et inventaire." },
  }),
  complexQ({
    id: "oep-115",
    module: "project",
    text: { en: "A billable support ticket should auto-create a project task when confirmed in Odoo 19. Which linkage enables this?", fr: "Un ticket de support facturable doit créer automatiquement une tâche de projet lorsqu'il est confirmé dans Odoo 19. Quel lien permet cela ?" },
    correct: { en: "Helpdesk team/track settings", fr: "Paramètres de l'équipe Helpdesk/suivi" },
    distractors: [
      { en: "Inventory reordering rule on the ticket priority field", fr: "Règle de réapprovisionnement d'inventaire sur le champ priorité du ticket" },
      { en: "Vendor three-way matching on helpdesk SLA timers", fr: "Rapprochement à 3 voies fournisseur sur les chronomètres SLA Helpdesk" },
      { en: "POS restaurant course management on table orders", fr: "Gestion des plats du PDV restaurant sur les commandes de table" },
    ],
    explanation: { en: "Helpdesk can be configured to create project tasks (and timesheets) from tickets, tying support work to project profitability and billing. This is a standard Enterprise integration tested on the functional exam.\n\nWhy not \"Inventory reordering rule on the ticket priority field\"? Reordering rules replenish stock; they do not spawn helpdesk project tasks.\n\nWhy not \"Vendor three-way matching on helpdesk SLA timers\"? Three-way matching validates vendor bills against PO/receipts, not ticket SLAs.\n\nWhy not \"POS restaurant course management on table orders\"? Restaurant course management sequences kitchen meals, not helpdesk projects.", fr: "Helpdesk peut être configuré pour créer des tâches de projet (et des feuilles de temps) à partir des tickets, liant le travail de support à la rentabilité du projet et à la facturation. C'est une intégration Enterprise standard testée à l'examen fonctionnel." },
  }),
  complexQ({
    id: "oep-116",
    module: "project",
    text: { en: "Project managers compare planned hours on tasks against timesheet hours logged in Odoo 19. Which view highlights the gap?", fr: "Les chefs de projet comparent les heures planifiées sur les tâches aux heures de feuille de temps enregistrées dans Odoo 19. Quelle vue met en évidence l'écart ?" },
    correct: { en: "Project profitability / planned vs actual reporting on tasks and timesheets", fr: "Rentabilité du projet / reporting planifié vs réalisé sur les tâches et feuilles de temps" },
    distractors: [
      { en: "Aged receivable buckets by customer overdue days", fr: "Tranches de balance âgée clients par jours de retard client" },
      { en: "POS session cash difference report by payment method", fr: "Rapport d'écart de caisse de session PDV par méthode de paiement" },
      { en: "Tax grid report mapping to statutory return boxes", fr: "Rapport de grille de taxe mappant vers les cases de déclaration légale" },
    ],
    explanation: { en: "Project reporting compares allocated/planned hours on tasks to timesheet entries actually logged. Variance feeds utilization and profitability analysis alongside billed amounts.\n\nWhy not \"Aged receivable buckets by customer overdue days\"? Aged receivable tracks customer balances, not project hour variance.\n\nWhy not \"POS session cash difference report by payment method\"? POS cash difference reconciles registers, not project planning hours.\n\nWhy not \"Tax grid report mapping to statutory return boxes\"? Tax grids populate VAT returns, unrelated to project hour tracking.", fr: "Le reporting de projet compare les heures allouées/planifiées sur les tâches aux écritures de feuille de temps réellement enregistrées. L'écart alimente l'analyse d'utilisation et de rentabilité aux côtés des montants facturés." },
  }),
  complexQ({
    id: "oep-117",
    module: "project",
    text: { en: "A service product is configured to create a project and task on sales order confirmation in Odoo 19. Which product setting drives this?", fr: "Un produit de service est configuré pour créer un projet et une tâche à la confirmation du bon de commande dans Odoo 19. Quel paramètre du produit pilote cela ?" },
    correct: { en: "Service tracking: Create a task in an existing project or new project", fr: "Suivi de service : Créer une tâche dans un projet existant ou un nouveau projet" },
    distractors: [
      { en: "Inventory route Dropship on the product category", fr: "Route d'inventaire Livraison directe sur la catégorie de produit" },
      { en: "BoM type Kit on the product template", fr: "Type de nomenclature Kit sur le modèle de produit" },
      { en: "POS config payment method outstanding account", fr: "Compte en attente de la méthode de paiement PDV" },
    ],
    explanation: { en: "On service products, Service Tracking defines whether confirming an SO creates a project, a task, or only timesheet entries. This links Sales to Project delivery automatically.\n\nWhy not \"Inventory route Dropship on the product category\"? Dropship routes vendor-to-customer fulfillment, not project task creation.\n\nWhy not \"BoM type Kit on the product template\"? Kit BoMs explode components on deliveries, not service project tasks.\n\nWhy not \"POS config payment method outstanding account\"? POS payment methods handle register tenders, not SO service tracking.", fr: "Sur les produits de service, le suivi de service définit si la confirmation d'une commande crée un projet, une tâche ou uniquement des écritures de feuille de temps. Cela lie automatiquement les Ventes à la livraison de Projet." },
  }),
  complexQ({
    id: "oep-118",
    module: "pos",
    text: { en: "A retailer enables loyalty points redeemable on future POS orders in Odoo 19. Where is this configured?", fr: "Un détaillant active des points de fidélité échangeables sur de futures commandes PDV dans Odoo 19. Où cela se configure-t-il ?" },
    correct: { en: "POS > Configuration > Loyalty Programs with rules and rewards", fr: "PDV > Configuration > Programmes de fidélité avec règles et récompenses" },
    distractors: [
      { en: "Purchase > Vendor pricelist minimum quantity tiers", fr: "Achats > Paliers de quantité minimum de la liste de prix fournisseur" },
      { en: "Accounting > Asset models for depreciation schedules", fr: "Comptabilité > Modèles d'immobilisations pour les plans d'amortissement" },
      { en: "MRP > Work center capacity calendars only", fr: "Fabrication > Calendriers de capacité des postes de charge uniquement" },
    ],
    explanation: { en: "POS Loyalty Programs define accrual rules (per order, per product) and rewards (discount, free product, points). Programs attach to POS configs and can integrate with eCommerce loyalty in omnichannel setups.\n\nWhy not \"Purchase > Vendor pricelist minimum quantity tiers\"? Vendor pricelists negotiate purchase pricing, not customer loyalty points.\n\nWhy not \"Accounting > Asset models for depreciation schedules\"? Asset models post depreciation entries, unrelated to POS loyalty.\n\nWhy not \"MRP > Work center capacity calendars only\"? Work center calendars schedule manufacturing capacity, not retail loyalty.", fr: "Les programmes de fidélité PDV définissent des règles d'accumulation (par commande, par produit) et des récompenses (remise, produit gratuit, points). Les programmes sont attachés aux configurations PDV et peuvent s'intégrer à la fidélité eCommerce en omnicanal." },
  }),
  complexQ({
    id: "oep-119",
    module: "pos",
    text: { en: "A customer pays a café bill with cash and card on one Odoo 19 POS order. Which feature supports this?", fr: "Un client paie une addition de café avec de l'argent liquide et une carte sur une même commande PDV Odoo 19. Quelle fonctionnalité supporte cela ?" },
    correct: { en: "Split payment / multiple payment methods on the same order", fr: "Paiement fractionné / plusieurs méthodes de paiement sur la même commande" },
    distractors: [
      { en: "Single payment method locked per POS config session", fr: "Méthode de paiement unique verrouillée par session de configuration PDV" },
      { en: "Vendor bill three-way matching on the receipt", fr: "Rapprochement à 3 voies de facture fournisseur sur le reçu" },
      { en: "Manufacturing order component consumption only", fr: "Consommation de composants d'ordre de fabrication uniquement" },
    ],
    explanation: { en: "POS allows multiple payments on one order (split tender). Each line posts to its payment method/journal while the order total is fully paid before validation.\n\nWhy not \"Single payment method locked per POS config session\"? POS configs can enable several payment methods; split tender is supported.\n\nWhy not \"Vendor bill three-way matching on the receipt\"? Three-way matching is an accounts payable control, not POS checkout.\n\nWhy not \"Manufacturing order component consumption only\"? MO component consumption is manufacturing inventory, not split POS payment.", fr: "Le PDV permet plusieurs paiements sur une même commande (paiement fractionné). Chaque ligne est comptabilisée dans sa méthode de paiement/journal pendant que le total de la commande est entièrement réglé avant validation." },
  }),
  complexQ({
    id: "oep-120",
    module: "purchases",
    text: { en: "A buyer should be billed for received quantities only, not the full PO amount ordered. Which Purchase setting controls this in Odoo 19?", fr: "Un acheteur ne doit être facturé que pour les quantités reçues, pas pour le montant total commandé. Quel paramètre d'Achats contrôle cela dans Odoo 19 ?" },
    correct: { en: "Bill Control: Received quantities vs Ordered quantities on the product/category", fr: "Contrôle de facturation : Quantités reçues vs Quantités commandées sur le produit/catégorie" },
    distractors: [
      { en: "Inventory valuation FIFO vs AVCO on the warehouse", fr: "Valorisation d'inventaire FIFO vs CMUP sur l'entrepôt" },
      { en: "CRM pipeline stage probability percentages", fr: "Pourcentages de probabilité d'étape du pipeline CRM" },
      { en: "Website snippet animation on the homepage hero block", fr: "Animation de snippet site web sur le bloc héros de la page d'accueil" },
    ],
    explanation: { en: "Bill Control on products/categories determines whether vendor bills default to ordered or received quantities. Received is common when payment follows physical receipt and three-way matching.\n\nWhy not \"Inventory valuation FIFO vs AVCO on the warehouse\"? Valuation methods affect inventory cost, not vendor bill quantity basis.\n\nWhy not \"CRM pipeline stage probability percentages\"? Pipeline probability forecasts deals, not purchase billing policy.\n\nWhy not \"Website snippet animation on the homepage hero block\"? Website snippets control page design, not purchase bill control.", fr: "Le contrôle de facturation sur les produits/catégories détermine si les factures fournisseur utilisent par défaut les quantités commandées ou reçues. « Reçues » est courant lorsque le paiement suit la réception physique et le rapprochement à 3 voies." },
  }),
  complexQ({
    id: "oep-121",
    module: "purchases",
    text: { en: "A company negotiates a year-long unit price with one vendor for recurring purchases in Odoo 19. Which Purchase object fits this?", fr: "Une entreprise négocie un prix unitaire annuel avec un seul fournisseur pour des achats récurrents dans Odoo 19. Quel objet d'Achats correspond ?" },
    correct: { en: "Blanket Purchase Agreement with agreed terms and call-off POs", fr: "Contrat d'achat ouvert avec conditions convenues et bons de commande d'appel" },
    distractors: [
      { en: "Kit BoM exploding components on customer deliveries", fr: "Nomenclature Kit éclatant les composants sur les livraisons client" },
      { en: "POS loyalty reward granting discount points", fr: "Récompense de fidélité PDV accordant des points de remise" },
      { en: "Survey matrix question with row and column labels", fr: "Question matrice d'enquête avec libellés de lignes et colonnes" },
    ],
    explanation: { en: "Blanket Orders (Purchase Agreements type Blanket) set negotiated terms, validity, and pricing with a vendor. Users create call-off POs against the blanket until quantity or date limits are reached.\n\nWhy not \"Kit BoM exploding components on customer deliveries\"? Kit BoMs bundle sellable products; they are not vendor blanket contracts.\n\nWhy not \"POS loyalty reward granting discount points\"? POS loyalty manages customer rewards, not vendor pricing agreements.\n\nWhy not \"Survey matrix question with row and column labels\"? Survey matrix questions collect responses, not purchase contract terms.", fr: "Les ordres ouverts (Contrats d'achat de type Ordre ouvert) définissent les conditions négociées, la validité et les prix avec un fournisseur. Les utilisateurs créent des bons de commande d'appel contre l'ordre ouvert jusqu'à ce que les limites de quantité ou de date soient atteintes." },
  }),
  complexQ({
    id: "oep-122",
    module: "inventory",
    text: { en: "Fast-moving SKUs should land in aisle bins automatically on receipt in Odoo 19. Which feature directs putaway?", fr: "Les références à rotation rapide doivent atterrir automatiquement dans les casiers d'allée à la réception dans Odoo 19. Quelle fonctionnalité dirige le rangement ?" },
    correct: { en: "Putaway rules mapping product/category to destination sub-locations", fr: "Règles de rangement associant le produit/catégorie aux sous-emplacements de destination" },
    distractors: [
      { en: "Fiscal positions remapping tax accounts by customer country", fr: "Positions fiscales remappant les comptes de taxe par pays client" },
      { en: "Email Marketing A/B tests on campaign subject lines", fr: "Tests A/B d'Email Marketing sur les objets de campagne" },
      { en: "HR appraisal templates for annual performance reviews", fr: "Modèles d'évaluation RH pour les revues annuelles de performance" },
    ],
    explanation: { en: "Putaway rules (stock.putaway.rule) assign incoming products to specific sub-locations based on product, category, or storage category. They require Storage Locations enabled on the warehouse.\n\nWhy not \"Fiscal positions remapping tax accounts by customer country\"? Fiscal positions change taxes/accounts, not physical bin putaway.\n\nWhy not \"Email Marketing A/B tests on campaign subject lines\"? Email A/B tests optimize campaigns, not warehouse slotting.\n\nWhy not \"HR appraisal templates for annual performance reviews\"? Appraisal templates evaluate employees, not inventory locations.", fr: "Les règles de rangement (stock.putaway.rule) assignent les produits entrants à des sous-emplacements spécifiques en fonction du produit, de la catégorie ou de la catégorie de stockage. Elles nécessitent l'activation des emplacements de stockage sur l'entrepôt." },
  }),
  complexQ({
    id: "oep-123",
    module: "inventory",
    text: { en: "Warehouse A runs low on stock and should pull replenishment from Warehouse B in Odoo 19. What enables this?", fr: "L'entrepôt A est en rupture de stock et doit tirer le réapprovisionnement de l'entrepôt B dans Odoo 19. Qu'est-ce qui active cela ?" },
    correct: { en: "Resupply from another warehouse configured on the warehouse record", fr: "Réapprovisionnement depuis un autre entrepôt configuré sur la fiche entrepôt" },
    distractors: [
      { en: "POS split payment across cash and card on one receipt", fr: "Paiement fractionné PDV entre espèces et carte sur un même reçu" },
      { en: "Deferred revenue schedule on a SaaS subscription invoice", fr: "Planning de produits constatés d'avance sur une facture d'abonnement SaaS" },
      { en: "Knowledge article @mentions in internal playbooks", fr: "@mentions d'articles Knowledge dans les guides internes" },
    ],
    explanation: { en: "Multi-warehouse setups can define resupply routes between warehouses. Reordering rules on the destination warehouse can trigger inter-warehouse transfers or procurements from the supplying warehouse.\n\nWhy not \"POS split payment across cash and card on one receipt\"? Split POS payments settle customer tenders, not inter-warehouse replenishment.\n\nWhy not \"Deferred revenue schedule on a SaaS subscription invoice\"? Deferred revenue spreads recognition over time, unrelated to stock resupply.\n\nWhy not \"Knowledge article @mentions in internal playbooks\"? Knowledge mentions collaborate on docs; they do not move inventory.", fr: "Les configurations multi-entrepôts peuvent définir des routes de réapprovisionnement entre entrepôts. Les règles de réapprovisionnement sur l'entrepôt de destination peuvent déclencher des transferts inter-entrepôts ou des approvisionnements depuis l'entrepôt fournisseur." },
  }),
  complexQ({
    id: "oep-124",
    module: "mrp",
    text: { en: "A planner uses Odoo 19 to forecast finished goods demand and propose manufacturing/purchase orders. Which app supports this?", fr: "Un planificateur utilise Odoo 19 pour prévoir la demande de produits finis et proposer des ordres de fabrication/achat. Quelle application supporte cela ?" },
    correct: { en: "Master Production Schedule (MPS) in Manufacturing planning views", fr: "Plan Directeur de Production (PDP) dans les vues de planification Fabrication" },
    distractors: [
      { en: "Email Marketing mass mailing A/B winner selection", fr: "Sélection du gagnant du test A/B de publipostage Email Marketing" },
      { en: "Website abandoned cart recovery automation emails", fr: "E-mails d'automatisation de récupération de panier abandonné du site web" },
      { en: "Sign document signature request on vendor contracts", fr: "Demande de signature Sign sur les contrats fournisseurs" },
    ],
    explanation: { en: "MPS lets planners enter demand forecasts by product/period and generates proposed MOs/RFQs after comparing forecast, on-hand, and incoming supply. It is part of the Manufacturing planning toolkit on the exam.\n\nWhy not \"Email Marketing mass mailing A/B winner selection\"? Email A/B tests optimize campaigns, not production/material planning.\n\nWhy not \"Website abandoned cart recovery automation emails\"? Abandoned cart emails recover eCommerce sales, not MRP forecasts.\n\nWhy not \"Sign document signature request on vendor contracts\"? Sign collects signatures; it does not schedule manufacturing proposals.", fr: "Le PDP permet aux planificateurs de saisir des prévisions de demande par produit/période et génère des OF/demandes de prix proposés après comparaison entre prévision, stock en main et approvisionnements entrants. Il fait partie de la boîte à outils de planification Fabrication à l'examen." },
  }),
  complexQ({
    id: "oep-125",
    module: "accounting",
    text: { en: "A SaaS vendor must spread annual subscription revenue across 12 months in Odoo 19. Which Accounting feature handles this?", fr: "Un fournisseur SaaS doit étaler le revenu d'abonnement annuel sur 12 mois dans Odoo 19. Quelle fonctionnalité comptable gère cela ?" },
    correct: { en: "Deferred revenue models generating periodic recognition entries", fr: "Modèles de produits constatés d'avance générant des écritures de reconnaissance périodiques" },
    distractors: [
      { en: "POS cash over/short difference account on session close", fr: "Compte d'écart de caisse en surplus/déficit PDV à la clôture de session" },
      { en: "Inventory consignment owner field on stock moves", fr: "Champ propriétaire de consignation d'inventaire sur les mouvements de stock" },
      { en: "CRM lead assignment round-robin on sales teams", fr: "Attribution de pistes CRM en tourniquet sur les équipes commerciales" },
    ],
    explanation: { en: "Deferred Revenue (and Deferred Expense) models create an initial balance sheet entry on invoice and auto-post periodic recognition entries to income over the defined duration.\n\nWhy not \"POS cash over/short difference account on session close\"? POS cash differences reconcile registers, not subscription revenue timing.\n\nWhy not \"Inventory consignment owner field on stock moves\"? Consignment tracks vendor-owned stock, not revenue deferral schedules.\n\nWhy not \"CRM lead assignment round-robin on sales teams\"? Lead assignment distributes CRM records, unrelated to deferred revenue.", fr: "Les produits constatés d'avance (et les charges constatées d'avance) créent une écriture initiale au bilan à la facturation et comptabilisent automatiquement des écritures de reconnaissance périodiques en produits sur la durée définie." },
  }),
  complexQ({
    id: "oep-126",
    module: "hr",
    text: { en: "HR wants structured annual reviews with goals and manager feedback in Odoo 19. Which module provides this?", fr: "La RH veut des revues annuelles structurées avec objectifs et retour du responsable dans Odoo 19. Quel module fournit cela ?" },
    correct: { en: "Appraisals with templates, schedules, and employee/manager surveys", fr: "Évaluations avec modèles, plannings et enquêtes employé/responsable" },
    distractors: [
      { en: "Barcode app scanning pickings on the warehouse floor", fr: "Application Code-barres scannant les transferts sur le sol de l'entrepôt" },
      { en: "Purchase Calls for Tender comparing vendor RFQ responses", fr: "Appels d'offres d'achat comparant les réponses de demandes de prix fournisseurs" },
      { en: "Website SEO metadata fields on product pages", fr: "Champs de métadonnées SEO du site web sur les pages produits" },
    ],
    explanation: { en: "Appraisals lets HR define review cycles, templates, goals, and 360° feedback. Completed appraisals attach to employee records and can trigger follow-up activities.\n\nWhy not \"Barcode app scanning pickings on the warehouse floor\"? Barcode operations execute warehouse transfers, not performance reviews.\n\nWhy not \"Purchase Calls for Tender comparing vendor RFQ responses\"? Purchase tenders compare vendor quotes, not employee appraisals.\n\nWhy not \"Website SEO metadata fields on product pages\"? Website SEO fields optimize search snippets, unrelated to HR reviews.", fr: "Les Évaluations permettent à la RH de définir des cycles d'évaluation, des modèles, des objectifs et du feedback 360°. Les évaluations complétées sont attachées aux fiches employés et peuvent déclencher des activités de suivi." },
  }),
  complexQ({
    id: "oep-127",
    module: "hr",
    text: { en: "An employee contract references standard 40-hour weeks with two days off in Odoo 19. Which object defines working hours?", fr: "Un contrat employé référence une semaine standard de 40 heures avec deux jours de repos dans Odoo 19. Quel objet définit les heures de travail ?" },
    correct: { en: "Working Schedule (resource.calendar) linked on hr.contract", fr: "Horaire de travail (resource.calendar) lié sur hr.contract" },
    distractors: [
      { en: "POS payment method outstanding receipts account", fr: "Compte d'encaissements en attente de la méthode de paiement PDV" },
      { en: "Stock putaway rule destination sub-location", fr: "Sous-emplacement de destination de la règle de rangement en stock" },
      { en: "Survey passing score percentage threshold", fr: "Seuil de pourcentage de score de passage d'enquête" },
    ],
    explanation: { en: "resource.calendar defines working hours, breaks, and time zones. Contracts link a working schedule used by Attendances, Planning, and Payroll to compute expected vs actual time.\n\nWhy not \"POS payment method outstanding receipts account\"? POS outstanding accounts handle register payments, not employee work hours.\n\nWhy not \"Stock putaway rule destination sub-location\"? Putaway rules direct products to bins, not employee weekly schedules.\n\nWhy not \"Survey passing score percentage threshold\"? Survey passing scores grade respondents, unrelated to working time calendars.", fr: "resource.calendar définit les heures de travail, les pauses et les fuseaux horaires. Les contrats lient un horaire de travail utilisé par Pointage, Planification et Paie pour calculer le temps attendu vs réel." },
  }),
  complexQ({
    id: "oep-128",
    module: "studio",
    text: { en: "A functional consultant restricts sales users to opportunities in their own country using Odoo 19 security. Which mechanism applies the filter?", fr: "Un consultant fonctionnel restreint les utilisateurs commerciaux aux opportunités de leur propre pays en utilisant la sécurité Odoo 19. Quel mécanisme applique le filtre ?" },
    correct: { en: "Record rule (ir.rule) domain on crm.lead scoped to the user group", fr: "Règle d'enregistrement (ir.rule) avec domaine sur crm.lead rattachée au groupe d'utilisateurs" },
    distractors: [
      { en: "Email template QWeb placeholder replacing merge fields", fr: "Champ dynamique de fusion de template d'e-mail QWeb" },
      { en: "Inventory AVCO average cost recalculation on receipts", fr: "Recalcul du coût moyen CMUP d'inventaire sur les réceptions" },
      { en: "Website snippet drag-and-drop block layout editor", fr: "Éditeur de disposition de blocs glisser-déposer de snippets du site web" },
    ],
    explanation: { en: "Record rules add domain filters per model and security group (e.g., country_id = user country). Combined with access rights, they constrain which records users can read or write.\n\nWhy not \"Email template QWeb placeholder replacing merge fields\"? Email templates format outbound messages; they do not enforce record-level security.\n\nWhy not \"Inventory AVCO average cost recalculation on receipts\"? AVCO valuation recalculates inventory cost, unrelated to CRM record access.\n\nWhy not \"Website snippet drag-and-drop block layout editor\"? Website snippets design pages; they do not filter CRM opportunity records.", fr: "Les règles d'enregistrement ajoutent des filtres de domaine par modèle et groupe de sécurité (ex. : country_id = pays de l'utilisateur). Combinées aux droits d'accès, elles restreignent quels enregistrements les utilisateurs peuvent lire ou écrire." },
  }),
  complexQ({
    id: "oep-129",
    module: "studio",
    text: { en: "A consultant must inspect model fields and XML views while troubleshooting in Odoo 19. What must be enabled first?", fr: "Un consultant doit inspecter les champs d'un modèle et les vues XML lors du dépannage dans Odoo 19. Que faut-il activer en premier ?" },
    correct: { en: "Developer mode (debug assets) from Settings or the user menu", fr: "Mode développeur (debug assets) depuis les Paramètres ou le menu utilisateur" },
    distractors: [
      { en: "POS restaurant floor plan and table management", fr: "Plan de salle restaurant PDV et gestion des tables" },
      { en: "Manufacturing subcontracting resupply route on the BoM", fr: "Route de sous-traitance avec réapprovisionnement sur la nomenclature de Fabrication" },
      { en: "Survey matrix question with weighted scoring columns", fr: "Question matrice d'enquête avec colonnes de scoring pondéré" },
    ],
    explanation: { en: "Developer mode exposes technical menus, view metadata, field names, and automated action definitions. It is required for advanced configuration and is part of the Studio/customization domain on the exam.\n\nWhy not \"POS restaurant floor plan and table management\"? Restaurant floor plans configure table service POS, not technical debugging tools.\n\nWhy not \"Manufacturing subcontracting resupply route on the BoM\"? Subcontracting routes vendor manufacturing; they do not enable developer menus.\n\nWhy not \"Survey matrix question with weighted scoring columns\"? Survey matrix questions collect responses, unrelated to debug mode.", fr: "Le mode développeur expose les menus techniques, les métadonnées de vue, les noms de champs et les définitions d'actions automatisées. Il est nécessaire pour la configuration avancée et fait partie du domaine Studio/personnalisation à l'examen." },
  }),
  complexQ({
    id: "oep-130",
    module: "studio",
    text: { en: "When importing partners from a legacy system into Odoo 19, which column preserves relationships for later updates?", fr: "Lors de l'importation de partenaires depuis un système existant dans Odoo 19, quelle colonne préserve les relations pour les mises à jour ultérieures ?" },
    correct: { en: "External ID (id column) using module.name syntax in the import file", fr: "ID externe (colonne id) utilisant la syntaxe module.name dans le fichier d'import" },
    distractors: [
      { en: "POS session name generated at register opening", fr: "Nom de session PDV généré à l'ouverture de la caisse" },
      { en: "Tax grid code on the statutory VAT return form", fr: "Code de grille de taxe sur le formulaire de déclaration de TVA légale" },
      { en: "Work center OEE efficiency percentage field", fr: "Champ de pourcentage d'efficacité TRS du poste de charge" },
    ],
    explanation: { en: "Odoo imports use External IDs (XML IDs) in the id column (e.g., __import__.legacy_partner_001) so re-imports update the same res.partner instead of creating duplicates. This is standard go-live/data migration practice.\n\nWhy not \"POS session name generated at register opening\"? POS session names identify register shifts, not import record keys.\n\nWhy not \"Tax grid code on the statutory VAT return form\"? Tax grid codes map VAT boxes, not CSV import identity for partners.\n\nWhy not \"Work center OEE efficiency percentage field\"? Work center OEE tracks equipment performance, unrelated to data import IDs.", fr: "Les imports Odoo utilisent des ID externes (XML IDs) dans la colonne id (ex. : __import__.legacy_partner_001) afin que les ré-importations mettent à jour le même res.partner au lieu de créer des doublons. C'est une pratique standard de mise en production/migration de données." },
  }),
  complexQ({
    id: "oep-131",
    module: "crm",
    text: { en: "A CRM manager wants lost reasons captured when an opportunity is marked Lost in Odoo 19. Where is this configured?", fr: "Un responsable CRM veut que les motifs de perte soient capturés lorsqu'une opportunité est marquée Perdue dans Odoo 19. Où cela se configure-t-il ?" },
    correct: { en: "CRM > Configuration > Lost Reasons, then select one when marking Lost", fr: "CRM > Configuration > Motifs de perte, puis en sélectionner un lors du marquage Perdu" },
    distractors: [
      { en: "Inventory > Routes > Make-to-Order on the opportunity product", fr: "Inventaire > Routes > Fabrication à la commande sur le produit de l'opportunité" },
      { en: "Accounting > Lock Dates on the company fiscal period settings", fr: "Comptabilité > Dates de verrouillage sur les paramètres de période fiscale de la société" },
      { en: "POS > Payment Methods outstanding receipts account mapping", fr: "PDV > Mapping du compte d'encaissements en attente des méthodes de paiement" },
    ],
    explanation: { en: "Lost Reasons are maintained under CRM configuration. When a salesperson marks an opportunity Lost, they pick a reason, enabling pipeline analytics on why deals fail.\n\nWhy not \"Inventory > Routes > Make-to-Order on the opportunity product\"? MTO routes drive procurement; they do not record why a CRM deal was lost.\n\nWhy not \"Accounting > Lock Dates on the company fiscal period settings\"? Lock dates prevent editing past accounting entries, unrelated to CRM loss reasons.\n\nWhy not \"POS > Payment Methods outstanding receipts account mapping\"? POS payment methods handle register tenders, not opportunity loss tracking.", fr: "Les motifs de perte sont maintenus dans la configuration CRM. Lorsqu'un commercial marque une opportunité comme Perdue, il choisit un motif, permettant l'analyse du pipeline sur les raisons d'échec des affaires." },
  }),
  complexQ({
    id: "oep-132",
    module: "crm",
    text: { en: "An opportunity reaches the Won stage in Odoo 19 CRM. What is the typical next step to bill the customer?", fr: "Une opportunité atteint l'étape Gagnée dans le CRM Odoo 19. Quelle est l'étape suivante typique pour facturer le client ?" },
    correct: { en: "Create a quotation or sales order from the opportunity and confirm invoicing flow", fr: "Créer un devis ou un bon de commande depuis l'opportunité et confirmer le flux de facturation" },
    distractors: [
      { en: "Post a vendor bill directly from the opportunity kanban card", fr: "Comptabiliser une facture fournisseur directement depuis la carte kanban de l'opportunité" },
      { en: "Run the MRP scheduler to replenish components from the pipeline stage", fr: "Exécuter le planificateur MRP pour réapprovisionner les composants depuis l'étape du pipeline" },
      { en: "Open a POS session and scan the opportunity barcode at checkout", fr: "Ouvrir une session PDV et scanner le code-barres de l'opportunité au passage en caisse" },
    ],
    explanation: { en: "Winning an opportunity usually converts to a quotation or sales order (New Quotation button). From the confirmed SO, delivery and customer invoicing follow the product invoicing policy.\n\nWhy not \"Post a vendor bill directly from the opportunity kanban card\"? Vendor bills are accounts payable documents, not created from won CRM deals.\n\nWhy not \"Run the MRP scheduler to replenish components from the pipeline stage\"? The MRP scheduler processes stock rules, not customer billing from CRM wins.\n\nWhy not \"Open a POS session and scan the opportunity barcode at checkout\"? POS sessions sell at retail registers; CRM opportunities are not POS transactions.", fr: "Gagner une opportunité mène généralement à la conversion en devis ou bon de commande (bouton Nouveau devis). Depuis la commande confirmée, la livraison et la facturation client suivent la politique de facturation du produit." },
  }),
  complexQ({
    id: "oep-133",
    module: "crm",
    text: { en: "A sales team uses predictive lead scoring in Odoo 19 CRM. What data primarily feeds the score?", fr: "Une équipe commerciale utilise le scoring prédictif des pistes dans le CRM Odoo 19. Quelles données alimentent principalement le score ?" },
    correct: { en: "Historical won/lost patterns and lead field values used by the scoring model", fr: "Les modèles historiques gagné/perdu et les valeurs des champs de la piste utilisés par le modèle de scoring" },
    distractors: [
      { en: "Warehouse on-hand quantity from stock quants per product variant", fr: "La quantité en stock de l'entrepôt depuis les quants de stock par variante de produit" },
      { en: "Bank statement reconciliation model regex rules on memo text", fr: "Les règles regex du modèle de lettrage de relevé bancaire sur le texte du mémo" },
      { en: "Manufacturing work center OEE downtime percentages per shift", fr: "Les pourcentages de temps d'arrêt TRS du poste de charge de fabrication par poste" },
    ],
    explanation: { en: "Predictive lead scoring (where enabled) learns from past opportunities—fields like country, industry, source, and stage outcomes—to rank new leads by likelihood to convert.\n\nWhy not \"Warehouse on-hand quantity from stock quants per product variant\"? Stock on-hand drives inventory replenishment, not CRM predictive lead scores.\n\nWhy not \"Bank statement reconciliation model regex rules on memo text\"? Reconciliation models match bank lines, unrelated to lead scoring algorithms.\n\nWhy not \"Manufacturing work center OEE downtime percentages per shift\"? Work center OEE tracks equipment efficiency, not CRM lead probability.", fr: "Le scoring prédictif des pistes (lorsqu'il est activé) apprend des opportunités passées — champs comme le pays, le secteur, la source et les résultats d'étape — pour classer les nouvelles pistes par probabilité de conversion." },
  }),
];
